//! HTJ2K block coding boundary.
//!
//! This crate owns HT block decoding for the milestone Part 15 subset and
//! explicit unsupported-case reporting for unimplemented HT modes. HTJ2K encode
//! APIs are out of scope for the first milestone.

extern crate alloc;

use core::{fmt, ops::Range};

mod block_encoder;
#[cfg(feature = "std")]
#[path = "openjph_fast_cleanup.rs"]
mod fast_cleanup;
mod ht_vlc_tables;
mod openjph_decoder;

use openjph_decoder::cleanup_bitplane_from_missing_msbs;

pub use block_encoder::{HtCleanupEncodeError, HtCleanupEncodedBlock, encode_ht_cleanup_block};

pub use ht_vlc_tables::{
    HT_VLC_TABLE_PROVENANCE, HtVlcStandardTableKind, HtVlcTableProvenance,
    ht_vlc_initial_lookup_table, ht_vlc_noninitial_lookup_table, ht_vlc_standard_lookup_table,
};

/// Marker-level HTJ2K support class reported by the HT boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtSupportClass {
    /// Input appears to be in the marker-level milestone subset and requires
    /// code-block decode to determine whether it is implemented.
    Candidate,
    /// Input is known to be outside the implemented subset.
    Unsupported,
    /// Input cannot be classified from available marker state.
    Unknown,
}

/// Narrow marker summary needed by the HT block-coder boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtMarkerState {
    pub has_cap_marker: bool,
    pub components: u16,
    pub sample_precision_bits: u8,
    pub all_components_same_sample_format: bool,
    pub all_components_unit_sampled: bool,
    /// Whether the caller observed exactly one tile. Tile-grid validation and
    /// stitching remain the codestream layer's responsibility.
    pub single_tile: bool,
    pub has_tile_part: bool,
    pub packet_progression_supported: bool,
    pub reversible_transform: bool,
    /// Whether COD permits SOP markers. The codestream layer remains
    /// responsible for validating each marker at a packet boundary.
    pub sop_markers: bool,
    /// Whether COD requires EPH markers. The codestream layer remains
    /// responsible for validating each marker at a packet-header boundary.
    pub eph_markers: bool,
    pub precincts_declared: bool,
    pub code_block_width: Option<u16>,
    pub code_block_height: Option<u16>,
}

/// HT classification detail that can be surfaced as a structured unsupported
/// reason by the codestream layer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtClassification {
    pub class: HtSupportClass,
    pub reason: HtUnsupportedReason,
}

/// Marker-derived HT decode candidate state after subset classification and
/// block-geometry validation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtDecodeCandidate {
    components: u16,
    sample_precision_bits: u8,
    block: HtBlockLayout,
}

impl HtDecodeCandidate {
    /// Number of image components admitted by the milestone HT decode subset.
    pub fn components(self) -> u16 {
        self.components
    }

    /// Component sample precision admitted by the milestone HT decode subset.
    pub fn sample_precision_bits(self) -> u8 {
        self.sample_precision_bits
    }

    /// Validated HT block layout carried forward from marker state.
    pub fn block(self) -> HtBlockLayout {
        self.block
    }
}

/// Stable reason codes for HTJ2K modes that are outside the first milestone.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtUnsupportedReason {
    /// No CAP marker was available, so the input cannot be classified as HTJ2K.
    MissingCapabilityMarker,
    /// The component count is outside the implemented grayscale/RGB subset.
    ComponentCount,
    /// Component sample precision or format agreement is outside the subset.
    SamplePrecision,
    /// Component subsampling is not implemented by the current HT path.
    ComponentSampling,
    /// The caller does not support the codestream's tile grid.
    MultipleTiles,
    /// A tile-part payload is required before decode can be enabled.
    MissingTilePart,
    /// The packet progression is outside the profile admitted by the caller.
    ProgressionOrder,
    /// Only reversible 5/3 is in the first candidate set.
    WaveletTransform,
    /// Legacy packet-marker gate retained for stable reason-code compatibility.
    /// Current candidates validate SOP/EPH in the codestream packet walker.
    PacketMarkers,
    /// Custom precinct partitioning is not in the first candidate set.
    Precincts,
    /// The COD marker did not provide valid HT code-block dimensions.
    CodeBlockDimensions,
    /// The markers match the candidate set, but its block decode path is not
    /// implemented.
    BlockDecodeNotImplemented,
}

impl HtUnsupportedReason {
    pub fn message(self) -> &'static str {
        match self {
            Self::MissingCapabilityMarker => {
                "CAP marker is required before HTJ2K decode support can be classified"
            }
            Self::ComponentCount => {
                "only grayscale and RGB HTJ2K candidates are tracked for the first decode subset"
            }
            Self::SamplePrecision => {
                "HTJ2K decode requires matching signedness and precision from 8 through 16 bits for every component"
            }
            Self::ComponentSampling => {
                "subsampled HTJ2K component grids are not implemented by the current decode path"
            }
            Self::MultipleTiles => "the HTJ2K tile grid is outside the caller's decode profile",
            Self::MissingTilePart => {
                "at least one HTJ2K tile-part payload is required before decode support can be enabled"
            }
            Self::ProgressionOrder => "HTJ2K packet progression is outside the decode subset",
            Self::WaveletTransform => "irreversible HTJ2K decode is not implemented",
            Self::PacketMarkers => {
                "HTJ2K SOP/EPH markers require codestream packet-walker validation"
            }
            Self::Precincts => "HTJ2K precinct partitioning is not implemented",
            Self::CodeBlockDimensions => {
                "HTJ2K code-block dimensions must be available and fit the block-layout bound before decode support is enabled"
            }
            Self::BlockDecodeNotImplemented => {
                "HTJ2K markers match the initial candidate subset, but its HT block decode path is not implemented"
            }
        }
    }
}

/// Classify the marker-level HTJ2K subset without attempting pixel decode.
pub fn classify_decode_subset(state: HtMarkerState) -> HtClassification {
    classify_decode_subset_with_component_grid(state, false, 8)
}

fn classify_decode_subset_with_component_grid(
    state: HtMarkerState,
    caller_owns_component_grid: bool,
    minimum_precision: u8,
) -> HtClassification {
    let unsupported = |reason| HtClassification {
        class: HtSupportClass::Unsupported,
        reason,
    };

    if !state.has_cap_marker {
        return HtClassification {
            class: HtSupportClass::Unknown,
            reason: HtUnsupportedReason::MissingCapabilityMarker,
        };
    }
    if !matches!(state.components, 1 | 3) {
        return unsupported(HtUnsupportedReason::ComponentCount);
    }
    if !(minimum_precision..=16).contains(&state.sample_precision_bits)
        || !state.all_components_same_sample_format
    {
        return unsupported(HtUnsupportedReason::SamplePrecision);
    }
    if !state.all_components_unit_sampled && !caller_owns_component_grid {
        return unsupported(HtUnsupportedReason::ComponentSampling);
    }
    if !state.has_tile_part {
        return unsupported(HtUnsupportedReason::MissingTilePart);
    }
    if !state.packet_progression_supported {
        return unsupported(HtUnsupportedReason::ProgressionOrder);
    }
    if !state.reversible_transform {
        return unsupported(HtUnsupportedReason::WaveletTransform);
    }
    // SOP and EPH are packet syntax rather than block-coder properties. The
    // codestream layer admits them only through its strict shared inline
    // packet walker, which checks signalling, placement and packet bounds.
    if state.precincts_declared {
        return unsupported(HtUnsupportedReason::Precincts);
    }
    let Some(width) = state.code_block_width else {
        return unsupported(HtUnsupportedReason::CodeBlockDimensions);
    };
    let Some(height) = state.code_block_height else {
        return unsupported(HtUnsupportedReason::CodeBlockDimensions);
    };
    if HtCodeBlockDimensions::new(width, height).is_err() {
        return unsupported(HtUnsupportedReason::CodeBlockDimensions);
    }

    HtClassification {
        class: HtSupportClass::Candidate,
        reason: HtUnsupportedReason::BlockDecodeNotImplemented,
    }
}

/// Plan the marker-level HTJ2K decode candidate after classification.
///
/// This is still not a general HT block decoder. It narrows accepted marker
/// state into the typed component count and block layout that future HT block
/// decode plumbing can consume, while returning the same structured
/// classification for unsupported states.
pub fn plan_decode_candidate(state: HtMarkerState) -> Result<HtDecodeCandidate, HtClassification> {
    plan_decode_candidate_with_component_grid(state, false, 8)
}

/// Plan a block-local candidate after the caller has independently admitted
/// and taken ownership of non-unit native component-grid geometry.
///
/// The HT block coder neither interprets nor resamples image component grids;
/// all other marker-level candidate checks remain unchanged. Callers must not
/// use this entry point as a general sampling-permission bypass.
pub fn plan_decode_candidate_for_native_component_grid(
    state: HtMarkerState,
) -> Result<HtDecodeCandidate, HtClassification> {
    plan_decode_candidate_with_component_grid(state, true, 8)
}

/// Plan block-local coefficients after the codestream owner has admitted ROI
/// restoration, quantisation and native sample conversion. Unlike the ordinary
/// image route this accepts one through sixteen native precision bits; block
/// magnitudes are independently bounded by the packet and transfer metadata.
pub fn plan_decode_candidate_for_native_roi(
    state: HtMarkerState,
) -> Result<HtDecodeCandidate, HtClassification> {
    plan_decode_candidate_with_component_grid(state, false, 1)
}

fn plan_decode_candidate_with_component_grid(
    state: HtMarkerState,
    caller_owns_component_grid: bool,
    minimum_precision: u8,
) -> Result<HtDecodeCandidate, HtClassification> {
    let classification = classify_decode_subset_with_component_grid(
        state,
        caller_owns_component_grid,
        minimum_precision,
    );
    if classification.class != HtSupportClass::Candidate {
        return Err(classification);
    }

    let Some(width) = state.code_block_width else {
        return Err(classification);
    };
    let Some(height) = state.code_block_height else {
        return Err(classification);
    };
    let dimensions = HtCodeBlockDimensions::new(width, height).map_err(|_| classification)?;

    Ok(HtDecodeCandidate {
        components: state.components,
        sample_precision_bits: state.sample_precision_bits,
        block: HtBlockLayout::new(dimensions),
    })
}

/// Decoded active code-block returned by the current HT block boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtDecodedCodeBlock<'a> {
    pub active_dimensions: HtCodeBlockDimensions,
    pub coefficients: &'a [i32],
}

/// Parsed code-block decode request passed into the HT block boundary.
///
/// The fields here are deliberately packet-level, not codestream-level: marker
/// classification has already produced a validated HT candidate, and the
/// codestream layer has already isolated one code-block segment plus the packet
/// metadata needed to decode it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtCodeBlockDecodeRequest<'a> {
    candidate: HtDecodeCandidate,
    active_dimensions: HtCodeBlockDimensions,
    missing_most_significant_bitplanes: u8,
    coding_passes: u16,
    cleanup_pass_segment_layout: Option<HtCleanupPassSegmentLayout>,
    cleanup_pass_byte_len: Option<usize>,
    code_block_segment: &'a [u8],
}

impl<'a> HtCodeBlockDecodeRequest<'a> {
    /// Bundle one parsed HT code-block segment handoff using the marker-derived
    /// code-block layout as the active decoded area.
    pub fn new(
        candidate: HtDecodeCandidate,
        missing_most_significant_bitplanes: u8,
        coding_passes: u16,
        code_block_segment: &'a [u8],
    ) -> Self {
        Self::new_with_active_dimensions(
            candidate,
            candidate.block().dimensions(),
            missing_most_significant_bitplanes,
            coding_passes,
            code_block_segment,
        )
    }

    /// Bundle one parsed HT code-block segment handoff with the active decoded
    /// area for this block.
    pub fn new_with_active_dimensions(
        candidate: HtDecodeCandidate,
        active_dimensions: HtCodeBlockDimensions,
        missing_most_significant_bitplanes: u8,
        coding_passes: u16,
        code_block_segment: &'a [u8],
    ) -> Self {
        Self {
            candidate,
            active_dimensions,
            missing_most_significant_bitplanes,
            coding_passes,
            cleanup_pass_segment_layout: None,
            cleanup_pass_byte_len: None,
            code_block_segment,
        }
    }

    /// Bundle one parsed HT code-block segment handoff with the active decoded
    /// area for this block and a caller-validated cleanup-pass segment layout.
    pub fn new_with_active_dimensions_and_cleanup_pass_segment_layout(
        candidate: HtDecodeCandidate,
        active_dimensions: HtCodeBlockDimensions,
        missing_most_significant_bitplanes: u8,
        coding_passes: u16,
        cleanup_pass_segment_layout: HtCleanupPassSegmentLayout,
        code_block_segment: &'a [u8],
    ) -> Self {
        Self {
            candidate,
            active_dimensions,
            missing_most_significant_bitplanes,
            coding_passes,
            cleanup_pass_segment_layout: Some(cleanup_pass_segment_layout),
            cleanup_pass_byte_len: None,
            code_block_segment,
        }
    }

    /// Bundle a parsed HT code-block with explicit cleanup and refinement
    /// segment boundaries from its packet header.
    #[allow(clippy::too_many_arguments)]
    pub fn new_with_active_dimensions_and_pass_segment_layout(
        candidate: HtDecodeCandidate,
        active_dimensions: HtCodeBlockDimensions,
        missing_most_significant_bitplanes: u8,
        coding_passes: u16,
        cleanup_pass_segment_layout: HtCleanupPassSegmentLayout,
        cleanup_pass_byte_len: usize,
        code_block_segment: &'a [u8],
    ) -> Self {
        Self {
            candidate,
            active_dimensions,
            missing_most_significant_bitplanes,
            coding_passes,
            cleanup_pass_segment_layout: Some(cleanup_pass_segment_layout),
            cleanup_pass_byte_len: Some(cleanup_pass_byte_len),
            code_block_segment,
        }
    }

    /// Marker-derived decode candidate covered by this request.
    pub fn candidate(self) -> HtDecodeCandidate {
        self.candidate
    }

    /// Active coefficient dimensions for this code-block in the image/tile.
    pub fn active_dimensions(self) -> HtCodeBlockDimensions {
        self.active_dimensions
    }

    /// Active block layout for this code-block.
    pub fn active_block_layout(self) -> HtBlockLayout {
        HtBlockLayout::new(self.active_dimensions)
    }

    /// Number of all-zero most-significant bitplanes declared by the packet.
    pub fn missing_most_significant_bitplanes(self) -> u8 {
        self.missing_most_significant_bitplanes
    }

    /// Component sample precision admitted by the marker-derived candidate.
    pub fn sample_precision_bits(self) -> u8 {
        self.candidate.sample_precision_bits()
    }

    /// Number of coding passes declared by the packet.
    pub fn coding_passes(self) -> u16 {
        self.coding_passes
    }

    /// Retained code-block segment bytes isolated from the packet payload.
    pub fn code_block_segment(self) -> &'a [u8] {
        self.code_block_segment
    }

    /// Packet-isolated cleanup pass bytes.
    pub fn cleanup_pass_segment(self) -> Result<&'a [u8], HtLayoutError> {
        let len = self
            .cleanup_pass_byte_len
            .unwrap_or(self.code_block_segment.len());
        self.code_block_segment
            .get(..len)
            .ok_or(HtLayoutError::InvalidRefinementPassSegment {
                reason: "cleanup pass length exceeds the code-block segment",
            })
    }

    /// Shared forward-SPP/reverse-MRP refinement segment bytes, when present.
    pub fn refinement_pass_segment(self) -> Result<Option<&'a [u8]>, HtLayoutError> {
        if self.coding_passes <= 1 {
            return Ok(None);
        }
        let len =
            self.cleanup_pass_byte_len
                .ok_or(HtLayoutError::InvalidRefinementPassSegment {
                    reason: "multi-pass request has no packet cleanup length",
                })?;
        let refinement = self.code_block_segment.get(len..).ok_or(
            HtLayoutError::InvalidRefinementPassSegment {
                reason: "cleanup pass length exceeds the code-block segment",
            },
        )?;
        if refinement.is_empty() {
            return Err(HtLayoutError::InvalidRefinementPassSegment {
                reason: "multi-pass request has an empty refinement segment",
            });
        }
        Ok(Some(refinement))
    }

    /// Parse the cleanup-pass segment layout declared by this packet-isolated
    /// code-block segment.
    pub fn cleanup_pass_segment_layout(self) -> Result<HtCleanupPassSegmentLayout, HtLayoutError> {
        self.cleanup_pass_segment_layout.map_or_else(
            || HtCleanupPassSegmentLayout::from_cleanup_pass_bytes(self.cleanup_pass_segment()?),
            Ok,
        )
    }

    /// Split this packet-isolated code-block segment into HT cleanup-pass
    /// magnitude/sign and combined MEL/VLC byte views.
    pub fn cleanup_pass_segment_views(
        self,
    ) -> Result<HtCleanupPassSegmentViews<'a>, HtLayoutError> {
        self.cleanup_pass_segment_layout()?
            .split_segment(self.cleanup_pass_segment()?)
    }

    /// Build forward magnitude/sign, forward MEL, and reverse VLC cursors over
    /// this packet-isolated cleanup-pass segment.
    pub fn cleanup_pass_segment_bit_cursors(
        self,
    ) -> Result<HtCleanupPassSegmentBitCursors<'a>, HtLayoutError> {
        self.cleanup_pass_segment_views()?.bit_cursors()
    }

    /// Number of active coefficients this request can write.
    pub fn coefficient_count(self) -> usize {
        self.active_dimensions.coefficient_count()
    }

    #[cfg(feature = "std")]
    fn cleanup_only_decode_request(self) -> Result<Self, HtLayoutError> {
        let cleanup = self.cleanup_pass_segment()?;
        Ok(Self {
            coding_passes: 1,
            cleanup_pass_byte_len: None,
            code_block_segment: cleanup,
            ..self
        })
    }
}

/// Checked code-block decode request bound to caller-owned coefficient output.
///
/// This is the mutation boundary for generic HT code-block decode: future real
/// MEL/VLC/refinement paths can validate the parsed request and output capacity
/// once, before writing coefficient storage.
pub struct HtCodeBlockDecodeBufferRequest<'request, 'output> {
    request: HtCodeBlockDecodeRequest<'request>,
    output: &'output mut [i32],
}

impl<'request, 'output> HtCodeBlockDecodeBufferRequest<'request, 'output> {
    /// Validate one code-block decode request against caller-owned coefficient
    /// output.
    pub fn new(
        request: HtCodeBlockDecodeRequest<'request>,
        output: &'output mut [i32],
    ) -> Result<Self, HtLayoutError> {
        let required = request.coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        request.cleanup_pass_segment_layout()?;
        Ok(Self { request, output })
    }

    /// Parsed code-block decode request covered by this output handoff.
    pub fn request(&self) -> HtCodeBlockDecodeRequest<'request> {
        self.request
    }

    /// Caller-owned coefficient output covered by this request.
    pub fn output(&self) -> &[i32] {
        self.output
    }

    /// Active block layout covered by the caller-owned output.
    pub fn active_block_layout(&self) -> HtBlockLayout {
        self.request.active_block_layout()
    }

    /// Split the checked request into parsed request and caller-owned output.
    pub fn into_parts(self) -> (HtCodeBlockDecodeRequest<'request>, &'output mut [i32]) {
        (self.request, self.output)
    }

    /// Decode through the checked caller-owned output request.
    pub fn decode(self) -> Result<HtCodeBlockDecodeOutcome<'output>, HtLayoutError> {
        let (request, output) = self.into_parts();
        match classify_code_block_decode_request(request) {
            HtCodeBlockDecodeRequestClass::DirectCleanupGroups
            | HtCodeBlockDecodeRequestClass::DirectRefinementPasses => {
                decode_with_temporary_reusable_buffer(request, output)
            }
            HtCodeBlockDecodeRequestClass::PendingBlockDecode => {
                Ok(HtCodeBlockDecodeOutcome::PendingBlockDecode)
            }
        }
    }
}

#[cfg(feature = "std")]
fn decode_with_temporary_reusable_buffer<'out>(
    request: HtCodeBlockDecodeRequest<'_>,
    output: &'out mut [i32],
) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
    let mut buffer = HtBlockScratchBuffer::new();
    buffer.decode_code_block_request_into(request, output)
}

#[cfg(not(feature = "std"))]
fn decode_with_temporary_reusable_buffer<'out>(
    _request: HtCodeBlockDecodeRequest<'_>,
    _output: &'out mut [i32],
) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
    Ok(HtCodeBlockDecodeOutcome::PendingBlockDecode)
}

/// Checked code-block decode request bound to caller-owned scratch and output.
///
/// This is the full generic workspace boundary for future real HT block decode:
/// it validates that side-buffer scratch is laid out for the active block and
/// that coefficient output can hold the decoded active coefficients before any
/// parser or materializer mutates caller storage.
pub struct HtCodeBlockDecodeScratchRequest<'request, 'scratch, 'output> {
    scratch_layout: HtBlockScratchLayout,
    scratch: &'scratch mut [u16],
    buffer: HtCodeBlockDecodeBufferRequest<'request, 'output>,
}

impl<'request, 'scratch, 'output> HtCodeBlockDecodeScratchRequest<'request, 'scratch, 'output> {
    /// Validate one code-block decode request against caller-owned side-buffer
    /// scratch and coefficient output.
    pub fn new(
        request: HtCodeBlockDecodeRequest<'request>,
        scratch_layout: HtBlockScratchLayout,
        scratch: &'scratch mut [u16],
        output: &'output mut [i32],
    ) -> Result<Self, HtLayoutError> {
        check_block_layout_match(request.active_block_layout(), scratch_layout.block())?;
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        let buffer = HtCodeBlockDecodeBufferRequest::new(request, output)?;
        Ok(Self {
            scratch_layout,
            scratch,
            buffer,
        })
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Active block layout covered by this request.
    pub fn active_block_layout(&self) -> HtBlockLayout {
        self.buffer.active_block_layout()
    }

    /// Parsed code-block decode request covered by this output handoff.
    pub fn request(&self) -> HtCodeBlockDecodeRequest<'request> {
        self.buffer.request()
    }

    /// Caller-owned side-buffer scratch covered by this request.
    pub fn scratch(&self) -> &[u16] {
        self.scratch
    }

    /// Caller-owned coefficient output covered by this request.
    pub fn output(&self) -> &[i32] {
        self.buffer.output()
    }

    /// Split the checked workspace into its layout, scratch, parsed request, and
    /// caller-owned output.
    pub fn into_parts(
        self,
    ) -> (
        HtBlockScratchLayout,
        &'scratch mut [u16],
        HtCodeBlockDecodeBufferRequest<'request, 'output>,
    ) {
        (self.scratch_layout, self.scratch, self.buffer)
    }

    /// Decode through the checked caller-owned scratch and output request.
    pub fn decode(self) -> Result<HtCodeBlockDecodeOutcome<'output>, HtLayoutError> {
        let (_scratch_layout, _scratch, buffer) = self.into_parts();
        match classify_code_block_decode_request(buffer.request()) {
            HtCodeBlockDecodeRequestClass::DirectCleanupGroups
            | HtCodeBlockDecodeRequestClass::DirectRefinementPasses => {
                Ok(HtCodeBlockDecodeOutcome::PendingBlockDecode)
            }
            HtCodeBlockDecodeRequestClass::PendingBlockDecode => {
                Ok(HtCodeBlockDecodeOutcome::PendingBlockDecode)
            }
        }
    }

    /// Decode this checked scratch request through the direct cleanup path when
    /// the caller also provides the cleanup-output, context, and MEL storage
    /// that the generic scratch request does not own.
    pub fn decode_direct_cleanup<'cleanup, 'context>(
        self,
        cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
        context_states: &'context mut [HtVlcContextProgression],
        mel_state: &'context mut HtMelEventState,
    ) -> Result<HtCodeBlockDecodeOutcome<'output>, HtLayoutError> {
        Ok(self
            .decode_direct_cleanup_with_progress(cleanup_outputs, context_states, mel_state)?
            .0)
    }

    /// Decode this checked scratch request through the direct cleanup path and
    /// preserve real cleanup segment traversal progress when decoded.
    pub fn decode_direct_cleanup_with_progress<'cleanup, 'context>(
        self,
        cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
        context_states: &'context mut [HtVlcContextProgression],
        mel_state: &'context mut HtMelEventState,
    ) -> Result<
        (
            HtCodeBlockDecodeOutcome<'output>,
            Option<HtVlcBlockCleanupSegmentProgress>,
        ),
        HtLayoutError,
    > {
        let direct_request =
            self.into_direct_cleanup_request(cleanup_outputs, context_states, mel_state)?;
        direct_request.decode_with_progress()
    }

    /// Decode this checked scratch request through the direct cleanup path and
    /// return the Part 15 parser-progress envelope used by explicit direct
    /// no-side-input routes.
    pub fn decode_direct_cleanup_with_parser_progress<'cleanup, 'context>(
        self,
        cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
        context_states: &'context mut [HtVlcContextProgression],
        mel_state: &'context mut HtMelEventState,
    ) -> Result<
        (
            HtCodeBlockDecodeOutcome<'output>,
            Option<HtPart15VlcCleanupSegmentProgress>,
        ),
        HtLayoutError,
    > {
        let direct_request =
            self.into_direct_cleanup_request(cleanup_outputs, context_states, mel_state)?;
        direct_request.decode_with_parser_progress()
    }

    fn into_direct_cleanup_request<'cleanup, 'context>(
        self,
        cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
        context_states: &'context mut [HtVlcContextProgression],
        mel_state: &'context mut HtMelEventState,
    ) -> Result<
        HtCodeBlockDirectCleanupDecodeScratchRequest<
            'request,
            'scratch,
            'cleanup,
            'context,
            'output,
        >,
        HtLayoutError,
    > {
        let (scratch_layout, scratch, buffer) = self.into_parts();
        let (request, output) = buffer.into_parts();
        HtCodeBlockDirectCleanupDecodeScratchRequest::new(
            request,
            scratch_layout,
            scratch,
            cleanup_outputs,
            context_states,
            mel_state,
            output,
        )
    }
}

/// Caller-owned workspace requirements for the real direct cleanup decode path.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtCodeBlockDirectCleanupDecodePlan {
    scratch_layout: HtBlockScratchLayout,
    cleanup_output_count: usize,
    coefficient_output_count: usize,
    context_state_count: usize,
    mel_state_count: usize,
}

impl HtCodeBlockDirectCleanupDecodePlan {
    /// Side-buffer scratch layout required by the active code-block.
    pub fn scratch_layout(self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Number of `HtVlcCleanupCoefficientOutput` slots required.
    pub fn cleanup_output_count(self) -> usize {
        self.cleanup_output_count
    }

    /// Number of coefficient output slots required.
    pub fn coefficient_output_count(self) -> usize {
        self.coefficient_output_count
    }

    /// Number of `HtVlcContextProgression` slots required.
    pub fn context_state_count(self) -> usize {
        self.context_state_count
    }

    /// Number of `HtMelEventState` values required.
    pub fn mel_state_count(self) -> usize {
        self.mel_state_count
    }
}

/// Validate one code-block request and return the caller-owned workspace sizes
/// required by the real direct cleanup decode path.
pub fn plan_code_block_direct_cleanup_decode(
    request: HtCodeBlockDecodeRequest<'_>,
) -> Result<HtCodeBlockDirectCleanupDecodePlan, HtLayoutError> {
    let (scratch_layout, cleanup_output_count) =
        preflight_code_block_cleanup_direct_decode_request(request)?;
    Ok(HtCodeBlockDirectCleanupDecodePlan {
        scratch_layout,
        cleanup_output_count,
        coefficient_output_count: request.coefficient_count(),
        context_state_count: scratch_layout.block().line_pair_count(),
        mel_state_count: 1,
    })
}

/// Checked code-block direct cleanup decode request bound to caller-owned
/// scratch, VLC cleanup outputs, context state, MEL state, and coefficient
/// output.
///
/// This is the allocation-free counterpart to the std reusable direct cleanup
/// path. It exposes the already-implemented real cleanup-segment group
/// materializer without requiring `HtBlockScratchBuffer`, while still keeping
/// all mutable caller storage behind one preflighted handoff.
pub struct HtCodeBlockDirectCleanupDecodeScratchRequest<
    'request,
    'scratch,
    'cleanup,
    'context,
    'output,
> {
    scratch_layout: HtBlockScratchLayout,
    scratch: &'scratch mut [u16],
    cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
    context_states: &'context mut [HtVlcContextProgression],
    mel_state: &'context mut HtMelEventState,
    buffer: HtCodeBlockDecodeBufferRequest<'request, 'output>,
}

impl<'request, 'scratch, 'cleanup, 'context, 'output>
    HtCodeBlockDirectCleanupDecodeScratchRequest<'request, 'scratch, 'cleanup, 'context, 'output>
{
    /// Validate one direct cleanup decode request against caller-owned
    /// workspace and coefficient output.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        request: HtCodeBlockDecodeRequest<'request>,
        scratch_layout: HtBlockScratchLayout,
        scratch: &'scratch mut [u16],
        cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
        context_states: &'context mut [HtVlcContextProgression],
        mel_state: &'context mut HtMelEventState,
        output: &'output mut [i32],
    ) -> Result<Self, HtLayoutError> {
        let plan = plan_code_block_direct_cleanup_decode(request)?;
        check_block_layout_match(plan.scratch_layout().block(), scratch_layout.block())?;
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        if cleanup_outputs.len() < plan.cleanup_output_count() {
            return Err(HtLayoutError::BufferTooSmall {
                required: plan.cleanup_output_count(),
                actual: cleanup_outputs.len(),
            });
        }
        if context_states.len() < plan.context_state_count() {
            return Err(HtLayoutError::BufferTooSmall {
                required: plan.context_state_count(),
                actual: context_states.len(),
            });
        }
        if output.len() < plan.coefficient_output_count() {
            return Err(HtLayoutError::BufferTooSmall {
                required: plan.coefficient_output_count(),
                actual: output.len(),
            });
        }
        let buffer = HtCodeBlockDecodeBufferRequest::new(request, output)?;
        Ok(Self {
            scratch_layout,
            scratch,
            cleanup_outputs,
            context_states,
            mel_state,
            buffer,
        })
    }

    /// Scratch layout covered by this direct cleanup request.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Parsed code-block request covered by this direct cleanup handoff.
    pub fn request(&self) -> HtCodeBlockDecodeRequest<'request> {
        self.buffer.request()
    }

    /// Caller-owned coefficient output covered by this request.
    pub fn output(&self) -> &[i32] {
        self.buffer.output()
    }

    /// Decode through the checked direct cleanup request.
    pub fn decode(self) -> Result<HtCodeBlockDecodeOutcome<'output>, HtLayoutError> {
        Ok(self.decode_with_progress()?.0)
    }

    /// Decode through the checked direct cleanup request and preserve real
    /// cleanup segment traversal progress when the block is decoded.
    pub fn decode_with_progress(
        self,
    ) -> Result<
        (
            HtCodeBlockDecodeOutcome<'output>,
            Option<HtVlcBlockCleanupSegmentProgress>,
        ),
        HtLayoutError,
    > {
        let Self {
            scratch_layout,
            scratch,
            cleanup_outputs,
            context_states,
            mel_state,
            buffer,
        } = self;
        let (request, output) = buffer.into_parts();
        let required = request.coefficient_count();
        let mut segment_cursors = request.cleanup_pass_segment_bit_cursors()?;

        let required_context_states = scratch_layout.block().line_pair_count();
        if required_context_states != 0 {
            context_states[0] = HtVlcContextProgression::initial();
            for context_state in &mut context_states[1..required_context_states] {
                *context_state = HtVlcContextProgression::non_initial(HtVlcContext(0));
            }
        }
        *mel_state = HtMelEventState::new();

        let Some(progress) = scratch_layout
            .try_decode_vlc_cleanup_segment_groups_to_outputs_and_materialize(
                scratch,
                &mut segment_cursors,
                &mut context_states[..required_context_states],
                mel_state,
                cleanup_outputs,
                request.missing_most_significant_bitplanes(),
                output,
            )?
        else {
            return Ok((HtCodeBlockDecodeOutcome::PendingBlockDecode, None));
        };
        if progress.decode.symbol_count != required {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok((
            HtCodeBlockDecodeOutcome::Decoded(HtDecodedCodeBlock {
                active_dimensions: request.active_dimensions(),
                coefficients: &output[..required],
            }),
            Some(progress),
        ))
    }

    /// Decode through the checked direct cleanup request and return the Part 15
    /// parser-progress envelope used by explicit direct no-side-input routes.
    pub fn decode_with_parser_progress(
        self,
    ) -> Result<
        (
            HtCodeBlockDecodeOutcome<'output>,
            Option<HtPart15VlcCleanupSegmentProgress>,
        ),
        HtLayoutError,
    > {
        let (decoded, segment) = self.decode_with_progress()?;
        let Some(segment) = segment else {
            return Ok((decoded, None));
        };
        Ok((
            decoded,
            Some(HtPart15VlcCleanupSegmentProgress::direct(segment)?),
        ))
    }
}

fn check_block_layout_match(
    expected: HtBlockLayout,
    actual: HtBlockLayout,
) -> Result<(), HtLayoutError> {
    if expected == actual {
        return Ok(());
    }
    let expected = expected.dimensions();
    let actual = actual.dimensions();
    Err(HtLayoutError::BlockLayoutMismatch {
        expected_width: expected.width(),
        expected_height: expected.height(),
        actual_width: actual.width(),
        actual_height: actual.height(),
    })
}

fn preflight_code_block_cleanup_direct_decode_request(
    request: HtCodeBlockDecodeRequest<'_>,
) -> Result<(HtBlockScratchLayout, usize), HtLayoutError> {
    if request.coding_passes() != 1 {
        return Err(HtLayoutError::UnsupportedCodingPassCount {
            coding_passes: request.coding_passes(),
        });
    }
    let scratch_layout = HtBlockScratchLayout::new(request.active_block_layout())?;
    let block = scratch_layout.block();
    let required = block.dimensions().coefficient_count();
    let _ = cleanup_bitplane_from_missing_msbs(request.missing_most_significant_bitplanes())?;
    let _ = request.cleanup_pass_segment_bit_cursors()?;

    Ok((scratch_layout, required))
}

/// Current classification for a parsed HT code-block decode request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtCodeBlockDecodeRequestClass {
    /// Request can be handled by the implemented one-pass direct cleanup
    /// group decoder when caller-owned direct-cleanup workspace is available.
    DirectCleanupGroups,
    /// Request can be handled by cleanup followed by the checked scalar
    /// significance-propagation and optional magnitude-refinement passes.
    DirectRefinementPasses,
    /// Request is structurally admitted but still needs real HT block decoding.
    PendingBlockDecode,
}

/// Current result of dispatching a parsed HT code-block request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtCodeBlockDecodeOutcome<'a> {
    /// Request decoded through an implemented HT block path.
    Decoded(HtDecodedCodeBlock<'a>),
    /// Request remains structurally admitted but needs real HT block decoding.
    PendingBlockDecode,
}

/// Dispatch provenance returned by reusable HT code-block decode.
///
/// This is intentionally separate from [`HtVlcBlockCleanupSegmentProgress`]:
/// segment progress proves that the real standard-table cleanup traversal ran,
/// while dispatch progress records the complete decode route.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtCodeBlockDecodeDispatchProgress {
    pub request_class: HtCodeBlockDecodeRequestClass,
    pub cleanup_segment_progress: Option<HtVlcBlockCleanupSegmentProgress>,
    pub materialization_progress: Option<HtVlcCleanupOutputMaterializationProgress>,
    /// Scalar SPP/MRP progress when refinement passes were applied.
    pub refinement_pass_progress: Option<HtRefinementPassProgress>,
}

impl HtCodeBlockDecodeDispatchProgress {
    /// True when the reusable decode dispatch reached a real standard-table
    /// VLC cleanup traversal.
    pub const fn used_standard_vlc_cleanup_tables(self) -> bool {
        self.cleanup_segment_progress.is_some()
    }

    /// True when the reusable decode dispatch materialized decoded VLC cleanup
    /// outputs into the row-major coefficient plane.
    pub const fn materialized_coefficients(self) -> bool {
        self.materialization_progress.is_some()
    }
}

/// Classify a parsed code-block request before attempting decode.
pub fn classify_code_block_decode_request(
    request: HtCodeBlockDecodeRequest<'_>,
) -> HtCodeBlockDecodeRequestClass {
    if plan_code_block_direct_cleanup_decode(request).is_ok() {
        HtCodeBlockDecodeRequestClass::DirectCleanupGroups
    } else if matches!(request.coding_passes(), 2 | 3)
        && request.refinement_pass_segment().is_ok()
        && request.cleanup_pass_segment_layout().is_ok()
        && cleanup_bitplane_from_missing_msbs(request.missing_most_significant_bitplanes())
            .is_ok_and(|bitplane| bitplane >= 2)
    {
        HtCodeBlockDecodeRequestClass::DirectRefinementPasses
    } else {
        HtCodeBlockDecodeRequestClass::PendingBlockDecode
    }
}

/// Decode a parsed HT code-block request through the currently implemented HT
/// block paths.
pub fn decode_code_block_request(
    request: HtCodeBlockDecodeRequest<'_>,
) -> HtCodeBlockDecodeOutcome<'static> {
    match classify_code_block_decode_request(request) {
        HtCodeBlockDecodeRequestClass::DirectCleanupGroups => {
            HtCodeBlockDecodeOutcome::PendingBlockDecode
        }
        HtCodeBlockDecodeRequestClass::DirectRefinementPasses => {
            HtCodeBlockDecodeOutcome::PendingBlockDecode
        }
        HtCodeBlockDecodeRequestClass::PendingBlockDecode => {
            HtCodeBlockDecodeOutcome::PendingBlockDecode
        }
    }
}

/// Decode a parsed HT code-block request into caller-owned coefficient output.
pub fn decode_code_block_request_into<'out>(
    request: HtCodeBlockDecodeRequest<'_>,
    output: &'out mut [i32],
) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
    decode_code_block_buffer_request(HtCodeBlockDecodeBufferRequest::new(request, output)?)
}

/// Decode a checked parsed HT code-block request into its caller-owned output.
pub fn decode_code_block_buffer_request<'out>(
    request: HtCodeBlockDecodeBufferRequest<'_, 'out>,
) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
    request.decode()
}

/// Decode a checked parsed HT code-block request using caller-owned scratch and
/// coefficient output.
pub fn decode_code_block_scratch_request<'out>(
    request: HtCodeBlockDecodeScratchRequest<'_, '_, 'out>,
) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
    request.decode()
}

/// Decode a checked parsed HT code-block request using caller-owned direct
/// cleanup workspace and coefficient output.
pub fn decode_code_block_direct_cleanup_scratch_request<'out>(
    request: HtCodeBlockDirectCleanupDecodeScratchRequest<'_, '_, '_, '_, 'out>,
) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
    request.decode()
}

/// Decode a checked parsed HT code-block request using caller-owned direct
/// cleanup workspace and return real cleanup segment traversal progress.
pub fn decode_code_block_direct_cleanup_scratch_request_with_progress<'out>(
    request: HtCodeBlockDirectCleanupDecodeScratchRequest<'_, '_, '_, '_, 'out>,
) -> Result<
    (
        HtCodeBlockDecodeOutcome<'out>,
        Option<HtVlcBlockCleanupSegmentProgress>,
    ),
    HtLayoutError,
> {
    request.decode_with_progress()
}

/// Decode a checked parsed HT code-block request using caller-owned direct
/// cleanup workspace and return the direct no-side-input parser-progress
/// envelope.
pub fn decode_code_block_direct_cleanup_scratch_request_with_parser_progress<'out>(
    request: HtCodeBlockDirectCleanupDecodeScratchRequest<'_, '_, '_, '_, 'out>,
) -> Result<
    (
        HtCodeBlockDecodeOutcome<'out>,
        Option<HtPart15VlcCleanupSegmentProgress>,
    ),
    HtLayoutError,
> {
    request.decode_with_parser_progress()
}

/// Boundary marker for future general HT block decoder state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtBoundary;

/// Errors reported by HT block-layout planning.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtLayoutError {
    /// HT code-block dimensions must be non-empty and fit the JPEG 2000
    /// code-block coefficient bound.
    InvalidCodeBlock { width: u16, height: u16 },
    /// A validated raw composed decode plan was built for different block
    /// geometry than the materialization boundary being used.
    BlockLayoutMismatch {
        expected_width: u16,
        expected_height: u16,
        actual_width: u16,
        actual_height: u16,
    },
    /// HT stream or scratch layout length arithmetic overflowed `usize`.
    SizeOverflow,
    /// `EMUELLA_J2K_HT_BACKEND` named an unknown HT cleanup backend.
    UnknownCleanupBackendOverride,
    /// The forced HT cleanup backend is unavailable on this CPU or build.
    UnavailableCleanupBackendOverride,
    /// A cleanup pass segment has an invalid `Scup` trailer declaration.
    InvalidCleanupPassSegment { lcup: usize, scup: usize },
    /// Packet pass lengths or refinement stream contents are malformed.
    InvalidRefinementPassSegment { reason: &'static str },
    /// A cleanup coefficient reconstruction request used an unsupported
    /// cleanup bitplane declaration.
    InvalidCleanupBitplane {
        missing_most_significant_bitplanes: u8,
    },
    /// A cleanup-only decode boundary received a request with extra HT coding
    /// passes that require refinement handling.
    UnsupportedCodingPassCount { coding_passes: u16 },
    /// A caller-provided scratch or stream buffer is too small for the layout.
    BufferTooSmall { required: usize, actual: usize },
    /// A caller-provided cleanup symbol slice does not match block geometry.
    SymbolCountMismatch { required: usize, actual: usize },
    /// A caller-provided refinement value slice does not match block geometry.
    RefinementValueCountMismatch { required: usize, actual: usize },
    /// A caller-provided magnitude/sign value slice does not match block
    /// geometry.
    MagnitudeSignValueCountMismatch { required: usize, actual: usize },
    /// A caller-provided VLC cleanup output slice does not match block
    /// geometry.
    VlcCleanupOutputCountMismatch { required: usize, actual: usize },
    /// A caller-provided VLC cleanup output is internally inconsistent.
    InvalidVlcCleanupOutput { reason: &'static str },
    /// A cleanup stream cursor consumed more bytes than its partition allows.
    StreamOverrun {
        stream: HtCleanupStreamKind,
        consumed: usize,
        available: usize,
    },
    /// A cleanup stream bit cursor consumed more bits than its partition allows.
    StreamBitOverrun {
        stream: HtCleanupStreamKind,
        consumed_bits: usize,
        available_bits: usize,
    },
    /// A required cleanup stream bit read could not be satisfied.
    StreamBitReadUnavailable {
        stream: HtCleanupStreamKind,
        requested_bits: usize,
        remaining_bits: usize,
    },
    /// A required byte read was attempted while a cleanup stream bit cursor
    /// was not aligned to a byte boundary.
    StreamUnalignedByteRead {
        stream: HtCleanupStreamKind,
        consumed_bits: usize,
    },
    /// A parser-output helper expected a cleanup stream bit cursor positioned
    /// at the start of its partition.
    StreamCursorNotAtStart {
        stream: HtCleanupStreamKind,
        consumed_bits: usize,
    },
    /// A cleanup stream bit cursor did not consume every declared bit.
    StreamBitUnderconsumed {
        stream: HtCleanupStreamKind,
        consumed_bits: usize,
        expected_bits: usize,
    },
    /// A finalized VLC cleanup traversal left caller-provided side-input items
    /// unread.
    SideInputUnderconsumed {
        remaining_quad_side_bits: usize,
        remaining_odd_tail_u_values: usize,
    },
    /// A preflighted Part 15 side-input request was paired with a different
    /// checked parser outcome.
    SideInputMismatch,
    /// A caller-provided VLC cleanup side-bit entry targets a cropped
    /// coefficient outside the active code-block dimensions.
    SideInputTargetsCroppedCoefficient { quad_side_bit_index: usize },
    /// A byte following a MEL `0xff` byte violated the HT MEL bit-stuffing
    /// constraint.
    StreamStuffedByteInvalid {
        stream: HtCleanupStreamKind,
        byte: u8,
        consumed_bits: usize,
    },
}

/// Named HT cleanup stream partition.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtCleanupStreamKind {
    CleanupForward,
    CleanupReverse,
    Mel,
    Vlc,
}

/// Byte traversal direction for one HT cleanup stream partition.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtCleanupStreamDirection {
    Forward,
    Reverse,
}

impl HtCleanupStreamKind {
    /// Number of cleanup stream partitions.
    pub const COUNT: usize = 4;

    /// Cleanup stream partitions in layout order.
    pub const ALL: [Self; Self::COUNT] = [
        Self::CleanupForward,
        Self::CleanupReverse,
        Self::Mel,
        Self::Vlc,
    ];

    /// Stable zero-based index in cleanup stream layout order.
    pub fn index(self) -> usize {
        match self {
            Self::CleanupForward => 0,
            Self::CleanupReverse => 1,
            Self::Mel => 2,
            Self::Vlc => 3,
        }
    }

    /// Cleanup stream kind for a stable layout-order index.
    pub fn from_index(index: usize) -> Option<Self> {
        Self::ALL.get(index).copied()
    }

    /// Byte traversal direction for this cleanup stream partition.
    pub fn direction(self) -> HtCleanupStreamDirection {
        match self {
            Self::CleanupForward | Self::Mel | Self::Vlc => HtCleanupStreamDirection::Forward,
            Self::CleanupReverse => HtCleanupStreamDirection::Reverse,
        }
    }

    /// True when this partition advances from the front of its byte range.
    pub fn is_forward(self) -> bool {
        self.direction() == HtCleanupStreamDirection::Forward
    }

    /// True when this partition advances from the back of its byte range.
    pub fn is_reverse(self) -> bool {
        self.direction() == HtCleanupStreamDirection::Reverse
    }
}

/// Raw cleanup-stream decode parameters for the staged HT block decoder.
///
/// This keeps the temporary raw-plane decoder's stream selection and
/// magnitude/sign width together so later MEL/VLC cleanup syntax can replace
/// the raw side-buffer driver without changing the block-output boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawCleanupDecodeConfig {
    stream: HtCleanupStreamKind,
    magnitude_sign_bits: u8,
}

impl HtRawCleanupDecodeConfig {
    /// Create validated raw cleanup decode parameters.
    pub fn new(
        stream: HtCleanupStreamKind,
        magnitude_sign_bits: u8,
    ) -> Result<Self, HtLayoutError> {
        if magnitude_sign_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok(Self {
            stream,
            magnitude_sign_bits,
        })
    }

    /// Cleanup stream partition used by this raw-plane decode.
    pub fn stream(self) -> HtCleanupStreamKind {
        self.stream
    }

    /// Number of raw magnitude/sign bits read for each real coefficient.
    pub fn magnitude_sign_bits(self) -> u8 {
        self.magnitude_sign_bits
    }

    /// Number of raw side-buffer bits this staged decoder expects for one
    /// block: cleanup-context, greater-than-one, refinement-bit, and the raw
    /// magnitude/sign field for every real coefficient.
    pub fn expected_raw_side_buffer_bits(
        self,
        block: HtBlockLayout,
    ) -> Result<usize, HtLayoutError> {
        let bits_per_coefficient = checked_add(3, usize::from(self.magnitude_sign_bits))?;
        checked_mul(block.dimensions().coefficient_count(), bits_per_coefficient)
    }

    /// Expected per-stream bit counts for this raw cleanup decode.
    pub fn expected_raw_side_buffer_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> Result<HtCleanupStreamBitCounts, HtLayoutError> {
        let bits = self.expected_raw_side_buffer_bits(block)?;
        Ok(match self.stream {
            HtCleanupStreamKind::CleanupForward => HtCleanupStreamBitCounts {
                cleanup_forward: bits,
                cleanup_reverse: 0,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::CleanupReverse => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: bits,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::Mel => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: bits,
                vlc: 0,
            },
            HtCleanupStreamKind::Vlc => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: 0,
                vlc: bits,
            },
        })
    }

    /// Validate the declared stream layout before scratch or output mutation.
    pub fn check_declared_raw_side_buffer_bits(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
    ) -> Result<(), HtLayoutError> {
        self.expected_raw_side_buffer_bit_counts(block)?
            .check_matches_layout(stream_layout)
    }

    /// Validate the declared stream layout and backing byte slice before raw
    /// cleanup-symbol side-buffer storage can mutate.
    pub fn check_available_raw_side_buffer_stream_bytes(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
        stream_bytes: &[u8],
    ) -> Result<(), HtLayoutError> {
        self.check_declared_raw_side_buffer_bits(block, stream_layout)?;
        let required_stream_bytes = stream_layout.total_bytes();
        if stream_bytes.len() < required_stream_bytes {
            return Err(HtLayoutError::BufferTooSmall {
                required: required_stream_bytes,
                actual: stream_bytes.len(),
            });
        }
        Ok(())
    }
}

