/// Raw one-bit coefficient-plane decode parameters for staged HT cleanup
/// side-buffer drivers.
///
/// This covers the temporary raw significance, greater-than-one, and
/// refinement-bit primitives. Each reads exactly one bit per real coefficient
/// from a selected cleanup stream partition before future MEL/VLC cleanup
/// syntax replaces the raw bit-plane readers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawCoefficientBitPlaneDecodeConfig {
    stream: HtCleanupStreamKind,
}

impl HtRawCoefficientBitPlaneDecodeConfig {
    /// Create raw one-bit coefficient-plane decode parameters.
    pub fn new(stream: HtCleanupStreamKind) -> Self {
        Self { stream }
    }

    /// Cleanup stream partition used by this raw bit-plane decode.
    pub fn stream(self) -> HtCleanupStreamKind {
        self.stream
    }

    /// Number of raw bit-plane bits expected for one block.
    pub fn expected_raw_bit_plane_bits(self, block: HtBlockLayout) -> usize {
        block.dimensions().coefficient_count()
    }

    /// Expected per-stream bit counts for this raw bit-plane decode.
    pub fn expected_raw_bit_plane_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> HtCleanupStreamBitCounts {
        let bits = self.expected_raw_bit_plane_bits(block);
        match self.stream {
            HtCleanupStreamKind::CleanupForward => HtCleanupStreamBitCounts {
                cleanup_forward: bits,
                cleanup_reverse: 0,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::CleanupReverse => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: bits,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::Mel => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: bits,
                vlc: 0,
            },
            HtCleanupStreamKind::Vlc => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: 0,
                vlc: bits,
            },
        }
    }

    /// Validate the declared stream layout before side-buffer mutation.
    pub fn check_declared_raw_bit_plane_bits(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
    ) -> Result<(), HtLayoutError> {
        self.expected_raw_bit_plane_bit_counts(block)
            .check_matches_layout(stream_layout)
    }

    /// Validate the declared stream layout and backing byte slice before a raw
    /// one-bit coefficient plane can mutate side-buffer scratch.
    pub fn check_available_raw_bit_plane_stream_bytes(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
        stream_bytes: &[u8],
    ) -> Result<(), HtLayoutError> {
        self.check_declared_raw_bit_plane_bits(block, stream_layout)?;
        let required_stream_bytes = stream_layout.total_bytes();
        if stream_bytes.len() < required_stream_bytes {
            return Err(HtLayoutError::BufferTooSmall {
                required: required_stream_bytes,
                actual: stream_bytes.len(),
            });
        }
        Ok(())
    }
}

