/// Raw side-input decode parameters for staged HT cleanup VLC traversal.
///
/// This temporary parser reads traversal-order `gt1` and refinement side-bit
/// masks plus fixed-width odd-tail `u` values from one selected cleanup stream.
/// Future real cleanup syntax can replace this raw reader while keeping the
/// side-input buffer and block traversal boundaries.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawVlcCleanupSideInputDecodeConfig {
    stream: HtCleanupStreamKind,
    odd_tail_u_bits: u8,
}

impl HtRawVlcCleanupSideInputDecodeConfig {
    /// Create validated raw VLC side-input decode parameters.
    pub fn new(stream: HtCleanupStreamKind, odd_tail_u_bits: u8) -> Result<Self, HtLayoutError> {
        if odd_tail_u_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok(Self {
            stream,
            odd_tail_u_bits,
        })
    }

    /// Cleanup stream partition used by this raw side-input decode.
    pub fn stream(self) -> HtCleanupStreamKind {
        self.stream
    }

    /// Fixed number of bits read for each odd-tail `u` value.
    pub fn odd_tail_u_bits(self) -> u8 {
        self.odd_tail_u_bits
    }

    /// Number of raw side-input bits expected for one block.
    pub fn expected_raw_vlc_side_input_bits(
        self,
        block: HtBlockLayout,
    ) -> Result<usize, HtLayoutError> {
        let counts = block.vlc_cleanup_side_input_counts();
        let quad_side_bits = checked_mul(counts.quad_side_bits, 8)?;
        let odd_tail_bits =
            checked_mul(counts.odd_tail_u_values, usize::from(self.odd_tail_u_bits))?;
        checked_add(quad_side_bits, odd_tail_bits)
    }

    /// Expected per-stream bit counts for this raw side-input decode.
    pub fn expected_raw_vlc_side_input_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> Result<HtCleanupStreamBitCounts, HtLayoutError> {
        let bits = self.expected_raw_vlc_side_input_bits(block)?;
        Ok(match self.stream {
            HtCleanupStreamKind::CleanupForward => HtCleanupStreamBitCounts {
                cleanup_forward: bits,
                cleanup_reverse: 0,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::CleanupReverse => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: bits,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::Mel => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: bits,
                vlc: 0,
            },
            HtCleanupStreamKind::Vlc => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: 0,
                vlc: bits,
            },
        })
    }

    /// Validate the declared stream layout before side-input buffer mutation.
    pub fn check_declared_raw_vlc_side_input_bits(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
    ) -> Result<(), HtLayoutError> {
        self.expected_raw_vlc_side_input_bit_counts(block)?
            .check_matches_layout(stream_layout)
    }

    /// Validate the declared stream layout and backing byte slice before
    /// side-input buffer mutation or reusable scratch growth.
    pub fn check_available_raw_vlc_side_input_stream_bytes(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
        stream_bytes: &[u8],
    ) -> Result<(), HtLayoutError> {
        self.check_declared_raw_vlc_side_input_bits(block, stream_layout)?;
        let required_stream_bytes = stream_layout.total_bytes();
        if stream_bytes.len() < required_stream_bytes {
            return Err(HtLayoutError::BufferTooSmall {
                required: required_stream_bytes,
                actual: stream_bytes.len(),
            });
        }
        Ok(())
    }

    /// Parse one traversal-order side-input group from the configured temporary
    /// raw byte-backed cleanup stream.
    pub fn parse_raw_side_input_group_from_stream_cursors(
        self,
        group: HtVlcQuadPairGroup,
        cursors: &mut HtCleanupStreamBitCursors<'_>,
    ) -> Result<HtVlcLinePairCleanupSideInput, HtLayoutError> {
        self.parse_raw_side_input_group_from_stream_cursors_with_counts(group, cursors)
            .map(HtParsedVlcCleanupSideInputGroup::into_side_input)
    }

    /// Parse one traversal-order side-input group and carry the produced
    /// side-input counts with the parsed value.
    pub fn parse_raw_side_input_group_from_stream_cursors_with_counts(
        self,
        group: HtVlcQuadPairGroup,
        cursors: &mut HtCleanupStreamBitCursors<'_>,
    ) -> Result<HtParsedVlcCleanupSideInputGroup, HtLayoutError> {
        let stream = self.stream();
        let odd_tail_u_bits = self.odd_tail_u_bits();
        let side_input = read_raw_vlc_cleanup_side_input_group(group, odd_tail_u_bits, |bits| {
            Ok(cursors.read_required_bits_for(stream, bits)? as u16)
        })?;
        HtParsedVlcCleanupSideInputGroup::try_new(group, side_input)
    }
}

/// Physical cleanup-pass segment cursor used by the temporary raw VLC
/// side-input parser.
///
/// This is narrower than [`HtCleanupStreamKind`]: a cleanup-pass segment has a
/// forward magnitude/sign cursor, a forward MEL cursor, and a reverse
/// unstuffed VLC cursor. The final Part 15 side-bit parser should replace the
/// raw layout while keeping this segment-cursor boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtCleanupPassSegmentStreamKind {
    MagnitudeSign,
    Mel,
    Vlc,
}

impl HtCleanupPassSegmentStreamKind {
    fn error_stream(self) -> HtCleanupStreamKind {
        match self {
            Self::MagnitudeSign => HtCleanupStreamKind::CleanupForward,
            Self::Mel => HtCleanupStreamKind::Mel,
            Self::Vlc => HtCleanupStreamKind::Vlc,
        }
    }
}

/// Raw side-input decode parameters over real cleanup-pass segment cursors.
///
/// The field layout is intentionally the same temporary traversal-order shape
/// as [`HtRawVlcCleanupSideInputDecodeConfig`]: four `gt1` bits and four
/// refinement bits per quad, plus a fixed-width odd-tail `u` value for each
/// single-quad traversal step.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawVlcCleanupSegmentSideInputDecodeConfig {
    stream: HtCleanupPassSegmentStreamKind,
    odd_tail_u_bits: u8,
}

impl HtRawVlcCleanupSegmentSideInputDecodeConfig {
    /// Create validated raw segment-side-input decode parameters.
    pub fn new(
        stream: HtCleanupPassSegmentStreamKind,
        odd_tail_u_bits: u8,
    ) -> Result<Self, HtLayoutError> {
        if odd_tail_u_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok(Self {
            stream,
            odd_tail_u_bits,
        })
    }

    /// Cleanup-pass segment cursor used by this temporary raw decode.
    pub fn stream(self) -> HtCleanupPassSegmentStreamKind {
        self.stream
    }

    /// Fixed number of bits read for each odd-tail `u` value.
    pub fn odd_tail_u_bits(self) -> u8 {
        self.odd_tail_u_bits
    }

    /// Number of raw side-input bits expected for one block.
    pub fn expected_raw_vlc_side_input_bits(
        self,
        block: HtBlockLayout,
    ) -> Result<usize, HtLayoutError> {
        let counts = block.vlc_cleanup_side_input_counts();
        let quad_side_bits = checked_mul(counts.quad_side_bits, 8)?;
        let odd_tail_bits =
            checked_mul(counts.odd_tail_u_values, usize::from(self.odd_tail_u_bits))?;
        checked_add(quad_side_bits, odd_tail_bits)
    }

    /// Expected physical segment-cursor bit counts for this raw side-input
    /// decode.
    pub fn expected_raw_vlc_side_input_segment_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> Result<HtCleanupPassSegmentBitCounts, HtLayoutError> {
        HtCleanupPassSegmentBitCounts::ZERO
            .checked_add_for_stream(self.stream, self.expected_raw_vlc_side_input_bits(block)?)
    }

    /// Validate that the selected segment cursor has enough bits for this
    /// temporary raw side-input decode before any parser-output storage mutates.
    pub fn check_available_raw_vlc_side_input_segment_bits(
        self,
        block: HtBlockLayout,
        segment_cursors: &HtCleanupPassSegmentBitCursors<'_>,
    ) -> Result<(), HtLayoutError> {
        let expected_bits = self.expected_raw_vlc_side_input_bits(block)?;
        let remaining_bits = segment_cursors.remaining_bits_for(self.stream);
        if remaining_bits < expected_bits {
            return Err(HtLayoutError::StreamBitReadUnavailable {
                stream: self.stream.error_stream(),
                requested_bits: expected_bits,
                remaining_bits,
            });
        }
        Ok(())
    }

    /// Parse one traversal-order side-input group from the configured temporary
    /// raw cleanup-pass segment cursor.
    pub fn parse_raw_side_input_group_from_segment_cursors(
        self,
        group: HtVlcQuadPairGroup,
        segment_cursors: &mut HtCleanupPassSegmentBitCursors<'_>,
    ) -> Result<HtVlcLinePairCleanupSideInput, HtLayoutError> {
        self.parse_raw_side_input_group_from_segment_cursors_with_counts(group, segment_cursors)
            .map(HtParsedVlcCleanupSideInputGroup::into_side_input)
    }

    /// Parse one traversal-order side-input group and carry the produced
    /// side-input counts with the parsed value.
    pub fn parse_raw_side_input_group_from_segment_cursors_with_counts(
        self,
        group: HtVlcQuadPairGroup,
        segment_cursors: &mut HtCleanupPassSegmentBitCursors<'_>,
    ) -> Result<HtParsedVlcCleanupSideInputGroup, HtLayoutError> {
        let stream = self.stream();
        let odd_tail_u_bits = self.odd_tail_u_bits();
        let side_input = read_raw_vlc_cleanup_side_input_group(group, odd_tail_u_bits, |bits| {
            Ok(segment_cursors.read_required_bits_for(stream, bits)? as u16)
        })?;
        HtParsedVlcCleanupSideInputGroup::try_new(group, side_input)
    }
}

/// Raw refinement-value decode parameters over real cleanup-pass segment
/// cursors.
///
/// This is the segment-byte counterpart to
/// [`HtRawRefinementValueDecodeConfig`]. It keeps the temporary fixed-width
/// refinement-value parser behind the physical segment-cursor boundary so real
/// Part 15 refinement syntax can replace the reader without changing the
/// traversal-order value plane.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawSegmentRefinementValueDecodeConfig {
    stream: HtCleanupPassSegmentStreamKind,
    refinement_value_bits: u8,
}

impl HtRawSegmentRefinementValueDecodeConfig {
    /// Create validated raw segment refinement-value decode parameters.
    pub fn new(
        stream: HtCleanupPassSegmentStreamKind,
        refinement_value_bits: u8,
    ) -> Result<Self, HtLayoutError> {
        if refinement_value_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok(Self {
            stream,
            refinement_value_bits,
        })
    }

    /// Cleanup-pass segment cursor used by this temporary raw decode.
    pub fn stream(self) -> HtCleanupPassSegmentStreamKind {
        self.stream
    }

    /// Number of raw refinement-value bits read for each real coefficient.
    pub fn refinement_value_bits(self) -> u8 {
        self.refinement_value_bits
    }

    /// Number of raw refinement-value bits expected for one block.
    pub fn expected_raw_refinement_value_bits(
        self,
        block: HtBlockLayout,
    ) -> Result<usize, HtLayoutError> {
        checked_mul(
            block.dimensions().coefficient_count(),
            usize::from(self.refinement_value_bits),
        )
    }

    /// Expected physical segment-cursor bit counts for this raw refinement
    /// value decode.
    pub fn expected_raw_refinement_value_segment_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> Result<HtCleanupPassSegmentBitCounts, HtLayoutError> {
        HtCleanupPassSegmentBitCounts::ZERO
            .checked_add_for_stream(self.stream, self.expected_raw_refinement_value_bits(block)?)
    }

    /// Validate that the selected segment cursor has enough bits for this
    /// temporary raw refinement-value decode before value storage mutates.
    pub fn check_available_raw_refinement_value_segment_bits(
        self,
        block: HtBlockLayout,
        segment_cursors: &HtCleanupPassSegmentBitCursors<'_>,
    ) -> Result<(), HtLayoutError> {
        let expected_bits = self.expected_raw_refinement_value_bits(block)?;
        let remaining_bits = segment_cursors.remaining_bits_for(self.stream);
        if remaining_bits < expected_bits {
            return Err(HtLayoutError::StreamBitReadUnavailable {
                stream: self.stream.error_stream(),
                requested_bits: expected_bits,
                remaining_bits,
            });
        }
        Ok(())
    }
}

