/// Temporary raw parser-output decode parameters over real cleanup-pass
/// segment cursors.
///
/// This groups the raw side-input, refinement-value, and magnitude/sign
/// segment-cursor readers behind one combined preflight so callers can reject
/// insufficient physical stream capacity before any parser-output plane is
/// mutated.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawSegmentParserOutputDecodeConfig {
    side_inputs: HtRawVlcCleanupSegmentSideInputDecodeConfig,
    refinement: HtRawSegmentRefinementValueDecodeConfig,
    magnitude_sign: HtRawSegmentMagnitudeSignValueDecodeConfig,
}

impl HtRawSegmentParserOutputDecodeConfig {
    /// Bundle validated raw segment parser-output decode configs.
    pub fn new(
        side_inputs: HtRawVlcCleanupSegmentSideInputDecodeConfig,
        refinement: HtRawSegmentRefinementValueDecodeConfig,
        magnitude_sign: HtRawSegmentMagnitudeSignValueDecodeConfig,
    ) -> Self {
        Self {
            side_inputs,
            refinement,
            magnitude_sign,
        }
    }

    /// Raw side-input decode config covered by this combined boundary.
    pub fn side_inputs(self) -> HtRawVlcCleanupSegmentSideInputDecodeConfig {
        self.side_inputs
    }

    /// Raw refinement-value decode config covered by this combined boundary.
    pub fn refinement(self) -> HtRawSegmentRefinementValueDecodeConfig {
        self.refinement
    }

    /// Raw magnitude/sign decode config covered by this combined boundary.
    pub fn magnitude_sign(self) -> HtRawSegmentMagnitudeSignValueDecodeConfig {
        self.magnitude_sign
    }

    /// Expected physical segment-cursor bit counts for all parser-output
    /// planes in this combined temporary raw decode.
    pub fn expected_raw_segment_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> Result<HtCleanupPassSegmentBitCounts, HtLayoutError> {
        self.side_inputs
            .expected_raw_vlc_side_input_segment_bit_counts(block)?
            .checked_add(
                self.refinement
                    .expected_raw_refinement_value_segment_bit_counts(block)?,
            )?
            .checked_add(
                self.magnitude_sign
                    .expected_raw_magnitude_sign_segment_bit_counts(block)?,
            )
    }

    /// Validate aggregate physical segment-cursor capacity for this temporary
    /// raw parser-output decode before any parser-output plane mutates.
    pub fn check_available_raw_segment_bits(
        self,
        block: HtBlockLayout,
        segment_cursors: &HtCleanupPassSegmentBitCursors<'_>,
    ) -> Result<(), HtLayoutError> {
        segment_cursors.check_available_bits(self.expected_raw_segment_bit_counts(block)?)
    }
}

/// Raw refinement-value decode parameters for the staged HT block decoder.
///
/// This keeps the temporary raw refinement-value parser separate from cleanup
/// symbol parsing so the real refinement syntax can replace it without
/// changing the prepared side-buffer mutation boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawRefinementValueDecodeConfig {
    stream: HtCleanupStreamKind,
    refinement_value_bits: u8,
}

impl HtRawRefinementValueDecodeConfig {
    /// Create validated raw refinement-value decode parameters.
    pub fn new(
        stream: HtCleanupStreamKind,
        refinement_value_bits: u8,
    ) -> Result<Self, HtLayoutError> {
        if refinement_value_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok(Self {
            stream,
            refinement_value_bits,
        })
    }

    /// Cleanup stream partition used by this raw refinement-value decode.
    pub fn stream(self) -> HtCleanupStreamKind {
        self.stream
    }

    /// Number of raw refinement-value bits read for each real coefficient.
    pub fn refinement_value_bits(self) -> u8 {
        self.refinement_value_bits
    }

    /// Number of raw refinement-value bits this staged decoder expects for
    /// one block.
    pub fn expected_raw_refinement_value_bits(
        self,
        block: HtBlockLayout,
    ) -> Result<usize, HtLayoutError> {
        checked_mul(
            block.dimensions().coefficient_count(),
            usize::from(self.refinement_value_bits),
        )
    }

    /// Expected per-stream bit counts for this raw refinement-value decode.
    pub fn expected_raw_refinement_value_bit_counts(
        self,
        block: HtBlockLayout,
    ) -> Result<HtCleanupStreamBitCounts, HtLayoutError> {
        let bits = self.expected_raw_refinement_value_bits(block)?;
        Ok(match self.stream {
            HtCleanupStreamKind::CleanupForward => HtCleanupStreamBitCounts {
                cleanup_forward: bits,
                cleanup_reverse: 0,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::CleanupReverse => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: bits,
                mel: 0,
                vlc: 0,
            },
            HtCleanupStreamKind::Mel => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: bits,
                vlc: 0,
            },
            HtCleanupStreamKind::Vlc => HtCleanupStreamBitCounts {
                cleanup_forward: 0,
                cleanup_reverse: 0,
                mel: 0,
                vlc: bits,
            },
        })
    }

    /// Validate the declared stream layout before side-buffer mutation.
    pub fn check_declared_raw_refinement_value_bits(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
    ) -> Result<(), HtLayoutError> {
        self.expected_raw_refinement_value_bit_counts(block)?
            .check_matches_layout(stream_layout)
    }

    /// Validate the declared stream layout and backing byte slice before
    /// refinement-value storage can mutate.
    pub fn check_available_raw_refinement_value_stream_bytes(
        self,
        block: HtBlockLayout,
        stream_layout: HtCleanupStreamLayout,
        stream_bytes: &[u8],
    ) -> Result<(), HtLayoutError> {
        self.check_declared_raw_refinement_value_bits(block, stream_layout)?;
        let required_stream_bytes = stream_layout.total_bytes();
        if stream_bytes.len() < required_stream_bytes {
            return Err(HtLayoutError::BufferTooSmall {
                required: required_stream_bytes,
                actual: stream_bytes.len(),
            });
        }
        Ok(())
    }
}

/// Fully checked byte-backed raw refinement-value buffer decode request.
///
/// This binds scratch layout, declared cleanup stream layout, raw refinement
/// config, stream bytes, and the caller-owned or reusable value-buffer length
/// before refinement values can be parsed or applied to side-buffer scratch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawRefinementValueBufferDecodeRequest<'a> {
    scratch_layout: HtBlockScratchLayout,
    stream_layout: HtCleanupStreamLayout,
    config: HtRawRefinementValueDecodeConfig,
    bytes: &'a [u8],
}

impl<'a> HtRawRefinementValueBufferDecodeRequest<'a> {
    /// Validate and bundle one byte-backed raw refinement-value buffer request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        stream_layout: HtCleanupStreamLayout,
        config: HtRawRefinementValueDecodeConfig,
        bytes: &'a [u8],
        value_count: usize,
    ) -> Result<Self, HtLayoutError> {
        check_refinement_value_count(scratch_layout.block(), value_count)?;
        config.check_available_raw_refinement_value_stream_bytes(
            scratch_layout.block(),
            stream_layout,
            bytes,
        )?;
        Ok(Self {
            scratch_layout,
            stream_layout,
            config,
            bytes,
        })
    }

    /// Validate and bundle one caller-owned raw refinement-value buffer
    /// request, including scratch capacity.
    pub fn new_with_scratch(
        scratch_layout: HtBlockScratchLayout,
        stream_layout: HtCleanupStreamLayout,
        config: HtRawRefinementValueDecodeConfig,
        bytes: &'a [u8],
        scratch: &[u16],
        value_count: usize,
    ) -> Result<Self, HtLayoutError> {
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        Self::new(scratch_layout, stream_layout, config, bytes, value_count)
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Stream layout covered by this request.
    pub fn stream_layout(self) -> HtCleanupStreamLayout {
        self.stream_layout
    }

    /// Raw refinement-value config covered by this request.
    pub fn config(self) -> HtRawRefinementValueDecodeConfig {
        self.config
    }

    /// Stream bytes covered by this request.
    pub fn stream_bytes(self) -> &'a [u8] {
        self.bytes
    }
}

