/// Raw composed block coefficient decode parameters for the staged HT decoder.
///
/// This groups the temporary raw cleanup-symbol, refinement-value, and
/// magnitude/sign parser configs into one typed block boundary. Future MEL/VLC
/// cleanup and refinement syntax can replace the raw parser internals while
/// preserving the same composed preflight/apply/materialize contract.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawComposedCoefficientDecodeConfig {
    cleanup: HtRawCleanupDecodeConfig,
    refinement: HtRawRefinementValueDecodeConfig,
    magnitude_sign: HtRawMagnitudeSignValueDecodeConfig,
}

impl HtRawComposedCoefficientDecodeConfig {
    /// Create validated raw composed block coefficient decode parameters.
    pub fn new(
        cleanup_stream: HtCleanupStreamKind,
        cleanup_magnitude_sign_bits: u8,
        refinement_stream: HtCleanupStreamKind,
        refinement_value_bits: u8,
        magnitude_sign_stream: HtCleanupStreamKind,
        magnitude_sign_bits: u8,
    ) -> Result<Self, HtLayoutError> {
        Ok(Self {
            cleanup: HtRawCleanupDecodeConfig::new(cleanup_stream, cleanup_magnitude_sign_bits)?,
            refinement: HtRawRefinementValueDecodeConfig::new(
                refinement_stream,
                refinement_value_bits,
            )?,
            magnitude_sign: HtRawMagnitudeSignValueDecodeConfig::new(
                magnitude_sign_stream,
                magnitude_sign_bits,
            )?,
        })
    }

    /// Build a composed config from already-validated raw parser configs.
    pub fn from_configs(
        cleanup: HtRawCleanupDecodeConfig,
        refinement: HtRawRefinementValueDecodeConfig,
        magnitude_sign: HtRawMagnitudeSignValueDecodeConfig,
    ) -> Self {
        Self {
            cleanup,
            refinement,
            magnitude_sign,
        }
    }

    /// Raw cleanup-symbol parser config.
    pub fn cleanup(self) -> HtRawCleanupDecodeConfig {
        self.cleanup
    }

    /// Raw refinement-value parser config.
    pub fn refinement(self) -> HtRawRefinementValueDecodeConfig {
        self.refinement
    }

    /// Raw magnitude/sign parser config.
    pub fn magnitude_sign(self) -> HtRawMagnitudeSignValueDecodeConfig {
        self.magnitude_sign
    }

    /// Validate every declared stream layout in one typed layout bundle.
    pub fn check_declared_raw_composed_layouts(
        self,
        block: HtBlockLayout,
        layouts: HtRawComposedStreamLayouts,
    ) -> Result<(), HtLayoutError> {
        self.cleanup
            .check_declared_raw_side_buffer_bits(block, layouts.cleanup())?;
        self.refinement
            .check_declared_raw_refinement_value_bits(block, layouts.refinement())?;
        self.magnitude_sign
            .check_declared_raw_magnitude_sign_bits(block, layouts.magnitude_sign())
    }

    /// Validate every declared stream layout used by the composed raw block
    /// decode before parser-buffer or side-buffer mutation.
    pub fn check_declared_raw_composed_bits(
        self,
        block: HtBlockLayout,
        cleanup_stream_layout: HtCleanupStreamLayout,
        refinement_stream_layout: HtCleanupStreamLayout,
        magnitude_sign_stream_layout: HtCleanupStreamLayout,
    ) -> Result<(), HtLayoutError> {
        self.check_declared_raw_composed_layouts(
            block,
            HtRawComposedStreamLayouts::new(
                cleanup_stream_layout,
                refinement_stream_layout,
                magnitude_sign_stream_layout,
            ),
        )
    }
}

/// Declared cleanup stream layouts for one composed raw HT coefficient parse.
///
/// This keeps cleanup-symbol, refinement-value, and magnitude/sign stream
/// layout declarations together so parser-output boundaries can preflight
/// byte buffers or prepared cursors without passing three unrelated layout
/// values through every call.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawComposedStreamLayouts {
    cleanup: HtCleanupStreamLayout,
    refinement: HtCleanupStreamLayout,
    magnitude_sign: HtCleanupStreamLayout,
}

impl HtRawComposedStreamLayouts {
    /// Bundle the three stream layouts used by one composed raw block parse.
    pub fn new(
        cleanup: HtCleanupStreamLayout,
        refinement: HtCleanupStreamLayout,
        magnitude_sign: HtCleanupStreamLayout,
    ) -> Self {
        Self {
            cleanup,
            refinement,
            magnitude_sign,
        }
    }

    /// Cleanup-symbol stream layout.
    pub fn cleanup(self) -> HtCleanupStreamLayout {
        self.cleanup
    }

    /// Refinement-value stream layout.
    pub fn refinement(self) -> HtCleanupStreamLayout {
        self.refinement
    }

    /// Magnitude/sign stream layout.
    pub fn magnitude_sign(self) -> HtCleanupStreamLayout {
        self.magnitude_sign
    }

    /// Validate caller-provided byte buffers against every declared stream
    /// layout before any parser-output mutation.
    pub fn check_byte_slices(
        self,
        cleanup_bytes: &[u8],
        refinement_bytes: &[u8],
        magnitude_sign_bytes: &[u8],
    ) -> Result<(), HtLayoutError> {
        let _ = self.cleanup.split_streams(cleanup_bytes)?;
        let _ = self.refinement.split_streams(refinement_bytes)?;
        let _ = self.magnitude_sign.split_streams(magnitude_sign_bytes)?;
        Ok(())
    }

    /// Validate that prepared bit cursors are still at the start of stream
    /// partitions whose remaining bit counts exactly match the declared
    /// layouts.
    pub fn check_fresh_cursors(
        self,
        cleanup_cursors: &HtCleanupStreamBitCursors<'_>,
        refinement_cursors: &HtCleanupStreamBitCursors<'_>,
        magnitude_sign_cursors: &HtCleanupStreamBitCursors<'_>,
    ) -> Result<(), HtLayoutError> {
        check_fresh_cursor_layout(cleanup_cursors, self.cleanup)?;
        check_fresh_cursor_layout(refinement_cursors, self.refinement)?;
        check_fresh_cursor_layout(magnitude_sign_cursors, self.magnitude_sign)
    }
}

/// Block-local raw composed coefficient decode declarations after validation.
///
/// This pairs the block geometry, three stream layouts, and three raw parser
/// configs once so parser-output boundaries can accept one checked declaration
/// object instead of repeatedly carrying an unchecked `(block, layouts, config)`
/// triple.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawComposedCoefficientDecodePlan {
    block: HtBlockLayout,
    layouts: HtRawComposedStreamLayouts,
    config: HtRawComposedCoefficientDecodeConfig,
}

impl HtRawComposedCoefficientDecodePlan {
    /// Validate and bundle one raw composed block decode declaration.
    pub fn new(
        block: HtBlockLayout,
        layouts: HtRawComposedStreamLayouts,
        config: HtRawComposedCoefficientDecodeConfig,
    ) -> Result<Self, HtLayoutError> {
        config.check_declared_raw_composed_layouts(block, layouts)?;
        Ok(Self {
            block,
            layouts,
            config,
        })
    }

    /// Block geometry covered by this declaration.
    pub fn block(self) -> HtBlockLayout {
        self.block
    }

    /// Stream layouts covered by this declaration.
    pub fn layouts(self) -> HtRawComposedStreamLayouts {
        self.layouts
    }

    /// Parser configs covered by this declaration.
    pub fn config(self) -> HtRawComposedCoefficientDecodeConfig {
        self.config
    }

    /// Validate that this declaration is being used with its original block
    /// geometry.
    pub fn check_block(self, block: HtBlockLayout) -> Result<(), HtLayoutError> {
        if self.block == block {
            return Ok(());
        }
        let expected = self.block.dimensions();
        let actual = block.dimensions();
        Err(HtLayoutError::BlockLayoutMismatch {
            expected_width: expected.width(),
            expected_height: expected.height(),
            actual_width: actual.width(),
            actual_height: actual.height(),
        })
    }

    /// Validate block identity and coefficient-output capacity for this composed
    /// plan before scratch or parser-output storage can mutate.
    pub fn check_coefficient_output_capacity(
        self,
        scratch_layout: HtBlockScratchLayout,
        output: &[i32],
    ) -> Result<usize, HtLayoutError> {
        self.check_block(scratch_layout.block())?;
        let required = self.block.dimensions().coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        Ok(required)
    }

    /// Validate byte backing for every stream covered by this composed plan.
    pub fn check_available_raw_composed_stream_bytes(
        self,
        bytes: HtRawComposedStreamBytes<'_>,
    ) -> Result<(), HtLayoutError> {
        bytes.check_layouts(self.layouts)
    }

    /// Validate caller-owned parser-output plane storage for this composed plan.
    pub fn check_parsed_coefficient_plane_buffers(
        self,
        buffers: &HtParsedCoefficientPlaneBuffers<'_>,
    ) -> Result<(), HtLayoutError> {
        buffers.check_lengths_for_block(self.block)
    }

    /// Validate that prepared cursor backing for every stream covered by this
    /// composed plan is still fresh.
    pub fn check_fresh_raw_composed_stream_cursors<
        'cursor,
        'cleanup,
        'refinement,
        'magnitude_sign,
    >(
        self,
        cursors: &HtRawComposedStreamBitCursorRefs<'cursor, 'cleanup, 'refinement, 'magnitude_sign>,
    ) -> Result<(), HtLayoutError> {
        cursors.check_fresh(self.layouts)
    }
}

/// Fully checked byte-backed raw composed coefficient decode request.
///
/// This binds reusable scratch layout, validated raw composed parser plan,
/// stream bytes, and coefficient-output capacity before parser-output buffers,
/// side-buffer scratch, or coefficient output can be mutated. Future real
/// MEL/VLC/refinement parsers can preserve this request boundary while
/// replacing the temporary raw stream-byte fallback.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawComposedCoefficientDecodeRequest<'a> {
    scratch_layout: HtBlockScratchLayout,
    plan: HtRawComposedCoefficientDecodePlan,
    bytes: HtRawComposedStreamBytes<'a>,
}

impl<'a> HtRawComposedCoefficientDecodeRequest<'a> {
    /// Validate and bundle one byte-backed raw composed coefficient decode
    /// request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'a>,
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        let _ = plan.check_coefficient_output_capacity(scratch_layout, output)?;
        plan.check_available_raw_composed_stream_bytes(bytes)?;
        Ok(Self {
            scratch_layout,
            plan,
            bytes,
        })
    }

    /// Validate and bundle one caller-owned byte-backed raw composed
    /// coefficient decode request, including scratch capacity.
    pub fn new_with_scratch(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'a>,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        Self::new(scratch_layout, plan, bytes, output)
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Raw composed decode plan covered by this request.
    pub fn plan(self) -> HtRawComposedCoefficientDecodePlan {
        self.plan
    }

    /// Stream bytes covered by this request.
    pub fn bytes(self) -> HtRawComposedStreamBytes<'a> {
        self.bytes
    }

    /// Split the checked byte bundle into fresh cleanup/refinement/magnitude
    /// cursor groups.
    pub fn split_fresh_bit_cursors(
        self,
    ) -> Result<HtRawComposedStreamBitCursors<'a>, HtLayoutError> {
        self.bytes.split_fresh_bit_cursors(self.plan.layouts())
    }
}

/// Fully checked cursor-backed raw composed coefficient decode request.
