/// Fully checked byte-backed raw composed plane-buffer coefficient request.
///
/// This extends [`HtRawComposedCoefficientDecodeRequest`] with caller-owned
/// parser-output plane storage. It validates scratch layout, output capacity,
/// declared stream bytes, and all three parser-output buffers before any fresh
/// cursor is split or any parsed plane can be mutated.
pub struct HtRawComposedPlaneBufferCoefficientDecodeRequest<'bytes, 'buffers> {
    scratch_layout: HtBlockScratchLayout,
    plan: HtRawComposedCoefficientDecodePlan,
    bytes: HtRawComposedStreamBytes<'bytes>,
    buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
}

impl<'bytes, 'buffers> HtRawComposedPlaneBufferCoefficientDecodeRequest<'bytes, 'buffers> {
    /// Validate and bundle one byte-backed raw composed plane-buffer
    /// coefficient request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        let required = Self::preflight(scratch_layout, plan, bytes, output)?;
        Self::from_preflighted(scratch_layout, plan, bytes, buffers, required)
    }

    fn preflight(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        output: &[i32],
    ) -> Result<usize, HtLayoutError> {
        let required = plan.check_coefficient_output_capacity(scratch_layout, output)?;
        plan.check_available_raw_composed_stream_bytes(bytes)?;
        Ok(required)
    }

    fn from_preflighted(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
        _required: usize,
    ) -> Result<Self, HtLayoutError> {
        plan.check_parsed_coefficient_plane_buffers(&buffers)?;
        Ok(Self {
            scratch_layout,
            plan,
            bytes,
            buffers,
        })
    }

    /// Validate and bundle one caller-owned byte-backed raw composed
    /// plane-buffer coefficient request, including scratch capacity.
    pub fn new_with_scratch(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        scratch: &[u16],
        buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        Self::new(scratch_layout, plan, bytes, buffers, output)
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Raw composed decode plan covered by this request.
    pub fn plan(&self) -> HtRawComposedCoefficientDecodePlan {
        self.plan
    }

    /// Stream bytes covered by this request.
    pub fn bytes(&self) -> HtRawComposedStreamBytes<'bytes> {
        self.bytes
    }

    /// Split the checked byte bundle and return the checked parser-output
    /// buffers for the decode/materialization path.
    pub fn into_fresh_cursor_parts(
        self,
    ) -> Result<
        (
            HtRawComposedCoefficientDecodePlan,
            HtRawComposedStreamBitCursors<'bytes>,
            HtParsedCoefficientPlaneBuffers<'buffers>,
        ),
        HtLayoutError,
    > {
        let cursors = self.bytes.split_fresh_bit_cursors(self.plan.layouts())?;
        Ok((self.plan, cursors, self.buffers))
    }

    /// Fill the checked parser-output buffers from the checked stream bytes.
    pub fn decode(
        self,
    ) -> Result<
        Option<(
            HtRawComposedCoefficientDecodePlan,
            HtParsedCoefficientPlaneBuffers<'buffers>,
        )>,
        HtLayoutError,
    > {
        HtRawComposedParserOutputRequest::new(self.plan, self.bytes, self.buffers)?.decode()
    }
}

