/// Caller-provided bytes for one composed raw HT coefficient parse.
///
/// This is the byte-buffer counterpart to `HtRawComposedStreamLayouts`.
/// Keeping the three byte slices together lets byte-backed raw fallback paths
/// split fresh bit cursors as one checked operation before parser-output
/// mutation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtRawComposedStreamBytes<'a> {
    cleanup: &'a [u8],
    refinement: &'a [u8],
    magnitude_sign: &'a [u8],
}

impl<'a> HtRawComposedStreamBytes<'a> {
    /// Bundle the three byte slices used by one composed raw block parse.
    pub fn new(cleanup: &'a [u8], refinement: &'a [u8], magnitude_sign: &'a [u8]) -> Self {
        Self {
            cleanup,
            refinement,
            magnitude_sign,
        }
    }

    /// Cleanup-symbol stream bytes.
    pub fn cleanup(self) -> &'a [u8] {
        self.cleanup
    }

    /// Refinement-value stream bytes.
    pub fn refinement(self) -> &'a [u8] {
        self.refinement
    }

    /// Magnitude/sign stream bytes.
    pub fn magnitude_sign(self) -> &'a [u8] {
        self.magnitude_sign
    }

    /// Validate the byte slices against the corresponding declared layouts.
    pub fn check_layouts(self, layouts: HtRawComposedStreamLayouts) -> Result<(), HtLayoutError> {
        layouts.check_byte_slices(self.cleanup, self.refinement, self.magnitude_sign)
    }

    /// Split all three byte slices into fresh bit cursors using the matching
    /// declared stream layouts.
    pub fn split_fresh_bit_cursors(
        self,
        layouts: HtRawComposedStreamLayouts,
    ) -> Result<HtRawComposedStreamBitCursors<'a>, HtLayoutError> {
        let cleanup = layouts.cleanup().split_streams(self.cleanup)?.bit_cursors();
        let refinement = layouts
            .refinement()
            .split_streams(self.refinement)?
            .bit_cursors();
        let magnitude_sign = layouts
            .magnitude_sign()
            .split_streams(self.magnitude_sign)?
            .bit_cursors();
        Ok(HtRawComposedStreamBitCursors::new(
            cleanup,
            refinement,
            magnitude_sign,
        ))
    }
}

/// Fresh bit cursors for one composed raw HT coefficient parse.
#[derive(Debug, Clone)]
pub struct HtRawComposedStreamBitCursors<'a> {
    cleanup: HtCleanupStreamBitCursors<'a>,
    refinement: HtCleanupStreamBitCursors<'a>,
    magnitude_sign: HtCleanupStreamBitCursors<'a>,
}

impl<'a> HtRawComposedStreamBitCursors<'a> {
    /// Bundle the three cursor groups used by one composed raw block parse.
    pub fn new(
        cleanup: HtCleanupStreamBitCursors<'a>,
        refinement: HtCleanupStreamBitCursors<'a>,
        magnitude_sign: HtCleanupStreamBitCursors<'a>,
    ) -> Self {
        Self {
            cleanup,
            refinement,
            magnitude_sign,
        }
    }

    /// Cleanup-symbol stream cursors.
    pub fn cleanup(&self) -> &HtCleanupStreamBitCursors<'a> {
        &self.cleanup
    }

    /// Mutable cleanup-symbol stream cursors.
    pub fn cleanup_mut(&mut self) -> &mut HtCleanupStreamBitCursors<'a> {
        &mut self.cleanup
    }

    /// Refinement-value stream cursors.
    pub fn refinement(&self) -> &HtCleanupStreamBitCursors<'a> {
        &self.refinement
    }

    /// Mutable refinement-value stream cursors.
    pub fn refinement_mut(&mut self) -> &mut HtCleanupStreamBitCursors<'a> {
        &mut self.refinement
    }

    /// Magnitude/sign stream cursors.
    pub fn magnitude_sign(&self) -> &HtCleanupStreamBitCursors<'a> {
        &self.magnitude_sign
    }

    /// Mutable magnitude/sign stream cursors.
    pub fn magnitude_sign_mut(&mut self) -> &mut HtCleanupStreamBitCursors<'a> {
        &mut self.magnitude_sign
    }

    /// Borrow all three cursor groups as one mutable cursor-reference
    /// contract without moving the owned bundle.
    pub fn as_mut_refs(&mut self) -> HtRawComposedStreamBitCursorRefs<'_, 'a, 'a, 'a> {
        HtRawComposedStreamBitCursorRefs::new(
            &mut self.cleanup,
            &mut self.refinement,
            &mut self.magnitude_sign,
        )
    }

    /// Validate every cursor group is still at the start of a partition whose
    /// remaining bits match the declared layouts.
    pub fn check_fresh(&self, layouts: HtRawComposedStreamLayouts) -> Result<(), HtLayoutError> {
        layouts.check_fresh_cursors(&self.cleanup, &self.refinement, &self.magnitude_sign)
    }
}

/// Borrowed fresh bit cursors for one composed raw HT coefficient parse.
///
/// This is the no-allocation counterpart to `HtRawComposedStreamBitCursors` for
/// callers that retain ownership of the individual cursor groups.
pub struct HtRawComposedStreamBitCursorRefs<'cursor, 'cleanup, 'refinement, 'magnitude_sign> {
    cleanup: &'cursor mut HtCleanupStreamBitCursors<'cleanup>,
    refinement: &'cursor mut HtCleanupStreamBitCursors<'refinement>,
    magnitude_sign: &'cursor mut HtCleanupStreamBitCursors<'magnitude_sign>,
}

impl<'cursor, 'cleanup, 'refinement, 'magnitude_sign>
    HtRawComposedStreamBitCursorRefs<'cursor, 'cleanup, 'refinement, 'magnitude_sign>
{
    /// Bundle borrowed cursor groups used by one composed raw block parse.
    pub fn new(
        cleanup: &'cursor mut HtCleanupStreamBitCursors<'cleanup>,
        refinement: &'cursor mut HtCleanupStreamBitCursors<'refinement>,
        magnitude_sign: &'cursor mut HtCleanupStreamBitCursors<'magnitude_sign>,
    ) -> Self {
        Self {
            cleanup,
            refinement,
            magnitude_sign,
        }
    }

    /// Cleanup-symbol stream cursors.
    pub fn cleanup(&self) -> &HtCleanupStreamBitCursors<'cleanup> {
        &*self.cleanup
    }

    /// Mutable cleanup-symbol stream cursors.
    pub fn cleanup_mut(&mut self) -> &mut HtCleanupStreamBitCursors<'cleanup> {
        &mut *self.cleanup
    }

    /// Refinement-value stream cursors.
    pub fn refinement(&self) -> &HtCleanupStreamBitCursors<'refinement> {
        &*self.refinement
    }

    /// Mutable refinement-value stream cursors.
    pub fn refinement_mut(&mut self) -> &mut HtCleanupStreamBitCursors<'refinement> {
        &mut *self.refinement
    }

    /// Magnitude/sign stream cursors.
    pub fn magnitude_sign(&self) -> &HtCleanupStreamBitCursors<'magnitude_sign> {
        &*self.magnitude_sign
    }

    /// Mutable magnitude/sign stream cursors.
    pub fn magnitude_sign_mut(&mut self) -> &mut HtCleanupStreamBitCursors<'magnitude_sign> {
        &mut *self.magnitude_sign
    }

    /// Validate every borrowed cursor group is still at the start of a
    /// partition whose remaining bits match the declared layouts.
    pub fn check_fresh(&self, layouts: HtRawComposedStreamLayouts) -> Result<(), HtLayoutError> {
        layouts.check_fresh_cursors(self.cleanup(), self.refinement(), self.magnitude_sign())
    }

    /// Fill all raw composed parser-output planes through the shared
    /// stream-consuming cursor helpers.
    ///
    /// This keeps temporary raw cleanup/refinement/magnitude parsing behind
    /// the same typed output boundary future MEL/VLC/refinement parsers will
    /// use, while preserving each plane's same-position output guard.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_parser_outputs(
        &mut self,
        plan: HtRawComposedCoefficientDecodePlan,
        mut buffers: HtParsedCoefficientPlaneBuffers<'_>,
    ) -> Result<Option<()>, HtLayoutError> {
        let block = plan.block();
        let config = plan.config();
        if self
            .cleanup_mut()
            .decode_raw_cleanup_symbols_with_config(
                block,
                plan.layouts().cleanup(),
                config.cleanup(),
                buffers.symbols_mut(),
            )?
            .is_none()
        {
            return Ok(None);
        }
        if self
            .refinement_mut()
            .decode_raw_refinement_values_with_config(
                block,
                plan.layouts().refinement(),
                config.refinement(),
                buffers.refinement_values_mut(),
            )?
            .is_none()
        {
            return Ok(None);
        }
        if self
            .magnitude_sign_mut()
            .decode_raw_magnitude_sign_values_with_config(
                block,
                plan.layouts().magnitude_sign(),
                config.magnitude_sign(),
                buffers.magnitude_sign_values_mut(),
            )?
            .is_none()
        {
            return Ok(None);
        }
        Ok(Some(()))
    }
}

/// Already-parsed HT coefficient-local planes for block materialization.
///
/// Future real MEL/VLC/refinement parsers can produce this borrowed bundle
/// after parsing their stream syntax, then hand it to caller-owned or std
/// reusable materialization without falling back to the temporary raw stream
/// parser boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtParsedCoefficientPlanes<'a> {
    symbols: &'a [HtCleanupCoefficientSymbol],
    refinement_values: &'a [HtCoefficientRefinementValue],
    magnitude_sign_values: &'a [HtCoefficientMagnitudeSignValue],
    magnitude_sign_bits: u8,
}

impl<'a> HtParsedCoefficientPlanes<'a> {
    /// Create a borrowed parsed-plane bundle.
    pub fn new(
        symbols: &'a [HtCleanupCoefficientSymbol],
        refinement_values: &'a [HtCoefficientRefinementValue],
        magnitude_sign_values: &'a [HtCoefficientMagnitudeSignValue],
        magnitude_sign_bits: u8,
    ) -> Result<Self, HtLayoutError> {
        if magnitude_sign_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok(Self {
            symbols,
            refinement_values,
            magnitude_sign_values,
            magnitude_sign_bits,
        })
    }

    /// Parsed cleanup-symbol plane.
    pub fn symbols(self) -> &'a [HtCleanupCoefficientSymbol] {
        self.symbols
    }

    /// Parsed refinement-value plane.
    pub fn refinement_values(self) -> &'a [HtCoefficientRefinementValue] {
        self.refinement_values
    }

    /// Parsed magnitude/sign-value plane.
    pub fn magnitude_sign_values(self) -> &'a [HtCoefficientMagnitudeSignValue] {
        self.magnitude_sign_values
    }

    /// Number of raw magnitude/sign bits represented by each magnitude/sign
    /// value.
    pub fn magnitude_sign_bits(self) -> u8 {
        self.magnitude_sign_bits
    }

    /// Validate that all parsed planes match one HT block traversal.
    pub fn validate_for_block(self, block: HtBlockLayout) -> Result<Option<()>, HtLayoutError> {
        if validate_cleanup_symbol_plane(block, self.symbols)?.is_none()
            || validate_refinement_value_plane(block, self.refinement_values)?.is_none()
            || validate_magnitude_sign_value_plane(block, self.magnitude_sign_values)?.is_none()
        {
            return Ok(None);
        }
        Ok(Some(()))
    }
}

/// Fully checked parsed-plane coefficient materialization request.
///
/// This binds scratch layout, already-parsed coefficient-local planes, and
/// coefficient-output capacity before caller-owned or reusable side-buffer
/// scratch can be cleared. Real MEL/VLC/refinement parsers can hand their
/// parsed planes through this request after syntax parsing succeeds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtParsedCoefficientMaterializationRequest<'a> {
    scratch_layout: HtBlockScratchLayout,
    planes: HtParsedCoefficientPlanes<'a>,
    sample_precision_bits: Option<u8>,
}

impl<'a> HtParsedCoefficientMaterializationRequest<'a> {
    /// Validate and bundle one parsed-plane materialization request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        Self::new_with_optional_sample_precision(scratch_layout, planes, None, output)
    }

    /// Validate and bundle one parsed-plane materialization request with
    /// known sample precision metadata.
    pub fn new_with_sample_precision(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
        sample_precision_bits: u8,
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        Self::new_with_optional_sample_precision(
            scratch_layout,
            planes,
            Some(sample_precision_bits),
            output,
        )
    }

    fn new_with_optional_sample_precision(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
        sample_precision_bits: Option<u8>,
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        let block = scratch_layout.block();
        let required = block.dimensions().coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        if planes.validate_for_block(block)?.is_none() {
            return Ok(None);
        }
        Ok(Some(Self {
            scratch_layout,
            planes,
            sample_precision_bits,
        }))
    }

    /// Validate and bundle one caller-owned parsed-plane materialization
    /// request, including scratch capacity.
    ///
    /// This is the no-std block boundary for parser implementations that own
    /// side-buffer scratch. It rejects short scratch before returning a request
    /// that can clear scratch or write coefficient output.
    pub fn new_with_scratch(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        Self::new_with_scratch_and_optional_sample_precision(
            scratch_layout,
            planes,
            None,
            scratch,
            output,
        )
    }

    /// Validate and bundle one caller-owned parsed-plane materialization
    /// request with known sample precision metadata.
    pub fn new_with_scratch_and_sample_precision(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
        sample_precision_bits: u8,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        Self::new_with_scratch_and_optional_sample_precision(
            scratch_layout,
            planes,
            Some(sample_precision_bits),
            scratch,
            output,
        )
    }

    fn new_with_scratch_and_optional_sample_precision(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
        sample_precision_bits: Option<u8>,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        Self::new_with_optional_sample_precision(
            scratch_layout,
            planes,
            sample_precision_bits,
            output,
        )
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Parsed coefficient planes covered by this request.
    pub fn planes(self) -> HtParsedCoefficientPlanes<'a> {
        self.planes
    }

    /// Source image sample precision, when this request came from a decode
    /// candidate carrying marker metadata.
    pub fn sample_precision_bits(self) -> Option<u8> {
        self.sample_precision_bits
    }

    /// Materialize this checked parsed-plane request through caller-owned
    /// side-buffer scratch and coefficient output.
    pub fn materialize(
        self,
        scratch: &mut [u16],
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let scratch_layout = self.scratch_layout;
        let planes = self.planes;
        let mut views = HtCleanupDecodeViews {
            scratch: scratch_layout.prepare_scratch(scratch)?,
            streams: HtCleanupStreamLayout::from_lengths(0, 0, 0, 0)?
                .split_streams(&[])?
                .bit_cursors(),
        };
        if views
            .apply_cleanup_refinement_and_magnitude_sign_planes(
                scratch_layout.block(),
                planes.symbols(),
                planes.refinement_values(),
                planes.magnitude_sign_values(),
            )?
            .is_none()
        {
            return Ok(None);
        }
        views.materialize_raw_cleanup_coefficients(
            scratch_layout.block(),
            output,
            planes.magnitude_sign_bits(),
        )
    }

    #[cfg(feature = "std")]
    fn from_validated_planes(
        scratch_layout: HtBlockScratchLayout,
        planes: HtParsedCoefficientPlanes<'a>,
    ) -> Self {
        Self {
            scratch_layout,
            planes,
            sample_precision_bits: None,
        }
    }
}

/// Fully checked real-segment VLC cleanup parsed-plane materialization request.
///
/// This binds scratch layout, typed cleanup side inputs, parser-output plane
/// storage, context-state capacity, MagSgn width, scratch capacity, and
/// coefficient-output capacity before the real cleanup segment bridge can clear
/// scratch, advance segment cursors, mutate context/MEL state, fill parsed
/// planes, or write coefficient output.
pub struct HtVlcCleanupParsedPlaneMaterializationRequest<'side_inputs, 'buffers> {
    scratch_layout: HtBlockScratchLayout,
    side_inputs: HtVlcBlockCleanupSideInputs<'side_inputs>,
    buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
    magnitude_sign_bits: u8,
}

impl<'side_inputs, 'buffers> HtVlcCleanupParsedPlaneMaterializationRequest<'side_inputs, 'buffers> {
    /// Validate and bundle one caller-owned real-segment VLC cleanup parsed-plane
    /// materialization request.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        side_inputs: HtVlcBlockCleanupSideInputs<'side_inputs>,
        context_states: &[HtVlcContextProgression],
        buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
        magnitude_sign_bits: u8,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        if magnitude_sign_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        let block = scratch_layout.block();
        let required_context_states = block.line_pair_count();
        if context_states.len() < required_context_states {
            return Err(HtLayoutError::BufferTooSmall {
                required: required_context_states,
                actual: context_states.len(),
            });
        }
        buffers.check_lengths_for_block(block)?;
        let required = block.dimensions().coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }

        Ok(Self {
            scratch_layout,
            side_inputs,
            buffers,
            magnitude_sign_bits,
        })
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Split the checked request into decode and materialization parts.
    pub fn into_parts(
        self,
    ) -> (
        HtVlcBlockCleanupSideInputs<'side_inputs>,
        HtParsedCoefficientPlaneBuffers<'buffers>,
        u8,
    ) {
        (self.side_inputs, self.buffers, self.magnitude_sign_bits)
    }
}

