/// Fully checked real-segment VLC cleanup-output paired segment-group
/// materialization request.
///
/// This wraps the side-input-free segment-group cleanup-output request with the
/// additional paired-only eligibility check: blocks with odd-tail cleanup groups
/// return `Ok(None)` before any scratch, segment cursor, context/MEL,
/// cleanup-output, or coefficient-output mutation.
pub struct HtVlcCleanupOutputPairedSegmentGroupMaterializationRequest<'cleanup> {
    inner: HtVlcCleanupOutputSegmentGroupMaterializationRequest<'cleanup>,
}

impl<'cleanup> HtVlcCleanupOutputPairedSegmentGroupMaterializationRequest<'cleanup> {
    /// Validate and bundle one caller-owned paired segment-group materialization
    /// request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        context_states: &[HtVlcContextProgression],
        cleanup_outputs: &'cleanup mut [HtVlcCleanupCoefficientOutput],
        missing_most_significant_bitplanes: u8,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Option<Self>, HtLayoutError> {
        let request = HtVlcCleanupOutputSegmentGroupMaterializationRequest::new(
            scratch_layout,
            context_states,
            cleanup_outputs,
            missing_most_significant_bitplanes,
            scratch,
            output,
        )?;
        if scratch_layout
            .block()
            .vlc_cleanup_side_input_counts()
            .odd_tail_u_values
            != 0
        {
            return Ok(None);
        }

        Ok(Some(Self { inner: request }))
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.inner.scratch_layout()
    }

    /// Active coefficient count covered by this request.
    pub fn required(&self) -> usize {
        self.inner.required()
    }

    /// Split the checked request into decode and materialization parts.
    pub fn into_parts(self) -> (&'cleanup mut [HtVlcCleanupCoefficientOutput], u8, usize) {
        self.inner.into_parts()
    }
}

/// Fully checked real-segment VLC cleanup-symbol decode request that
/// materializes through raw parser-output inputs.
///
/// This bridges real cleanup-symbol traversal into the temporary raw
/// refinement/MagSgn parser-output materializer. It validates block identity,
/// cleanup-symbol storage, context-state capacity, scratch capacity,
/// coefficient-output capacity, raw MagSgn width, and Part 15 side-input
/// readiness before scratch can be cleared, segment cursors advanced, context/MEL
/// state mutated, cleanup symbols written, or coefficient output written.
pub struct HtVlcCleanupRawParserOutputMaterializationRequest<'inputs, 'symbols> {
    scratch_layout: HtBlockScratchLayout,
    inputs: HtRawSegmentParserOutputMaterializationInputs<'inputs>,
    cleanup_symbols: &'symbols mut [HtCleanupCoefficientSymbol],
    raw_magnitude_sign_bits: u8,
}

impl<'inputs, 'symbols> HtVlcCleanupRawParserOutputMaterializationRequest<'inputs, 'symbols> {
    /// Validate and bundle one caller-owned raw parser-output materialization
    /// bridge request.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        context_states: &[HtVlcContextProgression],
        inputs: HtRawSegmentParserOutputMaterializationInputs<'inputs>,
        cleanup_symbols: &'symbols mut [HtCleanupCoefficientSymbol],
        raw_magnitude_sign_bits: u8,
        scratch: &[u16],
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        let block = scratch_layout.block();
        check_block_layout_match(block, inputs.block())?;
        check_cleanup_symbol_count(block, cleanup_symbols.len())?;
        let required_context_states = block.line_pair_count();
        if context_states.len() < required_context_states {
            return Err(HtLayoutError::BufferTooSmall {
                required: required_context_states,
                actual: context_states.len(),
            });
        }
        if scratch.len() < scratch_layout.total_words() {
            return Err(HtLayoutError::BufferTooSmall {
                required: scratch_layout.total_words(),
                actual: scratch.len(),
            });
        }
        if output.len() < inputs.required() {
            return Err(HtLayoutError::BufferTooSmall {
                required: inputs.required(),
                actual: output.len(),
            });
        }
        if raw_magnitude_sign_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        let _ = inputs.part15_side_input_outcome()?;

        Ok(Self {
            scratch_layout,
            inputs,
            cleanup_symbols,
            raw_magnitude_sign_bits,
        })
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Active coefficient count covered by this request.
    pub fn required(&self) -> usize {
        self.inputs.required()
    }

    /// Split the checked request into decode and materialization parts.
    pub fn into_parts(
        self,
    ) -> (
        HtRawSegmentParserOutputMaterializationInputs<'inputs>,
        &'symbols mut [HtCleanupCoefficientSymbol],
        u8,
    ) {
        (
            self.inputs,
            self.cleanup_symbols,
            self.raw_magnitude_sign_bits,
        )
    }
}

/// Caller-owned mutable storage for complete HT parsed coefficient planes.
///
/// This is the writable counterpart to `HtParsedCoefficientPlanes`. Temporary
/// raw parsers and future real MEL/VLC/refinement parsers can fill these
/// buffers as one typed block output contract, then borrow them as immutable
/// parsed planes for validation and materialization.
#[derive(Debug)]
pub struct HtParsedCoefficientPlaneBuffers<'a> {
    symbols: &'a mut [HtCleanupCoefficientSymbol],
    refinement_values: &'a mut [HtCoefficientRefinementValue],
    magnitude_sign_values: &'a mut [HtCoefficientMagnitudeSignValue],
}

impl<'a> HtParsedCoefficientPlaneBuffers<'a> {
    /// Bundle caller-owned parsed-plane storage.
    pub fn new(
        symbols: &'a mut [HtCleanupCoefficientSymbol],
        refinement_values: &'a mut [HtCoefficientRefinementValue],
        magnitude_sign_values: &'a mut [HtCoefficientMagnitudeSignValue],
    ) -> Self {
        Self {
            symbols,
            refinement_values,
            magnitude_sign_values,
        }
    }

    /// Cleanup-symbol storage.
    pub fn symbols(&self) -> &[HtCleanupCoefficientSymbol] {
        self.symbols
    }

    /// Mutable cleanup-symbol storage.
    pub fn symbols_mut(&mut self) -> &mut [HtCleanupCoefficientSymbol] {
        self.symbols
    }

    /// Refinement-value storage.
    pub fn refinement_values(&self) -> &[HtCoefficientRefinementValue] {
        self.refinement_values
    }

    /// Mutable refinement-value storage.
    pub fn refinement_values_mut(&mut self) -> &mut [HtCoefficientRefinementValue] {
        self.refinement_values
    }

    /// Magnitude/sign-value storage.
    pub fn magnitude_sign_values(&self) -> &[HtCoefficientMagnitudeSignValue] {
        self.magnitude_sign_values
    }

    /// Mutable magnitude/sign-value storage.
    pub fn magnitude_sign_values_mut(&mut self) -> &mut [HtCoefficientMagnitudeSignValue] {
        self.magnitude_sign_values
    }

    /// Validate that every mutable plane has the block's coefficient count.
    pub fn check_lengths_for_block(&self, block: HtBlockLayout) -> Result<(), HtLayoutError> {
        let required = block.dimensions().coefficient_count();
        if self.symbols.len() != required {
            return Err(HtLayoutError::SymbolCountMismatch {
                required,
                actual: self.symbols.len(),
            });
        }
        if self.refinement_values.len() != required {
            return Err(HtLayoutError::RefinementValueCountMismatch {
                required,
                actual: self.refinement_values.len(),
            });
        }
        if self.magnitude_sign_values.len() != required {
            return Err(HtLayoutError::MagnitudeSignValueCountMismatch {
                required,
                actual: self.magnitude_sign_values.len(),
            });
        }
        Ok(())
    }

    /// Borrow the filled buffers as immutable parsed planes.
    pub fn as_planes(
        &self,
        magnitude_sign_bits: u8,
    ) -> Result<HtParsedCoefficientPlanes<'_>, HtLayoutError> {
        HtParsedCoefficientPlanes::new(
            self.symbols,
            self.refinement_values,
            self.magnitude_sign_values,
            magnitude_sign_bits,
        )
    }

    /// Reborrow the mutable parser-output planes as a short-lived typed bundle.
    pub fn reborrow(&mut self) -> HtParsedCoefficientPlaneBuffers<'_> {
        HtParsedCoefficientPlaneBuffers::new(
            &mut *self.symbols,
            &mut *self.refinement_values,
            &mut *self.magnitude_sign_values,
        )
    }

    /// Decode all temporary raw composed coefficient planes into this
    /// caller-owned parser-output bundle without preparing or mutating
    /// side-buffer scratch.
    ///
    /// The method preflights output lengths, all declared raw stream bit
    /// counts, and all stream byte buffers before filling any parsed plane, so
    /// future parser drivers can share one all-or-nothing raw fallback
    /// boundary while real MEL/VLC/refinement syntax is being built.
    #[allow(clippy::too_many_arguments)]
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_with_config(
        &mut self,
        block: HtBlockLayout,
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_stream_bytes: &[u8],
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_stream_bytes: &[u8],
        magnitude_sign_stream_layout: HtCleanupStreamLayout,
        magnitude_sign_stream_bytes: &[u8],
        config: HtRawComposedCoefficientDecodeConfig,
    ) -> Result<Option<()>, HtLayoutError> {
        let layouts = HtRawComposedStreamLayouts::new(
            cleanup_stream_layout,
            refinement_stream_layout,
            magnitude_sign_stream_layout,
        );
        let bytes = HtRawComposedStreamBytes::new(
            cleanup_stream_bytes,
            refinement_stream_bytes,
            magnitude_sign_stream_bytes,
        );
        self.decode_raw_cleanup_refinement_and_magnitude_sign_from_stream_bytes_with_config(
            block, layouts, bytes, config,
        )
    }

    /// Decode all temporary raw composed coefficient planes from one typed
    /// composed byte bundle into this parser-output bundle.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_from_stream_bytes_with_config(
        &mut self,
        block: HtBlockLayout,
        layouts: HtRawComposedStreamLayouts,
        bytes: HtRawComposedStreamBytes<'_>,
        config: HtRawComposedCoefficientDecodeConfig,
    ) -> Result<Option<()>, HtLayoutError> {
        let plan = HtRawComposedCoefficientDecodePlan::new(block, layouts, config)?;
        self.decode_raw_cleanup_refinement_and_magnitude_sign_from_stream_bytes_with_plan(
            plan, bytes,
        )
    }

    /// Decode all temporary raw composed coefficient planes from one typed
    /// composed byte bundle using one validated raw composed decode plan.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_from_stream_bytes_with_plan(
        &mut self,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'_>,
    ) -> Result<Option<()>, HtLayoutError> {
        let request = HtRawComposedParserOutputRequest::new(plan, bytes, self.reborrow())?;
        Ok(request.decode()?.map(|_| ()))
    }

    /// Decode all temporary raw composed coefficient planes from one prepared
    /// fresh cursor bundle into this parser-output bundle.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursor_bundle_with_config(
        &mut self,
        block: HtBlockLayout,
        layouts: HtRawComposedStreamLayouts,
        cursors: &mut HtRawComposedStreamBitCursors<'_>,
        config: HtRawComposedCoefficientDecodeConfig,
    ) -> Result<Option<()>, HtLayoutError> {
        let plan = HtRawComposedCoefficientDecodePlan::new(block, layouts, config)?;
        self.decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursor_refs_with_plan(
            plan,
            cursors.as_mut_refs(),
        )
    }

    /// Decode all temporary raw composed coefficient planes from one borrowed
    /// fresh cursor group into this parser-output bundle.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursor_refs_with_config(
        &mut self,
        block: HtBlockLayout,
        layouts: HtRawComposedStreamLayouts,
        cursors: HtRawComposedStreamBitCursorRefs<'_, '_, '_, '_>,
        config: HtRawComposedCoefficientDecodeConfig,
    ) -> Result<Option<()>, HtLayoutError> {
        let plan = HtRawComposedCoefficientDecodePlan::new(block, layouts, config)?;
        self.decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursor_refs_with_plan(
            plan, cursors,
        )
    }

    /// Decode all temporary raw composed coefficient planes from one borrowed
    /// fresh cursor group using one validated raw composed decode plan.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursor_refs_with_plan(
        &mut self,
        plan: HtRawComposedCoefficientDecodePlan,
        cursors: HtRawComposedStreamBitCursorRefs<'_, '_, '_, '_>,
    ) -> Result<Option<()>, HtLayoutError> {
        let request = HtRawComposedParserOutputCursorRequest::new(plan, cursors, self.reborrow())?;
        Ok(request.decode()?.map(|_| ()))
    }

    /// Decode all temporary raw composed coefficient planes from already
    /// prepared fresh bit cursors into this parser-output bundle.
    ///
    /// The cursors must be positioned at the start of partitions whose
    /// remaining bit counts exactly match the supplied layouts. That keeps
    /// this boundary all-or-nothing for malformed prepared cursors while
    /// letting future MEL/VLC/refinement parser drivers fill the same typed
    /// output planes without re-slicing bytes.
    #[allow(clippy::too_many_arguments)]
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursors_with_config(
        &mut self,
        block: HtBlockLayout,
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_cursors: &mut HtCleanupStreamBitCursors<'_>,
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_cursors: &mut HtCleanupStreamBitCursors<'_>,
        magnitude_sign_stream_layout: HtCleanupStreamLayout,
        magnitude_sign_cursors: &mut HtCleanupStreamBitCursors<'_>,
        config: HtRawComposedCoefficientDecodeConfig,
    ) -> Result<Option<()>, HtLayoutError> {
        let layouts = HtRawComposedStreamLayouts::new(
            cleanup_stream_layout,
            refinement_stream_layout,
            magnitude_sign_stream_layout,
        );
        let cursors = HtRawComposedStreamBitCursorRefs::new(
            cleanup_cursors,
            refinement_cursors,
            magnitude_sign_cursors,
        );

        self.decode_raw_cleanup_refinement_and_magnitude_sign_from_fresh_cursor_refs_with_config(
            block, layouts, cursors, config,
        )
    }
}

impl fmt::Display for HtLayoutError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidCodeBlock { width, height } => {
                write!(f, "invalid HTJ2K code-block dimensions {width}x{height}")
            }
            Self::BlockLayoutMismatch {
                expected_width,
                expected_height,
                actual_width,
                actual_height,
            } => write!(
                f,
                "HTJ2K raw composed decode plan block mismatch: expected {expected_width}x{expected_height}, got {actual_width}x{actual_height}"
            ),
            Self::SizeOverflow => f.write_str("HTJ2K block layout size overflowed usize"),
            Self::UnknownCleanupBackendOverride => {
                f.write_str("unknown EMUELLA_J2K_HT_BACKEND override")
            }
            Self::UnavailableCleanupBackendOverride => f.write_str(
                "requested HT cleanup backend is unavailable on this CPU or build target",
            ),
            Self::InvalidCleanupPassSegment { lcup, scup } => write!(
                f,
                "invalid HTJ2K cleanup pass segment lengths: Lcup={lcup}, Scup={scup}"
            ),
            Self::InvalidRefinementPassSegment { reason } => {
                write!(f, "invalid HTJ2K refinement pass segment: {reason}")
            }
            Self::InvalidCleanupBitplane {
                missing_most_significant_bitplanes,
            } => write!(
                f,
                "invalid HTJ2K cleanup bitplane from {missing_most_significant_bitplanes} missing most-significant bitplanes"
            ),
            Self::UnsupportedCodingPassCount { coding_passes } => write!(
                f,
                "HTJ2K cleanup-only decode does not support {coding_passes} coding passes"
            ),
            Self::BufferTooSmall { required, actual } => write!(
                f,
                "HTJ2K block buffer is too small: required {required}, got {actual}"
            ),
            Self::SymbolCountMismatch { required, actual } => write!(
                f,
                "HTJ2K cleanup symbol count mismatch: required {required}, got {actual}"
            ),
            Self::RefinementValueCountMismatch { required, actual } => write!(
                f,
                "HTJ2K refinement value count mismatch: required {required}, got {actual}"
            ),
            Self::MagnitudeSignValueCountMismatch { required, actual } => write!(
                f,
                "HTJ2K magnitude/sign value count mismatch: required {required}, got {actual}"
            ),
            Self::VlcCleanupOutputCountMismatch { required, actual } => write!(
                f,
                "HTJ2K VLC cleanup output count mismatch: required {required}, got {actual}"
            ),
            Self::InvalidVlcCleanupOutput { reason } => {
                write!(f, "invalid HTJ2K VLC cleanup output: {reason}")
            }
            Self::StreamOverrun {
                stream,
                consumed,
                available,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} consumed {consumed} bytes, but only {available} bytes are available"
            ),
            Self::StreamBitOverrun {
                stream,
                consumed_bits,
                available_bits,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} consumed {consumed_bits} bits, but only {available_bits} bits are available"
            ),
            Self::StreamBitReadUnavailable {
                stream,
                requested_bits,
                remaining_bits,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} could not read {requested_bits} required bits with {remaining_bits} bits remaining"
            ),
            Self::StreamUnalignedByteRead {
                stream,
                consumed_bits,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} required an aligned byte read after {consumed_bits} consumed bits"
            ),
            Self::StreamCursorNotAtStart {
                stream,
                consumed_bits,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} cursor was already advanced by {consumed_bits} bits"
            ),
            Self::StreamBitUnderconsumed {
                stream,
                consumed_bits,
                expected_bits,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} consumed {consumed_bits} bits, but {expected_bits} bits were declared"
            ),
            Self::SideInputUnderconsumed {
                remaining_quad_side_bits,
                remaining_odd_tail_u_values,
            } => write!(
                f,
                "HTJ2K VLC cleanup side inputs left {remaining_quad_side_bits} quad side-bit entries and {remaining_odd_tail_u_values} odd-tail u values unread"
            ),
            Self::SideInputMismatch => {
                f.write_str("HTJ2K VLC cleanup side-input request did not match parser outcome")
            }
            Self::SideInputTargetsCroppedCoefficient {
                quad_side_bit_index,
            } => write!(
                f,
                "HTJ2K VLC cleanup side-input entry {quad_side_bit_index} targets a cropped coefficient"
            ),
            Self::StreamStuffedByteInvalid {
                stream,
                byte,
                consumed_bits,
            } => write!(
                f,
                "HTJ2K cleanup stream {stream:?} found invalid stuffed byte 0x{byte:02x} after {consumed_bits} consumed bits"
            ),
        }
    }
}

#[cfg(feature = "std")]
impl std::error::Error for HtLayoutError {}

/// HT code-block dimensions accepted by the future block decoder.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtCodeBlockDimensions {
    width: u16,
    height: u16,
}

impl HtCodeBlockDimensions {
    /// JPEG 2000 code-blocks are limited to 4096 coefficients.
    pub const MAX_COEFFICIENTS: usize = 4096;

    /// Create validated HT code-block dimensions.
    pub fn new(width: u16, height: u16) -> Result<Self, HtLayoutError> {
        let dimensions = Self { width, height };
        let coefficients = dimensions.coefficient_count();
        if coefficients == 0 || coefficients > Self::MAX_COEFFICIENTS {
            return Err(HtLayoutError::InvalidCodeBlock { width, height });
        }
        Ok(dimensions)
    }

    /// Width in coefficients.
    pub fn width(self) -> u16 {
        self.width
    }

    /// Height in coefficients.
    pub fn height(self) -> u16 {
        self.height
    }

    /// Total coefficient count.
    pub fn coefficient_count(self) -> usize {
        usize::from(self.width) * usize::from(self.height)
    }
}

/// HT cleanup/refinement geometry derived from a code-block.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtBlockLayout {
    dimensions: HtCodeBlockDimensions,
    line_pairs: usize,
    quad_columns: usize,
    octet_columns: usize,
}

impl HtBlockLayout {
    /// Build the SIMD-ready HT line-pair, quad, and octet layout.
    pub fn new(dimensions: HtCodeBlockDimensions) -> Self {
        let height = usize::from(dimensions.height);
        let width = usize::from(dimensions.width);
        Self {
            dimensions,
            line_pairs: height.div_ceil(2),
            quad_columns: width.div_ceil(2),
            octet_columns: width.div_ceil(4),
        }
    }

    /// Source code-block dimensions.
    pub fn dimensions(self) -> HtCodeBlockDimensions {
        self.dimensions
    }

    /// Number of two-row HT line-pairs.
    pub fn line_pair_count(self) -> usize {
        self.line_pairs
    }

    /// Number of 2x2 quads per line-pair.
    pub fn quad_columns(self) -> usize {
        self.quad_columns
    }

    /// Number of four-column octets per line-pair.
    pub fn octet_columns(self) -> usize {
        self.octet_columns
    }

    /// Total HT quads in the code-block.
    pub fn quad_count(self) -> usize {
        self.line_pairs * self.quad_columns
    }

    /// Total HT octets in the code-block.
    pub fn octet_count(self) -> usize {
        self.line_pairs * self.octet_columns
    }

    /// Materialize a complete traversal-order VLC cleanup output plane into
    /// row-major signed coefficients using real HT cleanup reconstruction.
    ///
    /// The output plane must contain exactly one decoded cleanup output for
    /// every real coefficient in HT quad traversal order. Capacity, position
    /// order, cleanup bitplane support, and every coefficient reconstruction
    /// are checked before `output` is mutated.
    pub fn materialize_vlc_cleanup_coefficient_outputs(
        self,
        outputs: &[HtVlcCleanupCoefficientOutput],
        missing_most_significant_bitplanes: u8,
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        self.materialize_vlc_cleanup_coefficient_outputs_with_progress(
            outputs,
            missing_most_significant_bitplanes,
            output,
        )
        .map(|progress| progress.map(|_| ()))
    }

    /// Materialize a complete traversal-order VLC cleanup output plane into
    /// row-major signed coefficients and report the completed handoff counts.
    ///
    /// This is the progress-reporting companion to
    /// [`Self::materialize_vlc_cleanup_coefficient_outputs`]. It lets staged
    /// HT block decoders prove that the parsed VLC cleanup-output prefix and
    /// row-major coefficient plane covered the same real coefficient count.
    pub fn materialize_vlc_cleanup_coefficient_outputs_with_progress(
        self,
        outputs: &[HtVlcCleanupCoefficientOutput],
        missing_most_significant_bitplanes: u8,
        output: &mut [i32],
    ) -> Result<Option<HtVlcCleanupOutputMaterializationProgress>, HtLayoutError> {
        let required = self.dimensions().coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        if validate_vlc_cleanup_coefficient_output_plane(self, outputs)?.is_none() {
            return Ok(None);
        }
        let cleanup_bitplane =
            cleanup_bitplane_from_missing_msbs(missing_most_significant_bitplanes)?;
        for decoded in outputs {
            decoded.reconstruct_cleanup_coefficient(missing_most_significant_bitplanes)?;
        }

        for decoded in outputs {
            output[decoded.position.refinement_slot] =
                decoded.reconstruct_cleanup_coefficient(missing_most_significant_bitplanes)?;
        }
        Ok(Some(HtVlcCleanupOutputMaterializationProgress {
            block: self,
            output_count: outputs.len(),
            coefficient_count: required,
            missing_most_significant_bitplanes,
            cleanup_bitplane,
        }))
    }

    /// Side-input item counts needed by a complete block-level VLC cleanup
    /// traversal.
    pub fn vlc_cleanup_side_input_counts(self) -> HtVlcLinePairCleanupSideInputCounts {
        HtVlcLinePairCleanupSideInputCounts {
            quad_side_bits: self.quad_count(),
            odd_tail_u_values: if self.quad_columns.is_multiple_of(2) {
                0
            } else {
                self.line_pairs
            },
        }
    }

    /// Row-major coefficient slot used by per-coefficient refinement storage.
    pub fn coefficient_index(self, x: usize, y: usize) -> Option<usize> {
        if x >= usize::from(self.dimensions.width) || y >= usize::from(self.dimensions.height) {
            return None;
        }
        Some(y * usize::from(self.dimensions.width) + x)
    }

    /// Packed quad index for one line-pair and quad column.
    pub fn quad_index(self, line_pair: usize, quad_column: usize) -> Option<usize> {
        if line_pair >= self.line_pairs || quad_column >= self.quad_columns {
            return None;
        }
        Some(line_pair * self.quad_columns + quad_column)
    }

    /// Packed octet index for one line-pair and octet column.
    pub fn octet_index(self, line_pair: usize, octet_column: usize) -> Option<usize> {
        if line_pair >= self.line_pairs || octet_column >= self.octet_columns {
            return None;
        }
        Some(line_pair * self.octet_columns + octet_column)
    }

    /// Locate the packed HT layout indices for one coefficient coordinate.
    pub fn coefficient_position(self, x: usize, y: usize) -> Option<HtCoefficientPosition> {
        let refinement_slot = self.coefficient_index(x, y)?;
        let line_pair = y / 2;
        let quad_column = x / 2;
        let octet_column = x / 4;
        Some(HtCoefficientPosition {
            x,
            y,
            refinement_slot,
            line_pair,
            quad_column,
            quad_index: self.quad_index(line_pair, quad_column)?,
            octet_column,
            octet_index: self.octet_index(line_pair, octet_column)?,
        })
    }

    /// Length of packed per-quad cleanup context storage.
    pub fn cleanup_context_words(self) -> usize {
        self.quad_count()
    }

    /// Length of packed per-quad greater-than-one side storage.
    pub fn gt1_words(self) -> usize {
        self.quad_count()
    }

    /// Number of coefficient refinement slots covered by the block.
    pub fn refinement_slots(self) -> usize {
        self.dimensions.coefficient_count()
    }

    /// Number of raw magnitude/sign side-buffer slots covered by the block.
    pub fn magnitude_sign_slots(self) -> usize {
        self.dimensions.coefficient_count()
    }

    /// Length of packed per-octet refinement bit storage.
    pub fn refinement_bit_words(self) -> usize {
        self.octet_count()
    }

    /// Return the coefficient bounds for one two-row line-pair.
    pub fn line_pair(self, index: usize) -> Option<HtLinePair> {
        if index >= self.line_pairs {
            return None;
        }
        let y = index * 2;
        Some(HtLinePair {
            y,
            height: (usize::from(self.dimensions.height) - y).min(2),
        })
    }

    /// Return the packed line-pair group for one two-row unit.
    pub fn line_pair_group(self, index: usize) -> Option<HtLinePairGroup> {
        if index >= self.line_pairs {
            return None;
        }
        let bounds = self.line_pair(index)?;
        let width = usize::from(self.dimensions.width);
        Some(HtLinePairGroup {
            line_pair: index,
            bounds,
            first_quad_index: index * self.quad_columns,
            quad_count: self.quad_columns,
            first_octet_index: index * self.octet_columns,
            octet_count: self.octet_columns,
            first_refinement_slot: bounds.y * width,
            refinement_count: bounds.height * width,
        })
    }

    /// Iterate packed two-row line-pairs in HT layout order.
    pub fn line_pair_groups(self) -> HtLinePairGroupIter {
        HtLinePairGroupIter {
            layout: self,
            next: 0,
        }
    }

    /// Return the coefficient bounds for one 2x2 quad.
    pub fn quad(self, line_pair: usize, quad_column: usize) -> Option<HtQuad> {
        let line_pair = self.line_pair(line_pair)?;
        if quad_column >= self.quad_columns {
            return None;
        }
        let x = quad_column * 2;
        Some(HtQuad {
            x,
            y: line_pair.y,
            width: (usize::from(self.dimensions.width) - x).min(2),
            height: line_pair.height,
        })
    }

    /// Return the coefficient bounds for one four-column HT octet.
    pub fn octet(self, line_pair: usize, octet_column: usize) -> Option<HtOctet> {
        let line_pair = self.line_pair(line_pair)?;
        if octet_column >= self.octet_columns {
            return None;
        }
        let x = octet_column * 4;
        Some(HtOctet {
            x,
            y: line_pair.y,
            width: (usize::from(self.dimensions.width) - x).min(4),
            height: line_pair.height,
        })
    }

    /// Return packed coefficient positions for one 2x2 quad.
    pub fn quad_positions(self, line_pair: usize, quad_column: usize) -> Option<HtQuadPositions> {
        let quad = self.quad(line_pair, quad_column)?;
        Some(HtQuadPositions {
            coefficients: [
                self.coefficient_position(quad.x, quad.y),
                self.coefficient_position(quad.x, quad.y + 1),
                self.coefficient_position(quad.x + 1, quad.y),
                self.coefficient_position(quad.x + 1, quad.y + 1),
            ],
        })
    }

    /// Return packed coefficient positions for one two-row, four-column octet.
    pub fn octet_positions(
        self,
        line_pair: usize,
        octet_column: usize,
    ) -> Option<HtOctetPositions> {
        let octet = self.octet(line_pair, octet_column)?;
        Some(HtOctetPositions {
            coefficients: [
                self.coefficient_position(octet.x, octet.y),
                self.coefficient_position(octet.x + 1, octet.y),
                self.coefficient_position(octet.x + 2, octet.y),
                self.coefficient_position(octet.x + 3, octet.y),
                self.coefficient_position(octet.x, octet.y + 1),
                self.coefficient_position(octet.x + 1, octet.y + 1),
                self.coefficient_position(octet.x + 2, octet.y + 1),
                self.coefficient_position(octet.x + 3, octet.y + 1),
            ],
        })
    }

    /// Iterate packed 2x2 quad groups in HT layout order.
    pub fn quad_groups(self) -> HtQuadGroupIter {
        HtQuadGroupIter {
            layout: self,
            next: 0,
            end: self.quad_count(),
        }
    }

    /// Iterate packed 2x2 quad groups for one line-pair only.
    pub fn quad_groups_in_line_pair(self, line_pair: usize) -> Option<HtQuadGroupIter> {
        if line_pair >= self.line_pairs {
            return None;
        }
        let start = line_pair * self.quad_columns;
        Some(HtQuadGroupIter {
            layout: self,
            next: start,
            end: start + self.quad_columns,
        })
    }

    /// Iterate packed two-row, four-column octet groups in HT layout order.
    pub fn octet_groups(self) -> HtOctetGroupIter {
        HtOctetGroupIter {
            layout: self,
            next: 0,
            end: self.octet_count(),
        }
    }

    /// Iterate packed two-row, four-column octet groups for one line-pair only.
    pub fn octet_groups_in_line_pair(self, line_pair: usize) -> Option<HtOctetGroupIter> {
        if line_pair >= self.line_pairs {
            return None;
        }
        let start = line_pair * self.octet_columns;
        Some(HtOctetGroupIter {
            layout: self,
            next: start,
            end: start + self.octet_columns,
        })
    }
}

/// One HT line-pair, normally two coefficient rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtLinePair {
    pub y: usize,
    pub height: usize,
}

/// One packed two-row line-pair group in HT traversal order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtLinePairGroup {
    pub line_pair: usize,
    pub bounds: HtLinePair,
    pub first_quad_index: usize,
    pub quad_count: usize,
    pub first_octet_index: usize,
    pub octet_count: usize,
    pub first_refinement_slot: usize,
    pub refinement_count: usize,
}

impl HtLinePairGroup {
    /// Packed quad-word range covered by this line-pair.
    pub fn quad_range(self) -> Option<Range<usize>> {
        let end = self.first_quad_index.checked_add(self.quad_count)?;
        Some(self.first_quad_index..end)
    }

    /// Packed octet-word range covered by this line-pair.
    pub fn octet_range(self) -> Option<Range<usize>> {
        let end = self.first_octet_index.checked_add(self.octet_count)?;
        Some(self.first_octet_index..end)
    }

    /// Row-major per-coefficient refinement-slot range covered by this
    /// line-pair.
    pub fn refinement_range(self) -> Option<Range<usize>> {
        let end = self
            .first_refinement_slot
            .checked_add(self.refinement_count)?;
        Some(self.first_refinement_slot..end)
    }

    /// Packed quad index local to this line-pair for one coefficient.
    pub fn coefficient_quad_local_index(self, position: HtCoefficientPosition) -> Option<usize> {
        if position.line_pair != self.line_pair {
            return None;
        }
        let index = position.quad_index.checked_sub(self.first_quad_index)?;
        (index < self.quad_count).then_some(index)
    }

    /// Packed octet index local to this line-pair for one coefficient.
    pub fn coefficient_octet_local_index(self, position: HtCoefficientPosition) -> Option<usize> {
        if position.line_pair != self.line_pair {
            return None;
        }
        let index = position.octet_index.checked_sub(self.first_octet_index)?;
        (index < self.octet_count).then_some(index)
    }

    /// Row-major refinement slot local to this line-pair for one coefficient.
    pub fn coefficient_refinement_local_index(
        self,
        position: HtCoefficientPosition,
    ) -> Option<usize> {
        if position.line_pair != self.line_pair {
            return None;
        }
        let index = position
            .refinement_slot
            .checked_sub(self.first_refinement_slot)?;
        (index < self.refinement_count).then_some(index)
    }
}

/// Iterator over packed HT line-pair groups.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtLinePairGroupIter {
    layout: HtBlockLayout,
    next: usize,
}

impl Iterator for HtLinePairGroupIter {
    type Item = HtLinePairGroup;

    fn next(&mut self) -> Option<Self::Item> {
        if self.next >= self.layout.line_pair_count() {
            return None;
        }
        let line_pair = self.next;
        self.next += 1;
        self.layout.line_pair_group(line_pair)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.layout.line_pair_count() - self.next;
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for HtLinePairGroupIter {}

/// One HT 2x2 quad, cropped on right/bottom code-block edges.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtQuad {
    pub x: usize,
    pub y: usize,
    pub width: usize,
    pub height: usize,
}

/// One HT octet, consisting of up to two adjacent quads in one line-pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtOctet {
    pub x: usize,
    pub y: usize,
    pub width: usize,
    pub height: usize,
}

/// One packed 2x2 quad group in HT traversal order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtQuadGroup {
    pub line_pair: usize,
    pub quad_column: usize,
    pub quad_index: usize,
    pub positions: HtQuadPositions,
}

impl HtQuadGroup {
    /// Index of this quad inside its containing line-pair.
    pub fn line_pair_local_index(self, line_pair: HtLinePairGroup) -> Option<usize> {
        if self.line_pair != line_pair.line_pair {
            return None;
        }
        let index = self.quad_index.checked_sub(line_pair.first_quad_index)?;
        (index < line_pair.quad_count).then_some(index)
    }

    /// Number of real coefficients in this possibly cropped quad.
    pub fn present_count(self) -> usize {
        self.positions.present_count()
    }

    /// Packed quad-word mask for real coefficients in this possibly cropped
    /// quad.
    pub fn present_mask(self) -> u16 {
        self.positions.present_mask()
    }

    /// Iterate only real coefficient positions in packed quad-slot order.
    pub fn present_positions(self) -> HtQuadPresentPositionIter {
        self.positions.present_positions()
    }
}

/// Iterator over packed HT 2x2 quad groups.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtQuadGroupIter {
    layout: HtBlockLayout,
    next: usize,
    end: usize,
}

impl Iterator for HtQuadGroupIter {
    type Item = HtQuadGroup;

    fn next(&mut self) -> Option<Self::Item> {
        if self.next >= self.end {
            return None;
        }
        let index = self.next;
        self.next += 1;
        let line_pair = index / self.layout.quad_columns;
        let quad_column = index % self.layout.quad_columns;
        Some(HtQuadGroup {
            line_pair,
            quad_column,
            quad_index: index,
            positions: self.layout.quad_positions(line_pair, quad_column)?,
        })
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.end - self.next;
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for HtQuadGroupIter {}

/// One adjacent VLC cleanup quad pair in line-pair traversal order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtVlcQuadPairGroup {
    pub first: HtQuadGroup,
    pub second: Option<HtQuadGroup>,
}

impl HtVlcQuadPairGroup {
    /// Traversal-order side-input entries required by this VLC cleanup group.
    pub const fn side_input_counts(self) -> HtVlcLinePairCleanupSideInputCounts {
        if self.second.is_some() {
            HtVlcLinePairCleanupSideInputCounts {
                quad_side_bits: 2,
                odd_tail_u_values: 0,
            }
        } else {
            HtVlcLinePairCleanupSideInputCounts {
                quad_side_bits: 1,
                odd_tail_u_values: 1,
            }
        }
    }
}

/// Iterator over adjacent VLC cleanup quad pairs for one HT line-pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtVlcQuadPairGroupIter {
    groups: HtQuadGroupIter,
}

impl Iterator for HtVlcQuadPairGroupIter {
    type Item = HtVlcQuadPairGroup;

    fn next(&mut self) -> Option<Self::Item> {
        let first = self.groups.next()?;
        let second = self.groups.next();
        Some(HtVlcQuadPairGroup { first, second })
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.groups.len().div_ceil(2);
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for HtVlcQuadPairGroupIter {}

/// One packed two-row, four-column octet group in HT traversal order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtOctetGroup {
    pub line_pair: usize,
    pub octet_column: usize,
    pub octet_index: usize,
    pub positions: HtOctetPositions,
}

impl HtOctetGroup {
    /// Index of this octet inside its containing line-pair.
    pub fn line_pair_local_index(self, line_pair: HtLinePairGroup) -> Option<usize> {
        if self.line_pair != line_pair.line_pair {
            return None;
        }
        let index = self.octet_index.checked_sub(line_pair.first_octet_index)?;
        (index < line_pair.octet_count).then_some(index)
    }

    /// Number of real coefficients in this possibly cropped octet.
    pub fn present_count(self) -> usize {
        self.positions.present_count()
    }

    /// Packed octet-word mask for real coefficients in this possibly cropped
    /// octet.
    pub fn present_mask(self) -> u16 {
        self.positions.present_mask()
    }

    /// Iterate only real coefficient positions in packed octet-slot order.
    pub fn present_positions(self) -> HtOctetPresentPositionIter {
        self.positions.present_positions()
    }
}

/// Iterator over packed HT two-row, four-column octet groups.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtOctetGroupIter {
    layout: HtBlockLayout,
    next: usize,
    end: usize,
}

impl Iterator for HtOctetGroupIter {
    type Item = HtOctetGroup;

    fn next(&mut self) -> Option<Self::Item> {
        if self.next >= self.end {
            return None;
        }
        let index = self.next;
        self.next += 1;
        let line_pair = index / self.layout.octet_columns;
        let octet_column = index % self.layout.octet_columns;
        Some(HtOctetGroup {
            line_pair,
            octet_column,
            octet_index: index,
            positions: self.layout.octet_positions(line_pair, octet_column)?,
        })
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.end - self.next;
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for HtOctetGroupIter {}

/// Coefficient positions in one 2x2 HT quad, in packed quad-slot order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtQuadPositions {
    pub coefficients: [Option<HtCoefficientPosition>; 4],
}

impl HtQuadPositions {
    /// Packed quad index shared by every real coefficient in this group.
    pub fn quad_index(self) -> Option<usize> {
        self.coefficients
            .iter()
            .flatten()
            .next()
            .map(|position| position.quad_index)
    }

    /// Number of real coefficients in this possibly cropped quad.
    pub fn present_count(self) -> usize {
        self.coefficients
            .iter()
            .filter(|position| position.is_some())
            .count()
    }

    /// Packed quad-word mask for real coefficients in this possibly cropped
    /// quad.
    pub fn present_mask(self) -> u16 {
        self.coefficients
            .iter()
            .flatten()
            .fold(0_u16, |mask, position| mask | position.quad_mask())
    }

    /// Iterate only real coefficient positions in packed quad-slot order.
    pub fn present_positions(self) -> HtQuadPresentPositionIter {
        HtQuadPresentPositionIter {
            coefficients: self.coefficients,
            next: 0,
            remaining: self.present_count(),
        }
    }
}

/// Coefficient positions in one two-row, four-column HT octet, in packed order.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtOctetPositions {
    pub coefficients: [Option<HtCoefficientPosition>; 8],
}

impl HtOctetPositions {
    /// Packed octet index shared by every real coefficient in this group.
    pub fn octet_index(self) -> Option<usize> {
        self.coefficients
            .iter()
            .flatten()
            .next()
            .map(|position| position.octet_index)
    }

    /// Number of real coefficients in this possibly cropped octet.
    pub fn present_count(self) -> usize {
        self.coefficients
            .iter()
            .filter(|position| position.is_some())
            .count()
    }

    /// Packed octet-word mask for real coefficients in this possibly cropped
    /// octet.
    pub fn present_mask(self) -> u16 {
        self.coefficients
            .iter()
            .flatten()
            .fold(0_u16, |mask, position| mask | position.octet_mask())
    }

    /// Iterate only real coefficient positions in packed octet-slot order.
    pub fn present_positions(self) -> HtOctetPresentPositionIter {
        HtOctetPresentPositionIter {
            coefficients: self.coefficients,
            next: 0,
            remaining: self.present_count(),
        }
    }
}

/// Iterator over real positions in one packed HT 2x2 quad.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtQuadPresentPositionIter {
    coefficients: [Option<HtCoefficientPosition>; 4],
    next: usize,
    remaining: usize,
}

impl Iterator for HtQuadPresentPositionIter {
    type Item = HtCoefficientPosition;

    fn next(&mut self) -> Option<Self::Item> {
        while self.next < self.coefficients.len() {
            let position = self.coefficients[self.next];
            self.next += 1;
            if let Some(position) = position {
                self.remaining -= 1;
                return Some(position);
            }
        }
        None
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl ExactSizeIterator for HtQuadPresentPositionIter {}

