    /// Decode raw cleanup symbols and raw refinement values through
    /// caller-owned coefficient-local buffers before materializing row-major
    /// signed coefficient output.
    ///
    /// This staged block boundary preflights both raw stream layouts and byte
    /// buffers before mutating either caller-owned parse buffer or side-buffer
    /// scratch. It then parses cleanup symbols and refinement values without
    /// scratch, prepares cleared side-buffer scratch once, applies both
    /// complete coefficient-local planes, and materializes coefficients from
    /// the resulting side-buffer state.
    pub fn decode_raw_cleanup_and_refinement_coefficients_with_buffers_checked(
        self,
        scratch: &mut [u16],
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_stream_bytes: &[u8],
        cleanup_stream: HtCleanupStreamKind,
        magnitude_sign_bits: u8,
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_stream_bytes: &[u8],
        refinement_stream: HtCleanupStreamKind,
        refinement_value_bits: u8,
        symbols: &mut [HtCleanupCoefficientSymbol],
        refinement_values: &mut [HtCoefficientRefinementValue],
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let cleanup_config = HtRawCleanupDecodeConfig::new(cleanup_stream, magnitude_sign_bits)?;
        let refinement_config =
            HtRawRefinementValueDecodeConfig::new(refinement_stream, refinement_value_bits)?;
        self.decode_raw_cleanup_and_refinement_coefficients_with_buffers_config(
            scratch,
            cleanup_stream_layout,
            cleanup_stream_bytes,
            cleanup_config,
            refinement_stream_layout,
            refinement_stream_bytes,
            refinement_config,
            symbols,
            refinement_values,
            output,
        )
    }

    /// Decode raw cleanup symbols and raw refinement values through
    /// caller-owned coefficient-local buffers using validated raw configs.
    pub fn decode_raw_cleanup_and_refinement_coefficients_with_buffers_config(
        self,
        scratch: &mut [u16],
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_stream_bytes: &[u8],
        cleanup_config: HtRawCleanupDecodeConfig,
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_stream_bytes: &[u8],
        refinement_config: HtRawRefinementValueDecodeConfig,
        symbols: &mut [HtCleanupCoefficientSymbol],
        refinement_values: &mut [HtCoefficientRefinementValue],
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let required = self.block.dimensions().coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        if symbols.len() != required {
            return Err(HtLayoutError::SymbolCountMismatch {
                required,
                actual: symbols.len(),
            });
        }
        if refinement_values.len() != required {
            return Err(HtLayoutError::RefinementValueCountMismatch {
                required,
                actual: refinement_values.len(),
            });
        }
        if scratch.len() < self.total_words {
            return Err(HtLayoutError::BufferTooSmall {
                required: self.total_words,
                actual: scratch.len(),
            });
        }
        cleanup_config.check_declared_raw_side_buffer_bits(self.block, cleanup_stream_layout)?;
        refinement_config
            .check_declared_raw_refinement_value_bits(self.block, refinement_stream_layout)?;
        let _ = cleanup_stream_layout.split_streams(cleanup_stream_bytes)?;
        let _ = refinement_stream_layout.split_streams(refinement_stream_bytes)?;

        if HtRawCleanupSymbolDecodeRequest::new(
            self.block,
            cleanup_stream_layout,
            cleanup_config,
            cleanup_stream_bytes,
            symbols,
        )?
        .decode()?
        .is_none()
        {
            return Ok(None);
        }
        if HtRawRefinementValueDecodeRequest::new(
            self.block,
            refinement_stream_layout,
            refinement_config,
            refinement_stream_bytes,
            refinement_values,
        )?
        .decode()?
        .is_none()
        {
            return Ok(None);
        }

        let streams = cleanup_stream_layout.split_streams(cleanup_stream_bytes)?;
        let mut views = HtCleanupDecodeViews {
            scratch: self.prepare_scratch(scratch)?,
            streams: streams.bit_cursors(),
        };
        if views
            .apply_cleanup_coefficient_symbols(self.block, symbols)?
            .is_none()
        {
            return Ok(None);
        }
        if views
            .apply_coefficient_refinement_values(self.block, refinement_values)?
            .is_none()
        {
            return Ok(None);
        }
        views.materialize_raw_cleanup_coefficients(
            self.block,
            output,
            cleanup_config.magnitude_sign_bits(),
        )
    }

    /// Decode raw cleanup symbols, raw refinement values, and raw
    /// magnitude/sign values through caller-owned coefficient-local buffers
    /// before materializing row-major signed coefficient output.
    ///
    /// This staged block boundary keeps all parser outputs scratch-free until
    /// every declared stream layout and byte buffer has been validated. It then
    /// prepares cleared side-buffer scratch once, applies all three complete
    /// coefficient-local planes, and materializes coefficients from the final
    /// magnitude/sign state.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_coefficients_with_buffers_checked(
        self,
        scratch: &mut [u16],
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_stream_bytes: &[u8],
        cleanup_stream: HtCleanupStreamKind,
        cleanup_magnitude_sign_bits: u8,
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_stream_bytes: &[u8],
        refinement_stream: HtCleanupStreamKind,
        refinement_value_bits: u8,
        magnitude_sign_stream_layout: HtCleanupStreamLayout,
        magnitude_sign_stream_bytes: &[u8],
        magnitude_sign_stream: HtCleanupStreamKind,
        magnitude_sign_bits: u8,
        symbols: &mut [HtCleanupCoefficientSymbol],
        refinement_values: &mut [HtCoefficientRefinementValue],
        magnitude_sign_values: &mut [HtCoefficientMagnitudeSignValue],
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let config = HtRawComposedCoefficientDecodeConfig::new(
            cleanup_stream,
            cleanup_magnitude_sign_bits,
            refinement_stream,
            refinement_value_bits,
            magnitude_sign_stream,
            magnitude_sign_bits,
        )?;
        self
            .decode_raw_cleanup_refinement_and_magnitude_sign_coefficients_with_buffers_composed_config(
            scratch,
            cleanup_stream_layout,
            cleanup_stream_bytes,
            refinement_stream_layout,
            refinement_stream_bytes,
            magnitude_sign_stream_layout,
            magnitude_sign_stream_bytes,
            config,
            symbols,
            refinement_values,
            magnitude_sign_values,
            output,
        )
    }

