/// scratch-layout block identity, output capacity, and stream byte capacity
/// before fresh cursors are split or reusable parser-output storage is grown.
#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtReusableRawComposedCoefficientDecodeRequest<'a> {
    scratch_layout: HtBlockScratchLayout,
    plan: HtRawComposedCoefficientDecodePlan,
    bytes: HtRawComposedStreamBytes<'a>,
    required: usize,
}

#[cfg(feature = "std")]
impl<'a> HtReusableRawComposedCoefficientDecodeRequest<'a> {
    /// Validate and bundle one reusable byte-backed raw composed decode request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'a>,
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        let required = plan.check_coefficient_output_capacity(scratch_layout, output)?;
        plan.check_available_raw_composed_stream_bytes(bytes)?;
        Ok(Self {
            scratch_layout,
            plan,
            bytes,
            required,
        })
    }

    /// Scratch layout covered by this request.
    pub fn scratch_layout(self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Raw composed decode plan covered by this request.
    pub fn plan(self) -> HtRawComposedCoefficientDecodePlan {
        self.plan
    }

    /// Stream bytes covered by this request.
    pub fn bytes(self) -> HtRawComposedStreamBytes<'a> {
        self.bytes
    }

    /// Active reusable parser-output prefix length covered by this request.
    pub fn required(self) -> usize {
        self.required
    }

    /// Split the checked byte bundle into fresh cursors for reusable decode.
    pub fn into_fresh_cursor_parts(
        self,
    ) -> Result<
        (
            HtBlockScratchLayout,
            HtRawComposedCoefficientDecodePlan,
            HtRawComposedStreamBitCursors<'a>,
            usize,
        ),
        HtLayoutError,
    > {
        let cursors = self.bytes.split_fresh_bit_cursors(self.plan.layouts())?;
        Ok((self.scratch_layout, self.plan, cursors, self.required))
    }
}

