/// Fully checked request for filling reusable raw composed parser-output
/// plane prefixes from stream bytes.
///
/// This is the byte-backed counterpart to
/// [`HtReusableRawComposedPlaneBufferCoefficientDecodeCursorRequest`]. It
/// validates scratch-layout block identity, coefficient-output capacity,
/// declared stream byte capacity, and the active reusable parser-output plane
/// prefixes before splitting fresh cursors or mutating parser-output planes.
#[cfg(feature = "std")]
pub struct HtReusableRawComposedPlaneBufferCoefficientDecodeRequest<'bytes, 'buffers> {
    scratch_layout: HtBlockScratchLayout,
    plan: HtRawComposedCoefficientDecodePlan,
    bytes: HtRawComposedStreamBytes<'bytes>,
    buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
    required: usize,
}

#[cfg(feature = "std")]
impl<'bytes, 'buffers> HtReusableRawComposedPlaneBufferCoefficientDecodeRequest<'bytes, 'buffers> {
    /// Validate and bundle one reusable byte-backed raw composed plane-buffer
    /// decode request.
    pub fn new(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
        output: &[i32],
    ) -> Result<Self, HtLayoutError> {
        let required = Self::preflight(scratch_layout, plan, bytes, output)?;
        Self::from_preflighted(scratch_layout, plan, bytes, buffers, required)
    }

    fn preflight(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        output: &[i32],
    ) -> Result<usize, HtLayoutError> {
        let required = plan.check_coefficient_output_capacity(scratch_layout, output)?;
        plan.check_available_raw_composed_stream_bytes(bytes)?;
        Ok(required)
    }

    fn from_preflighted(
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'bytes>,
        buffers: HtParsedCoefficientPlaneBuffers<'buffers>,
        required: usize,
    ) -> Result<Self, HtLayoutError> {
        plan.check_parsed_coefficient_plane_buffers(&buffers)?;
        Ok(Self {
            scratch_layout,
            plan,
            bytes,
            buffers,
            required,
        })
    }

    /// Scratch layout covered by this reusable parser-output handoff.
    pub fn scratch_layout(&self) -> HtBlockScratchLayout {
        self.scratch_layout
    }

    /// Raw composed decode plan covered by this reusable parser-output handoff.
    pub fn plan(&self) -> HtRawComposedCoefficientDecodePlan {
        self.plan
    }

    /// Stream bytes covered by this reusable parser-output handoff.
    pub fn bytes(&self) -> HtRawComposedStreamBytes<'bytes> {
        self.bytes
    }

    /// Active reusable parser-output prefix length covered by this request.
    pub fn required(&self) -> usize {
        self.required
    }

    /// Fill the checked reusable parser-output plane prefixes.
    pub fn decode(
        self,
    ) -> Result<
        Option<(
            HtBlockScratchLayout,
            HtRawComposedCoefficientDecodePlan,
            usize,
        )>,
        HtLayoutError,
    > {
        let valid = HtRawComposedParserOutputRequest::new(self.plan, self.bytes, self.buffers)?
            .decode()?
            .is_some();

        if valid {
            Ok(Some((self.scratch_layout, self.plan, self.required)))
        } else {
            Ok(None)
        }
    }
}

