    fn decode_raw_segment_parser_output_prefixes_with_reusable_buffers_prechecked<'a>(
        &'a mut self,
        request: HtCodeBlockDecodeRequest<'_>,
        scratch_layout: HtBlockScratchLayout,
        raw_segment_parser_output_config: HtRawSegmentParserOutputDecodeConfig,
        segment_cursors: &mut HtCleanupPassSegmentBitCursors<'_>,
        required: usize,
    ) -> Result<Option<HtRawSegmentParserOutputDecodeOutcome<'a>>, HtLayoutError> {
        let block = scratch_layout.block();
        self.ensure_layout(scratch_layout);
        self.ensure_vlc_cleanup_side_input_layout(scratch_layout);
        self.ensure_refinement_value_layout(scratch_layout);
        self.ensure_magnitude_sign_value_layout(scratch_layout);

        let side_input_counts = block.vlc_cleanup_side_input_counts();
        let mut side_input_buffers = HtVlcBlockCleanupSideInputBuffers::new(
            &mut self.vlc_quad_side_bits[..side_input_counts.quad_side_bits],
            &mut self.vlc_odd_tail_u_values[..side_input_counts.odd_tail_u_values],
        );

        let Some(side_input_counts) = segment_cursors
            .decode_raw_parser_outputs_prechecked_with_config(
                block,
                raw_segment_parser_output_config,
                &mut side_input_buffers,
                &mut self.refinement_values[..required],
                &mut self.magnitude_sign_values[..required],
            )?
        else {
            return Ok(None);
        };
        let prefixes = self.raw_segment_parser_output_prefixes(scratch_layout)?;

        Ok(Some(HtRawSegmentParserOutputDecodeOutcome::new(
            scratch_layout,
            request.missing_most_significant_bitplanes(),
            request.sample_precision_bits(),
            side_input_counts,
            prefixes,
        )))
    }

    /// Decode temporary raw parser-output prefixes from a preflighted
    /// code-block cleanup-pass segment request, decode real VLC cleanup
    /// symbols from those prefixes, then materialize row-major coefficients
    /// through this buffer's reusable storage.
    ///
    /// This is the staged real-segment bridge from packet-level parser-output
    /// filling into coefficient materialization. The temporary raw
    /// refinement/MagSgn parser-output layout remains replaceable by real Part
    /// 15 syntax, while cleanup symbols already come from the real segment
    /// VLC/MEL traversal.
    pub fn try_decode_preflighted_code_block_cleanup_raw_segment_parser_outputs_with_reusable_state_and_materialize(
        &mut self,
        reusable_request: HtReusableCodeBlockCleanupRawSegmentParserOutputDecodeRequest<'_>,
        raw_magnitude_sign_bits: u8,
        output: &mut [i32],
    ) -> Result<Option<HtVlcBlockCleanupSegmentProgress>, HtLayoutError> {
        Ok(self
            .try_decode_preflighted_code_block_cleanup_raw_segment_parser_outputs_with_reusable_state_and_materialize_with_parser_progress_internal(
                reusable_request,
                raw_magnitude_sign_bits,
                output,
            )?
            .map(|(segment, _parser_side_input_counts)| segment))
    }

    fn try_decode_preflighted_code_block_cleanup_raw_segment_parser_outputs_with_reusable_state_and_materialize_with_parser_progress_internal(
        &mut self,
        reusable_request: HtReusableCodeBlockCleanupRawSegmentParserOutputDecodeRequest<'_>,
        raw_magnitude_sign_bits: u8,
        output: &mut [i32],
    ) -> Result<
        Option<(
            HtVlcBlockCleanupSegmentProgress,
            HtVlcLinePairCleanupSideInputCounts,
        )>,
        HtLayoutError,
    > {
        let request = reusable_request.request();
        let scratch_layout = reusable_request.scratch_layout();
        let block = scratch_layout.block();
        let required = reusable_request.required();
        let materialization_plan =
            HtReusableVlcCleanupRawParserOutputMaterializationRequest::new_for_code_block_request(
                reusable_request,
                raw_magnitude_sign_bits,
                output,
            )?;

        let materialization_request = {
            let Some(outcome) = self
                .decode_preflighted_code_block_cleanup_raw_segment_parser_output_prefixes_with_reusable_buffers_config(
                    reusable_request,
                )?
            else {
                return Ok(None);
            };
            HtRawSegmentParserOutputMaterializationRequest::new(outcome, output)?
        };
        let mut segment_cursors = request.cleanup_pass_segment_bit_cursors()?;

        self.ensure_layout(scratch_layout);
        self.ensure_symbol_layout(scratch_layout);
        let required_context_states = reset_reusable_vlc_cleanup_progression_state(
            &mut self.vlc_context_states,
            &mut self.vlc_mel_state,
            scratch_layout,
        );

        let side_input_counts = block.vlc_cleanup_side_input_counts();
        let side_inputs = HtVlcBlockCleanupSideInputs::new(
            block,
            &self.vlc_quad_side_bits[..side_input_counts.quad_side_bits],
            &self.vlc_odd_tail_u_values[..side_input_counts.odd_tail_u_values],
        )?;
        let prefixes = HtRawSegmentParserOutputPrefixes::new(
            block,
            side_inputs,
            &self.refinement_values[..required],
            &self.magnitude_sign_values[..required],
        )?;
        let materialization_request =
            materialization_plan.check_request(materialization_request)?;
        let inputs =
            materialization_plan.check_inputs(materialization_request.with_prefixes(prefixes)?)?;
        let parser_side_input_counts = inputs.side_input_counts();

        let Some(segment) = scratch_layout
            .try_decode_vlc_cleanup_segment_side_inputs_to_raw_parser_output_inputs_and_materialize(
                &mut self.words,
                &mut segment_cursors,
                &mut self.vlc_context_states[..required_context_states],
                &mut self.vlc_mel_state,
                inputs,
                &mut self.symbols[..required],
                materialization_plan.raw_magnitude_sign_bits(),
                output,
            )?
        else {
            return Ok(None);
        };
        Ok(Some((segment, parser_side_input_counts)))
    }

    /// Decode temporary raw parser-output prefixes from a preflighted
    /// code-block cleanup-pass segment request, materialize coefficients, and
    /// preserve the parser-produced side-input counts.
    pub fn try_decode_preflighted_code_block_cleanup_raw_segment_parser_outputs_with_reusable_state_outputs_and_parser_progress(
        &mut self,
        reusable_request: HtReusableCodeBlockCleanupRawSegmentParserOutputDecodeRequest<'_>,
        raw_magnitude_sign_bits: u8,
        output: &mut [i32],
    ) -> Result<Option<HtPart15VlcCleanupSegmentProgress>, HtLayoutError> {
        let Some((segment, parser_side_input_counts)) = self
            .try_decode_preflighted_code_block_cleanup_raw_segment_parser_outputs_with_reusable_state_and_materialize_with_parser_progress_internal(
                reusable_request,
                raw_magnitude_sign_bits,
                output,
            )?
        else {
            return Ok(None);
        };
        Ok(Some(HtPart15VlcCleanupSegmentProgress::new(
            parser_side_input_counts,
            segment,
        )?))
    }

    /// Decode a parsed HT code-block request through this reusable scratch
    /// allocation into caller-owned coefficient output.
    pub fn decode_code_block_request_into<'out>(
        &mut self,
        request: HtCodeBlockDecodeRequest<'_>,
        output: &'out mut [i32],
    ) -> Result<HtCodeBlockDecodeOutcome<'out>, HtLayoutError> {
        Ok(self
            .decode_code_block_request_into_with_progress(request, output)?
            .0)
    }

    /// Decode a parsed HT code-block request through this reusable scratch
    /// allocation into caller-owned coefficient output, preserving real cleanup
    /// segment traversal progress for implemented direct cleanup paths.
    pub fn decode_code_block_request_into_with_progress<'out>(
        &mut self,
        request: HtCodeBlockDecodeRequest<'_>,
        output: &'out mut [i32],
    ) -> Result<
        (
            HtCodeBlockDecodeOutcome<'out>,
            Option<HtVlcBlockCleanupSegmentProgress>,
        ),
        HtLayoutError,
    > {
        let (decoded, progress) =
            self.decode_code_block_request_into_with_dispatch_progress(request, output)?;
        Ok((decoded, progress.cleanup_segment_progress))
    }

    fn try_decode_code_block_cleanup_groups_direct_scalar_with_progress(
        &mut self,
        request: HtReusableCodeBlockDecodeRequest<'_>,
        output: &mut [i32],
    ) -> Result<
        Option<(
            HtVlcBlockCleanupSegmentProgress,
            HtVlcCleanupOutputMaterializationProgress,
        )>,
        HtLayoutError,
    > {
        preflight_code_block_cleanup_direct_decode_request(request.request())?;
        let views = request.request().cleanup_pass_segment_views()?;
        if let Some(dispatch) = self.prepared_dispatch? {
            let storage = core::mem::take(&mut self.prepared_magsgn_storage);
            let mut prepared =
                match fast_cleanup::PreparedHtCleanupBlock::new_for_block_with_magsgn_storage(
                    views,
                    request.required(),
                    storage,
                    dispatch,
                ) {
                    Ok(prepared) => prepared,
                    Err((error, storage)) => {
                        self.prepared_magsgn_storage = storage;
                        return Err(error);
                    }
                };
            let result = request
                .scratch_layout()
                .block()
                .try_decode_vlc_cleanup_segment_groups_direct_scalar(
                    &mut prepared,
                    request.request().missing_most_significant_bitplanes(),
                    output,
                );
            self.prepared_magsgn_storage =
                prepared.take_prepared_magsgn_storage().unwrap_or_default();
            return result;
        }
        let mut prepared =
            fast_cleanup::PreparedHtCleanupBlock::new_for_block(views, request.required())?;
        request
            .scratch_layout()
            .block()
            .try_decode_vlc_cleanup_segment_groups_direct_scalar(
                &mut prepared,
                request.request().missing_most_significant_bitplanes(),
                output,
            )
    }

    /// Decode a parsed HT code-block request through this reusable scratch
    /// allocation into caller-owned coefficient output, preserving both
    /// cleanup segment traversal progress and dispatch provenance.
    pub fn decode_code_block_request_into_with_dispatch_progress<'out>(
        &mut self,
        request: HtCodeBlockDecodeRequest<'_>,
        output: &'out mut [i32],
    ) -> Result<
        (
            HtCodeBlockDecodeOutcome<'out>,
            HtCodeBlockDecodeDispatchProgress,
        ),
        HtLayoutError,
    > {
        let request = HtReusableCodeBlockDecodeRequest::new(request, output)?;
        let request_class = classify_code_block_decode_request(request.request());
        if request_class == HtCodeBlockDecodeRequestClass::DirectRefinementPasses {
            let full_request = request.request();
            let cleanup_request = full_request.cleanup_only_decode_request()?;
            let cleanup_request = HtReusableCodeBlockDecodeRequest::new(cleanup_request, output)?;
            let Some((progress, materialization_progress)) = self
                .try_decode_code_block_cleanup_groups_direct_scalar_with_progress(
                    cleanup_request,
                    output,
                )?
            else {
                return Ok((
                    HtCodeBlockDecodeOutcome::PendingBlockDecode,
                    HtCodeBlockDecodeDispatchProgress {
                        request_class,
                        cleanup_segment_progress: None,
                        materialization_progress: None,
                        refinement_pass_progress: None,
                    },
                ));
            };
            let required = request.required();
            if progress.decode.symbol_count != required {
                return Err(HtLayoutError::SizeOverflow);
            }
            let refinement_pass_progress =
                decode_ht_refinement_passes(full_request, &mut output[..required])?;
            return Ok((
                HtCodeBlockDecodeOutcome::Decoded(HtDecodedCodeBlock {
                    active_dimensions: full_request.active_dimensions(),
                    coefficients: &output[..required],
                }),
                HtCodeBlockDecodeDispatchProgress {
                    request_class,
                    cleanup_segment_progress: Some(progress),
                    materialization_progress: Some(materialization_progress),
                    refinement_pass_progress: Some(refinement_pass_progress),
                },
            ));
        }

        let Some((progress, materialization_progress)) =
            self.try_decode_code_block_cleanup_groups_direct_scalar_with_progress(request, output)?
        else {
            return Ok((
                HtCodeBlockDecodeOutcome::PendingBlockDecode,
                HtCodeBlockDecodeDispatchProgress {
                    request_class,
                    cleanup_segment_progress: None,
                    materialization_progress: None,
                    refinement_pass_progress: None,
                },
            ));
        };
        let required = request.required();
        if progress.decode.symbol_count != required {
            return Err(HtLayoutError::SizeOverflow);
        }
        Ok((
            HtCodeBlockDecodeOutcome::Decoded(HtDecodedCodeBlock {
                active_dimensions: request.request().active_dimensions(),
                coefficients: &output[..required],
            }),
            HtCodeBlockDecodeDispatchProgress {
                request_class,
                cleanup_segment_progress: Some(progress),
                materialization_progress: Some(materialization_progress),
                refinement_pass_progress: None,
            },
        ))
    }

