    /// Decode raw cleanup symbols and raw refinement values through this
    /// buffer's reusable coefficient-local storage before materializing
    /// row-major signed coefficient output.
    pub fn decode_raw_cleanup_and_refinement_coefficients_with_reusable_buffers_checked(
        &mut self,
        scratch_layout: HtBlockScratchLayout,
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_stream_bytes: &[u8],
        cleanup_stream: HtCleanupStreamKind,
        magnitude_sign_bits: u8,
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_stream_bytes: &[u8],
        refinement_stream: HtCleanupStreamKind,
        refinement_value_bits: u8,
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let cleanup_config = HtRawCleanupDecodeConfig::new(cleanup_stream, magnitude_sign_bits)?;
        let refinement_config =
            HtRawRefinementValueDecodeConfig::new(refinement_stream, refinement_value_bits)?;
        self.decode_raw_cleanup_and_refinement_coefficients_with_reusable_buffers_config(
            scratch_layout,
            cleanup_stream_layout,
            cleanup_stream_bytes,
            cleanup_config,
            refinement_stream_layout,
            refinement_stream_bytes,
            refinement_config,
            output,
        )
    }

    /// Decode raw cleanup symbols and raw refinement values through this
    /// buffer's reusable coefficient-local storage using validated raw configs.
    pub fn decode_raw_cleanup_and_refinement_coefficients_with_reusable_buffers_config(
        &mut self,
        scratch_layout: HtBlockScratchLayout,
        cleanup_stream_layout: HtCleanupStreamLayout,
        cleanup_stream_bytes: &[u8],
        cleanup_config: HtRawCleanupDecodeConfig,
        refinement_stream_layout: HtCleanupStreamLayout,
        refinement_stream_bytes: &[u8],
        refinement_config: HtRawRefinementValueDecodeConfig,
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let block = scratch_layout.block();
        let required = block.dimensions().coefficient_count();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }
        cleanup_config.check_declared_raw_side_buffer_bits(block, cleanup_stream_layout)?;
        refinement_config
            .check_declared_raw_refinement_value_bits(block, refinement_stream_layout)?;
        let _ = cleanup_stream_layout.split_streams(cleanup_stream_bytes)?;
        let _ = refinement_stream_layout.split_streams(refinement_stream_bytes)?;

        self.ensure_layout(scratch_layout);
        self.ensure_symbol_layout(scratch_layout);
        self.ensure_refinement_value_layout(scratch_layout);

        scratch_layout.decode_raw_cleanup_and_refinement_coefficients_with_buffers_config(
            &mut self.words,
            cleanup_stream_layout,
            cleanup_stream_bytes,
            cleanup_config,
            refinement_stream_layout,
            refinement_stream_bytes,
            refinement_config,
            &mut self.symbols[..required],
            &mut self.refinement_values[..required],
            output,
        )
    }

