    /// Decode raw cleanup symbols, raw refinement values, and raw
    /// magnitude/sign values from one typed composed byte bundle and one
    /// validated raw composed decode plan through this buffer's reusable
    /// coefficient-local storage.
    pub fn decode_raw_cleanup_refinement_and_magnitude_sign_coefficients_with_reusable_stream_bytes_plan(
        &mut self,
        scratch_layout: HtBlockScratchLayout,
        plan: HtRawComposedCoefficientDecodePlan,
        bytes: HtRawComposedStreamBytes<'_>,
        output: &mut [i32],
    ) -> Result<Option<()>, HtLayoutError> {
        let required = HtReusableRawComposedPlaneBufferCoefficientDecodeRequest::preflight(
            scratch_layout,
            plan,
            bytes,
            output,
        )?;
        let buffers = self.prepare_parsed_coefficient_plane_buffers(scratch_layout);
        let plane_request =
            HtReusableRawComposedPlaneBufferCoefficientDecodeRequest::from_preflighted(
                scratch_layout,
                plan,
                bytes,
                buffers,
                required,
            )?;
        let Some((scratch_layout, plan, _required)) = plane_request.decode()? else {
            return Ok(None);
        };

        self.materialize_prepared_parsed_cleanup_refinement_and_magnitude_sign_coefficients(
            scratch_layout,
            plan.config().magnitude_sign().magnitude_sign_bits(),
            output,
        )
    }

