    /// Decode a preflighted cleanup-only code-block by filling reusable Part
    /// 15 side-input prefixes from a parser callback, then materializing
    /// through reusable direct cleanup-output storage.
    ///
    /// This is the explicit parser-backed route for future real Part 15
    /// side-bit/tail syntax. It is separate from the direct group route: the
    /// callback must produce every traversal-order side-input item before
    /// coefficient scratch, context/MEL state, segment cursors, cleanup-output
    /// storage, or caller output are mutated.
    pub fn try_decode_preflighted_code_block_cleanup_part15_parser_side_inputs_with_reusable_state_outputs_and_parser_progress<
        F,
    >(
        &mut self,
        reusable_request: HtReusableCodeBlockCleanupPart15ParserDecodeRequest<'_>,
        parse: F,
        output: &mut [i32],
    ) -> Result<Option<HtPart15VlcCleanupSegmentProgress>, HtLayoutError>
    where
        F: FnMut(
            HtVlcQuadPairGroup,
        ) -> Result<Option<HtVlcLinePairCleanupSideInput>, HtLayoutError>,
    {
        let required = reusable_request.required();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }

        let parser_side_input_snapshot = self
            .try_fill_preflighted_code_block_cleanup_part15_parser_side_input_snapshot(
                reusable_request,
                parse,
            )?;
        if !parser_side_input_snapshot.is_complete() {
            return Ok(None);
        }
        let parser_side_input_counts = parser_side_input_snapshot.written();

        self.try_materialize_preflighted_code_block_cleanup_part15_parser_side_input_counts_with_reusable_state_outputs_and_parser_progress(
            reusable_request,
            parser_side_input_counts,
            output,
        )
    }

