    fn try_materialize_preflighted_code_block_cleanup_part15_parser_side_input_counts_with_reusable_state_outputs_and_parser_progress(
        &mut self,
        reusable_request: HtReusableCodeBlockCleanupPart15ParserDecodeRequest<'_>,
        parser_side_input_counts: HtVlcLinePairCleanupSideInputCounts,
        output: &mut [i32],
    ) -> Result<Option<HtPart15VlcCleanupSegmentProgress>, HtLayoutError> {
        let request = reusable_request.request();
        let scratch_layout = reusable_request.scratch_layout();
        let block = scratch_layout.block();
        let required = reusable_request.required();
        if output.len() < required {
            return Err(HtLayoutError::BufferTooSmall {
                required,
                actual: output.len(),
            });
        }

        self.ensure_layout(scratch_layout);
        self.ensure_vlc_cleanup_output_layout(scratch_layout);
        let required_context_states = reset_reusable_vlc_cleanup_progression_state(
            &mut self.vlc_context_states,
            &mut self.vlc_mel_state,
            scratch_layout,
        );

        let required_side_inputs = block.vlc_cleanup_side_input_counts();
        let part15_side_inputs = HtPart15VlcCleanupSideInputs::from_slices(
            block,
            &self.vlc_quad_side_bits[..required_side_inputs.quad_side_bits],
            &self.vlc_odd_tail_u_values[..required_side_inputs.odd_tail_u_values],
        )?;
        let checked_outcome = HtPart15VlcCleanupSideInputDecodeOutcome::try_new(
            parser_side_input_counts,
            part15_side_inputs,
        )?;
        let mut segment_cursors = request.cleanup_pass_segment_bit_cursors()?;
        let Some(segment) = scratch_layout
            .try_decode_finalized_vlc_cleanup_segment_side_inputs_to_outputs_and_materialize(
                &mut self.words,
                &mut segment_cursors,
                &mut self.vlc_context_states[..required_context_states],
                &mut self.vlc_mel_state,
                checked_outcome.side_inputs().side_inputs(),
                &mut self.vlc_cleanup_outputs[..required],
                request.missing_most_significant_bitplanes(),
                output,
            )?
        else {
            return Ok(None);
        };
        Ok(Some(HtPart15VlcCleanupSegmentProgress::new(
            parser_side_input_counts,
            segment,
        )?))
    }

