    /// Visit every quad group in this line-pair in layout order, replacing its
    /// packed cleanup-context and greater-than-one bits with the callback
    /// result.
    pub fn update_quad_scratch_bit_groups<F>(&mut self, update: F) -> Option<()>
    where
        F: FnMut(HtQuadScratchBits) -> HtQuadScratchBits,
    {
        self.line_pair.update_quad_scratch_bit_groups(update)
    }

    /// Visit every quad group in this line-pair in layout order, allowing the
    /// callback to consume cleanup streams while replacing packed
    /// cleanup-context and greater-than-one bits.
    ///
    /// Returning bits for a different group is rejected so callers cannot
    /// accidentally move state between packed slots.
    pub fn update_quad_scratch_bit_groups_with_parser<F>(&mut self, mut update: F) -> Option<()>
    where
        F: FnMut(&mut Self, HtQuadScratchBits) -> Option<HtQuadScratchBits>,
    {
        for group in self.quad_groups() {
            let current = self.quad_scratch_bits(group)?;
            let updated = update(self, current)?;
            if updated.group != group {
                return None;
            }
            self.set_quad_scratch_bits(
                updated.group,
                updated.cleanup_context_bits,
                updated.gt1_bits,
            )?;
        }
        Some(())
    }

    /// Visit every quad group in this line-pair in layout order, allowing the
    /// callback to consume cleanup streams and propagate typed parser errors
    /// while replacing packed cleanup-context and greater-than-one bits.
    pub fn try_update_quad_scratch_bit_groups_with_parser<F>(
        &mut self,
        mut update: F,
    ) -> Result<Option<()>, HtLayoutError>
    where
        F: FnMut(&mut Self, HtQuadScratchBits) -> Result<Option<HtQuadScratchBits>, HtLayoutError>,
    {
        for group in self.quad_groups() {
            let Some(current) = self.quad_scratch_bits(group) else {
                return Ok(None);
            };
            let Some(updated) = update(self, current)? else {
                return Ok(None);
            };
            if updated.group != group {
                return Ok(None);
            }
            if self
                .set_quad_scratch_bits(
                    updated.group,
                    updated.cleanup_context_bits,
                    updated.gt1_bits,
                )
                .is_none()
            {
                return Ok(None);
            }
        }
        Ok(Some(()))
    }

