    /// Visit every real coefficient in this line-pair in quad traversal order,
    /// allowing the callback to consume cleanup streams while replacing its
    /// packed side-buffer bits.
    ///
    /// Returning bits for a different coefficient is rejected so callers cannot
    /// accidentally move state between packed slots.
    pub fn update_coefficient_scratch_bits_with_parser<F>(&mut self, mut update: F) -> Option<()>
    where
        F: FnMut(&mut Self, HtCoefficientScratchBits) -> Option<HtCoefficientScratchBits>,
    {
        for group in self.quad_groups() {
            for position in group.present_positions() {
                let current = self.coefficient_scratch_bits(position)?;
                let updated = update(self, current)?;
                if updated.position != position {
                    return None;
                }
                self.set_coefficient_scratch_bits(updated)?;
            }
        }
        Some(())
    }

    /// Visit every real coefficient in this line-pair in quad traversal order,
    /// allowing the callback to consume cleanup streams and propagate typed
    /// parser errors while replacing packed side-buffer bits.
    pub fn try_update_coefficient_scratch_bits_with_parser<F>(
        &mut self,
        mut update: F,
    ) -> Result<Option<()>, HtLayoutError>
    where
        F: FnMut(
            &mut Self,
            HtCoefficientScratchBits,
        ) -> Result<Option<HtCoefficientScratchBits>, HtLayoutError>,
    {
        for group in self.quad_groups() {
            for position in group.present_positions() {
                let Some(current) = self.coefficient_scratch_bits(position) else {
                    return Ok(None);
                };
                let Some(updated) = update(self, current)? else {
                    return Ok(None);
                };
                if updated.position != position {
                    return Ok(None);
                }
                if self.set_coefficient_scratch_bits(updated).is_none() {
                    return Ok(None);
                }
            }
        }
        Ok(Some(()))
    }

    /// Decode one raw cleanup significance bit for every real coefficient in
    /// this line-pair, writing packed cleanup-context bits in quad traversal
    /// order and leaving the other side-buffer fields unchanged.
    ///
    /// The caller selects the cleanup stream partition so tests and future
    /// staged parsers can exercise forward/reverse partition routing while the
    /// full HT MEL/VLC cleanup syntax is still being implemented.
    pub fn decode_raw_cleanup_significance_bits_for(
        &mut self,
        stream: HtCleanupStreamKind,
    ) -> Result<Option<()>, HtLayoutError> {
        self.try_update_coefficient_scratch_bits_with_parser(|parser, mut bits| {
            bits.cleanup_context_bit = parser.read_required_bit_for(stream)? != 0;
            Ok(Some(bits))
        })
    }

    /// Decode one raw cleanup greater-than-one bit for every real coefficient
    /// in this line-pair, writing packed greater-than-one bits in quad
    /// traversal order and leaving every other side-buffer field unchanged.
    pub fn decode_raw_cleanup_gt1_bits_for(
        &mut self,
        stream: HtCleanupStreamKind,
    ) -> Result<Option<()>, HtLayoutError> {
        self.try_update_coefficient_scratch_bits_with_parser(|parser, mut bits| {
            bits.gt1_bit = parser.read_required_bit_for(stream)? != 0;
            Ok(Some(bits))
        })
    }

    /// Decode one raw cleanup refinement bit for every real coefficient in
    /// this line-pair, writing packed refinement bits in octet side-buffer
    /// words and leaving every other side-buffer field unchanged.
    pub fn decode_raw_cleanup_refinement_bits_for(
        &mut self,
        stream: HtCleanupStreamKind,
    ) -> Result<Option<()>, HtLayoutError> {
        self.try_update_coefficient_scratch_bits_with_parser(|parser, mut bits| {
            bits.refinement_bit = parser.read_required_bit_for(stream)? != 0;
            Ok(Some(bits))
        })
    }

    /// Decode raw refinement-value words for every real coefficient in this
    /// line-pair, writing per-coefficient refinement side-buffer storage and
    /// leaving every packed side-buffer bit unchanged.
    pub fn decode_raw_refinement_values_for(
        &mut self,
        stream: HtCleanupStreamKind,
        refinement_value_bits: u8,
    ) -> Result<Option<()>, HtLayoutError> {
        if refinement_value_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        self.try_update_coefficient_refinement_values_with_parser(|parser, mut value| {
            value.value = parser.read_required_bits_for(stream, refinement_value_bits)? as u16;
            Ok(Some(value))
        })
    }

    /// Decode raw cleanup side-buffer state for every real coefficient in this
    /// line-pair in one coefficient-order traversal.
    pub fn decode_raw_cleanup_side_buffer_states_for(
        &mut self,
        stream: HtCleanupStreamKind,
        magnitude_sign_bits: u8,
    ) -> Result<Option<()>, HtLayoutError> {
        if magnitude_sign_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        self.try_update_coefficient_side_buffer_states_with_parser(|parser, mut state| {
            state.cleanup_context_bit = parser.read_required_bit_for(stream)? != 0;
            state.gt1_bit = parser.read_required_bit_for(stream)? != 0;
            state.refinement_bit = parser.read_required_bit_for(stream)? != 0;
            state.magnitude_sign_value =
                parser.read_required_bits_for(stream, magnitude_sign_bits)? as u16;
            Ok(Some(state))
        })
    }

    /// Decode one fixed-width raw magnitude/sign word for every real
    /// coefficient in this line-pair, writing row-major coefficient side-buffer
    /// slots in quad traversal order and leaving every other side-buffer field
    /// unchanged.
    pub fn decode_raw_cleanup_magnitude_sign_values_for(
        &mut self,
        stream: HtCleanupStreamKind,
        bits_per_value: u8,
    ) -> Result<Option<()>, HtLayoutError> {
        if bits_per_value > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }
        self.try_update_coefficient_magnitude_sign_values_with_parser(|parser, mut value| {
            value.value = parser.read_required_bits_for(stream, bits_per_value)? as u16;
            Ok(Some(value))
        })
    }

