/// Mutable HT scratch words for one two-row line-pair group.
#[derive(Debug)]
pub struct HtLinePairScratchMut<'a> {
    pub cleanup_contexts: &'a mut [u16],
    pub gt1: &'a mut [u16],
    pub refinement_bits: &'a mut [u16],
    pub refinement: &'a mut [u16],
    pub magnitude_sign: &'a mut [u16],
}

impl HtLinePairScratchMut<'_> {
    /// Borrow this mutable line-pair scratch as read-only grouped scratch.
    pub fn as_read(&self) -> HtLinePairScratch<'_> {
        HtLinePairScratch {
            cleanup_contexts: &self.cleanup_contexts[..],
            gt1: &self.gt1[..],
            refinement_bits: &self.refinement_bits[..],
            refinement: &self.refinement[..],
            magnitude_sign: &self.magnitude_sign[..],
        }
    }

    /// Clear every side-buffer word in this line-pair scratch view.
    pub fn clear(&mut self) {
        self.cleanup_contexts.fill(0);
        self.gt1.fill(0);
        self.refinement_bits.fill(0);
        self.refinement.fill(0);
        self.magnitude_sign.fill(0);
    }

    /// Replace packed side-buffer bits for one coefficient inside this
    /// line-pair, leaving every other coefficient bit untouched.
    pub fn set_coefficient_scratch_bits(
        &mut self,
        line_pair: HtLinePairGroup,
        bits: HtCoefficientScratchBits,
    ) -> Option<()> {
        let position = bits.position;
        let quad_index = line_pair.coefficient_quad_local_index(position)?;
        let octet_index = line_pair.coefficient_octet_local_index(position)?;
        set_masked_bit(
            self.cleanup_contexts.get_mut(quad_index)?,
            position.quad_mask(),
            bits.cleanup_context_bit,
        );
        set_masked_bit(
            self.gt1.get_mut(quad_index)?,
            position.quad_mask(),
            bits.gt1_bit,
        );
        set_masked_bit(
            self.refinement_bits.get_mut(octet_index)?,
            position.octet_mask(),
            bits.refinement_bit,
        );
        Some(())
    }

    /// Replace all coefficient-local side-buffer state inside this line-pair,
    /// leaving every other coefficient bit or value untouched.
    pub fn set_coefficient_side_buffer_state(
        &mut self,
        line_pair: HtLinePairGroup,
        state: HtCoefficientSideBufferState,
    ) -> Option<()> {
        self.set_coefficient_scratch_bits(
            line_pair,
            HtCoefficientScratchBits {
                position: state.position,
                cleanup_context_bit: state.cleanup_context_bit,
                gt1_bit: state.gt1_bit,
                refinement_bit: state.refinement_bit,
            },
        )?;
        self.set_refinement_value(line_pair, state.position, state.refinement_value)?;
        self.set_magnitude_sign_value(line_pair, state.position, state.magnitude_sign_value)
    }

    /// Replace present cleanup-context and greater-than-one bits for one quad
    /// group inside this line-pair, leaving cropped/padding bits untouched.
    pub fn set_quad_scratch_bits(
        &mut self,
        line_pair: HtLinePairGroup,
        group: HtQuadGroup,
        cleanup_context_bits: u16,
        gt1_bits: u16,
    ) -> Option<()> {
        let index = group.line_pair_local_index(line_pair)?;
        let mask = group.present_mask();
        let cleanup_context_word = self.cleanup_contexts.get_mut(index)?;
        let gt1_word = self.gt1.get_mut(index)?;
        *cleanup_context_word = (*cleanup_context_word & !mask) | (cleanup_context_bits & mask);
        *gt1_word = (*gt1_word & !mask) | (gt1_bits & mask);
        Some(())
    }

    /// Replace present cleanup-context bits for one quad group inside this
    /// line-pair, leaving cropped/padding bits untouched.
    pub fn set_cleanup_context_bits_for_quad_group(
        &mut self,
        line_pair: HtLinePairGroup,
        group: HtQuadGroup,
        bits: u16,
    ) -> Option<()> {
        let index = group.line_pair_local_index(line_pair)?;
        let mask = group.present_mask();
        let word = self.cleanup_contexts.get_mut(index)?;
        *word = (*word & !mask) | (bits & mask);
        Some(())
    }

    /// Replace present greater-than-one bits for one quad group inside this
    /// line-pair, leaving cropped/padding bits untouched.
    pub fn set_gt1_bits_for_quad_group(
        &mut self,
        line_pair: HtLinePairGroup,
        group: HtQuadGroup,
        bits: u16,
    ) -> Option<()> {
        let index = group.line_pair_local_index(line_pair)?;
        let mask = group.present_mask();
        let word = self.gt1.get_mut(index)?;
        *word = (*word & !mask) | (bits & mask);
        Some(())
    }

    /// Replace present refinement bits for one octet group inside this
    /// line-pair, leaving cropped/padding bits untouched.
    pub fn set_refinement_bits_for_octet_group(
        &mut self,
        line_pair: HtLinePairGroup,
        group: HtOctetGroup,
        bits: u16,
    ) -> Option<()> {
        let index = group.line_pair_local_index(line_pair)?;
        let mask = group.present_mask();
        let word = self.refinement_bits.get_mut(index)?;
        *word = (*word & !mask) | (bits & mask);
        Some(())
    }

    /// Replace present refinement bits for one octet group inside this
    /// line-pair, leaving cropped/padding bits untouched.
    pub fn set_octet_scratch_bits(
        &mut self,
        line_pair: HtLinePairGroup,
        group: HtOctetGroup,
        bits: u16,
    ) -> Option<()> {
        self.set_refinement_bits_for_octet_group(line_pair, group, bits)
    }

    /// Store a per-coefficient refinement side-buffer word inside this
    /// line-pair.
    pub fn set_refinement_value(
        &mut self,
        line_pair: HtLinePairGroup,
        position: HtCoefficientPosition,
        value: u16,
    ) -> Option<()> {
        let index = line_pair.coefficient_refinement_local_index(position)?;
        let word = self.refinement.get_mut(index)?;
        *word = value;
        Some(())
    }

    /// Store a per-coefficient raw magnitude/sign side-buffer word inside this
    /// line-pair.
    pub fn set_magnitude_sign_value(
        &mut self,
        line_pair: HtLinePairGroup,
        position: HtCoefficientPosition,
        value: u16,
    ) -> Option<()> {
        let index = line_pair.coefficient_refinement_local_index(position)?;
        let word = self.magnitude_sign.get_mut(index)?;
        *word = value;
        Some(())
    }
}

/// Immutable cleanup scratch and packed geometry for one HT line-pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtLinePairDecodeView<'a> {
    pub group: HtLinePairGroup,
    pub scratch: HtLinePairScratch<'a>,
    pub quad_groups: HtQuadGroupIter,
    pub octet_groups: HtOctetGroupIter,
}

impl<'a> HtLinePairDecodeView<'a> {
    /// Current packed side-buffer bits for one coefficient in this line-pair.
    pub fn coefficient_scratch_bits(
        &self,
        position: HtCoefficientPosition,
    ) -> Option<HtCoefficientScratchBits> {
        self.scratch.coefficient_scratch_bits(self.group, position)
    }

    /// Current packed side-buffer bits and refinement value for one
    /// coefficient in this line-pair.
    pub fn coefficient_side_buffer_state(
        &self,
        position: HtCoefficientPosition,
    ) -> Option<HtCoefficientSideBufferState> {
        self.scratch
            .coefficient_side_buffer_state(self.group, position)
    }

    /// Iterate real coefficient positions with their current packed
    /// side-buffer bits in quad traversal order.
    pub fn coefficient_scratch_bit_positions(self) -> HtLinePairCoefficientScratchBitsIter<'a> {
        let remaining = self.quad_groups.map(|group| group.present_count()).sum();
        HtLinePairCoefficientScratchBitsIter {
            line_pair: self.group,
            scratch: self.scratch,
            groups: self.quad_groups,
            positions: None,
            remaining,
        }
    }

    /// Iterate real coefficient positions with their full coefficient-local
    /// side-buffer state in quad traversal order.
    pub fn coefficient_side_buffer_states(self) -> HtLinePairCoefficientSideBufferStateIter<'a> {
        let remaining = self.quad_groups.map(|group| group.present_count()).sum();
        HtLinePairCoefficientSideBufferStateIter {
            line_pair: self.group,
            scratch: self.scratch,
            groups: self.quad_groups,
            positions: None,
            remaining,
        }
    }

    /// Iterate real coefficient positions with their current refinement
    /// side-buffer values in quad traversal order.
    pub fn coefficient_refinement_values(self) -> HtLinePairRefinementValueIter<'a> {
        let remaining = self.quad_groups.map(|group| group.present_count()).sum();
        HtLinePairRefinementValueIter {
            line_pair: self.group,
            scratch: self.scratch,
            groups: self.quad_groups,
            positions: None,
            remaining,
        }
    }

    /// Iterate real coefficient positions with their current raw
    /// magnitude/sign side-buffer values in quad traversal order.
    pub fn coefficient_magnitude_sign_values(self) -> HtLinePairMagnitudeSignValueIter<'a> {
        let remaining = self.quad_groups.map(|group| group.present_count()).sum();
        HtLinePairMagnitudeSignValueIter {
            line_pair: self.group,
            scratch: self.scratch,
            groups: self.quad_groups,
            positions: None,
            remaining,
        }
    }

    /// Present cleanup-context bits for one quad group in this line-pair.
    pub fn cleanup_context_bits_for_quad_group(&self, group: HtQuadGroup) -> Option<u16> {
        self.scratch
            .cleanup_context_bits_for_quad_group(self.group, group)
    }

    /// Present greater-than-one bits for one quad group in this line-pair.
    pub fn gt1_bits_for_quad_group(&self, group: HtQuadGroup) -> Option<u16> {
        self.scratch.gt1_bits_for_quad_group(self.group, group)
    }

    /// Present refinement bits for one octet group in this line-pair.
    pub fn refinement_bits_for_octet_group(&self, group: HtOctetGroup) -> Option<u16> {
        self.scratch
            .refinement_bits_for_octet_group(self.group, group)
    }

    /// Current per-coefficient refinement side-buffer word in this line-pair.
    pub fn refinement_value(&self, position: HtCoefficientPosition) -> Option<u16> {
        self.scratch.refinement_value(self.group, position)
    }

    /// Current per-coefficient raw magnitude/sign side-buffer word in this
    /// line-pair.
    pub fn magnitude_sign_value(&self, position: HtCoefficientPosition) -> Option<u16> {
        self.scratch.magnitude_sign_value(self.group, position)
    }

    /// Present cleanup-context and greater-than-one bits for one quad group in
    /// this line-pair.
    pub fn quad_scratch_bits(&self, group: HtQuadGroup) -> Option<HtQuadScratchBits> {
        self.scratch.quad_scratch_bits(self.group, group)
    }

    /// Present refinement bits for one octet group in this line-pair.
    pub fn octet_scratch_bits(&self, group: HtOctetGroup) -> Option<HtOctetScratchBits> {
        self.scratch.octet_scratch_bits(self.group, group)
    }

    /// Iterate quad groups with their current cleanup-context and
    /// greater-than-one scratch bits.
    pub fn quad_scratch_bit_groups(self) -> HtQuadScratchBitsIter<'a> {
        HtQuadScratchBitsIter {
            line_pair: self.group,
            scratch: self.scratch,
            groups: self.quad_groups,
        }
    }

    /// Iterate octet groups with their current refinement scratch bits.
    pub fn octet_scratch_bit_groups(self) -> HtOctetScratchBitsIter<'a> {
        HtOctetScratchBitsIter {
            line_pair: self.group,
            scratch: self.scratch,
            groups: self.octet_groups,
        }
    }

    /// Materialize this line-pair's current raw cleanup side-buffer state into
    /// a row-major signed coefficient plane.
    pub fn materialize_raw_cleanup_coefficients(
        self,
        output: &mut [i32],
        magnitude_sign_bits: u8,
    ) -> Result<Option<()>, HtLayoutError> {
        if magnitude_sign_bits > u16::BITS as u8 {
            return Err(HtLayoutError::SizeOverflow);
        }

        for state in self.coefficient_side_buffer_states() {
            let Some(coefficient) = output.get_mut(state.position.refinement_slot) else {
                return Ok(None);
            };
            *coefficient = raw_cleanup_coefficient_from_state(state, magnitude_sign_bits)?;
        }
        Ok(Some(()))
    }
}

fn raw_cleanup_coefficient_from_state(
    state: HtCoefficientSideBufferState,
    magnitude_sign_bits: u8,
) -> Result<i32, HtLayoutError> {
    if magnitude_sign_bits > u16::BITS as u8 {
        return Err(HtLayoutError::SizeOverflow);
    }
    if !state.cleanup_context_bit || magnitude_sign_bits == 0 {
        return Ok(0);
    }

    let sign_bit = 1_u16 << (magnitude_sign_bits - 1);
    let magnitude = i32::from(state.magnitude_sign_value & (sign_bit - 1));
    if state.magnitude_sign_value & sign_bit == 0 {
        Ok(magnitude)
    } else {
        Ok(-magnitude)
    }
}

