fn decode_required_vlc_quad_cleanup_symbols_from_cursors(
    cursors: &mut HtCleanupStreamBitCursors<'_>,
    table: HtVlcLookupTable<'_>,
    context: HtVlcContext,
    zero_context_mel_event: Option<bool>,
    group: HtQuadGroup,
    u_value: u16,
    magnitude_sign_stream: HtCleanupStreamKind,
    side_bits: HtVlcQuadCleanupSideBits,
    output: &mut [HtCleanupCoefficientSymbol],
) -> Result<Option<usize>, HtLayoutError> {
    let codeword = decode_required_vlc_quad_codeword_from_cursor(
        &mut cursors.vlc,
        table,
        context,
        zero_context_mel_event,
    )?;
    decode_required_vlc_quad_cleanup_symbols_from_codeword(
        cursors,
        codeword,
        group,
        u_value,
        magnitude_sign_stream,
        side_bits,
        output,
    )
}

fn decode_required_vlc_quad_cleanup_symbols_from_codeword(
    cursors: &mut HtCleanupStreamBitCursors<'_>,
    codeword: HtVlcQuadCodeword,
    group: HtQuadGroup,
    u_value: u16,
    magnitude_sign_stream: HtCleanupStreamKind,
    side_bits: HtVlcQuadCleanupSideBits,
    output: &mut [HtCleanupCoefficientSymbol],
) -> Result<Option<usize>, HtLayoutError> {
    if side_bits.check_within_quad(group).is_none() {
        return Ok(None);
    }
    let required = group.present_count();
    if output.len() < required {
        return Err(HtLayoutError::BufferTooSmall {
            required,
            actual: output.len(),
        });
    }
    let Some(seed_position) = group.present_positions().next() else {
        return Ok(Some(0));
    };

    let seed_output = HtVlcCleanupCoefficientOutput {
        position: seed_position,
        significant: false,
        magnitude_sign_bits: 0,
        magnitude_sign_value: 0,
        embedded_magnitude_bit: false,
        magnitude_exponent_reduction: false,
    };
    let mut vlc_outputs = [seed_output; 4];
    let Some(count) = decode_required_vlc_quad_cleanup_outputs_from_codeword(
        cursors,
        codeword,
        group,
        u_value,
        magnitude_sign_stream,
        &mut vlc_outputs,
    )?
    else {
        return Ok(None);
    };

    let seed_symbol = HtCleanupCoefficientSymbol {
        position: seed_position,
        cleanup_context_bit: false,
        gt1_bit: false,
        refinement_bit: false,
        magnitude_sign_value: 0,
    };
    let mut symbols = [seed_symbol; 4];
    for index in 0..count {
        let Some(symbol) =
            vlc_outputs[index].to_cleanup_coefficient_symbol_with_side_bits(side_bits)
        else {
            return Ok(None);
        };
        symbols[index] = symbol;
    }
    output[..count].copy_from_slice(&symbols[..count]);
    Ok(Some(count))
}

