fn skip_required_vlc_bits_from_cursor(
    cursor: &mut HtForwardBitCursor<'_>,
    count: u8,
) -> Result<(), HtLayoutError> {
    let requested_bits = usize::from(count);
    let remaining_bits = cursor.remaining_bits();
    if count > 32 || requested_bits > remaining_bits {
        return Err(HtLayoutError::StreamBitReadUnavailable {
            stream: HtCleanupStreamKind::Vlc,
            requested_bits,
            remaining_bits,
        });
    }

    cursor
        .skip_bits(count)
        .ok_or(HtLayoutError::StreamBitReadUnavailable {
            stream: HtCleanupStreamKind::Vlc,
            requested_bits,
            remaining_bits: cursor.remaining_bits(),
        })
}

/// Forward byte cursor used by HT cleanup, MEL, and VLC stream scaffolding.
#[derive(Debug, Clone)]
pub struct HtForwardByteCursor<'a> {
    bytes: &'a [u8],
    offset: usize,
}

impl<'a> HtForwardByteCursor<'a> {
    /// Start reading at the first byte of the stream.
    pub fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, offset: 0 }
    }

    /// Number of bytes already returned by this cursor.
    pub fn consumed(&self) -> usize {
        self.offset
    }

    /// Number of unread bytes left in this cursor.
    pub fn remaining(&self) -> usize {
        self.bytes.len() - self.offset
    }

    /// Return the next byte from the front of the stream.
    pub fn read_byte(&mut self) -> Option<u8> {
        let byte = self.bytes.get(self.offset).copied()?;
        self.offset += 1;
        Some(byte)
    }
}

/// MSB-first bit cursor over a forward HT stream.
#[derive(Debug, Clone)]
pub struct HtForwardBitCursor<'a> {
    bytes: &'a [u8],
    byte_offset: usize,
    current: u8,
    bits_remaining_in_current: u8,
    magnitude_sign_current_data_bits: u8,
    magnitude_sign_virtual_padding: bool,
}

impl<'a> HtForwardBitCursor<'a> {
    /// Start reading bits from the first byte of the stream.
    pub fn new(bytes: &'a [u8]) -> Self {
        Self {
            bytes,
            byte_offset: 0,
            current: 0,
            bits_remaining_in_current: 0,
            magnitude_sign_current_data_bits: 8,
            magnitude_sign_virtual_padding: false,
        }
    }

    /// Number of bits already returned by this cursor.
    pub fn consumed_bits(&self) -> usize {
        if self.magnitude_sign_virtual_padding {
            return self.bytes.len() * 8;
        }
        self.byte_offset * 8 - usize::from(self.bits_remaining_in_current)
    }

    /// Number of stream bytes touched by this cursor.
    pub fn consumed_bytes(&self) -> usize {
        self.consumed_bits().div_ceil(8)
    }

    /// Number of unread bits left in this cursor.
    pub fn remaining_bits(&self) -> usize {
        if self.magnitude_sign_virtual_padding {
            return 0;
        }
        (self.bytes.len() - self.byte_offset) * 8 + usize::from(self.bits_remaining_in_current)
    }

    /// Number of fully unread stream bytes left in this cursor.
    pub fn remaining_bytes(&self) -> usize {
        self.remaining_bits() / 8
    }

    /// True when the next read starts at a byte boundary.
    pub fn is_byte_aligned(&self) -> bool {
        self.bits_remaining_in_current == 0
    }

    /// Discard any buffered bits from the current byte so the next read starts
    /// at the next stream byte.
    pub fn align_to_byte(&mut self) {
        self.bits_remaining_in_current = 0;
    }

    /// Return the next whole byte when the cursor is byte-aligned.
    pub fn read_aligned_byte(&mut self) -> Option<u8> {
        if !self.is_byte_aligned() {
            return None;
        }
        let byte = *self.bytes.get(self.byte_offset)?;
        self.byte_offset += 1;
        Some(byte)
    }

    /// Return the next bit, reading the most-significant bit of each byte first.
    pub fn read_bit(&mut self) -> Option<u8> {
        if self.bits_remaining_in_current == 0 {
            self.current = *self.bytes.get(self.byte_offset)?;
            self.byte_offset += 1;
            self.bits_remaining_in_current = 8;
        }
        self.bits_remaining_in_current -= 1;
        Some((self.current >> self.bits_remaining_in_current) & 1)
    }

    /// Return up to 32 bits, packed MSB-first into the low bits of the result.
    pub fn read_bits(&mut self, count: u8) -> Option<u32> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut count = count;
        let mut value = 0_u32;

        while count != 0 {
            if self.bits_remaining_in_current == 0 {
                self.current = *self.bytes.get(self.byte_offset)?;
                self.byte_offset += 1;
                self.bits_remaining_in_current = 8;
            }
            let take = self.bits_remaining_in_current.min(count);
            let shift = self.bits_remaining_in_current - take;
            let mask = low_bits_mask(take);
            let chunk = (self.current >> shift) & mask;
            value = (value << take) | u32::from(chunk);
            self.bits_remaining_in_current -= take;
            count -= take;
        }

        Some(value)
    }

    /// Return up to 32 bits, reading each byte LSB-first and packing the first
    /// consumed bit into bit 0 of the result.
    pub fn read_lsb_bits(&mut self, count: u8) -> Option<u32> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut value = 0_u32;
        for shift in 0..count {
            if self.bits_remaining_in_current == 0 {
                self.current = *self.bytes.get(self.byte_offset)?;
                self.byte_offset += 1;
                self.bits_remaining_in_current = 8;
            }
            let consumed_in_current = 8 - self.bits_remaining_in_current;
            value |= u32::from((self.current >> consumed_in_current) & 1) << shift;
            self.bits_remaining_in_current -= 1;
        }
        Some(value)
    }

    /// Return MagSgn bits in LSB-first order while applying HT cleanup byte
    /// stuffing. A byte immediately following `0xff` contributes seven data
    /// bits; its most-significant bit is not part of the MagSgn bitstream.
    pub fn read_magnitude_sign_lsb_bits(&mut self, count: u8) -> Option<u32> {
        if count > 32 {
            return None;
        }
        let mut value = 0_u32;
        for shift in 0..count {
            if self.bits_remaining_in_current == 0 {
                let follows_ff = self.current == 0xff
                    && (self.byte_offset != 0 || self.magnitude_sign_virtual_padding);
                if let Some(&byte) = self.bytes.get(self.byte_offset) {
                    self.current = byte;
                    self.byte_offset += 1;
                } else {
                    // Annex F defines an exhausted MagSgn stream as an
                    // unbounded sequence of 0xff fill bytes.
                    self.current = 0xff;
                    self.magnitude_sign_virtual_padding = true;
                }
                self.magnitude_sign_current_data_bits = if follows_ff { 7 } else { 8 };
                self.bits_remaining_in_current = self.magnitude_sign_current_data_bits;
            }
            let consumed_in_current =
                self.magnitude_sign_current_data_bits - self.bits_remaining_in_current;
            value |= u32::from((self.current >> consumed_in_current) & 1) << shift;
            self.bits_remaining_in_current -= 1;
        }
        Some(value)
    }

    /// Inspect up to 32 upcoming bits without advancing the cursor.
    pub fn peek_bits(&self, count: u8) -> Option<u32> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut count = count;
        let mut value = 0_u32;
        let mut byte_offset = self.byte_offset;
        let mut current = self.current;
        let mut bits_remaining_in_current = self.bits_remaining_in_current;

        while count != 0 {
            if bits_remaining_in_current == 0 {
                current = *self.bytes.get(byte_offset)?;
                byte_offset += 1;
                bits_remaining_in_current = 8;
            }
            let take = bits_remaining_in_current.min(count);
            let shift = bits_remaining_in_current - take;
            let mask = low_bits_mask(take);
            let chunk = (current >> shift) & mask;
            value = (value << take) | u32::from(chunk);
            bits_remaining_in_current -= take;
            count -= take;
        }

        Some(value)
    }

    /// Advance past up to 32 bits without returning their value.
    pub fn skip_bits(&mut self, count: u8) -> Option<()> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut count = count;
        let current_skip = self.bits_remaining_in_current.min(count);
        self.bits_remaining_in_current -= current_skip;
        count -= current_skip;
        if count == 0 {
            return Some(());
        }

        let whole_bytes = usize::from(count / 8);
        self.byte_offset += whole_bytes;
        count %= 8;
        if count != 0 {
            self.current = *self.bytes.get(self.byte_offset)?;
            self.byte_offset += 1;
            self.bits_remaining_in_current = 8 - count;
        }
        Some(())
    }
}

/// Reverse byte cursor used by HT cleanup reverse-stream scaffolding.
#[derive(Debug, Clone)]
pub struct HtReverseByteCursor<'a> {
    bytes: &'a [u8],
    remaining: usize,
}

impl<'a> HtReverseByteCursor<'a> {
    /// Start reading at the last byte of the stream.
    pub fn new(bytes: &'a [u8]) -> Self {
        Self {
            bytes,
            remaining: bytes.len(),
        }
    }

    /// Number of bytes already returned by this cursor.
    pub fn consumed(&self) -> usize {
        self.bytes.len() - self.remaining
    }

    /// Number of unread bytes left in this cursor.
    pub fn remaining(&self) -> usize {
        self.remaining
    }

    /// Return the next byte from the back of the stream.
    pub fn read_byte(&mut self) -> Option<u8> {
        self.remaining = self.remaining.checked_sub(1)?;
        Some(self.bytes[self.remaining])
    }
}

/// MSB-first bit cursor over a reverse HT stream.
#[derive(Debug, Clone)]
pub struct HtReverseBitCursor<'a> {
    bytes: &'a [u8],
    remaining_bytes: usize,
    current: u8,
    bits_remaining_in_current: u8,
}

impl<'a> HtReverseBitCursor<'a> {
    /// Start reading bits from the last byte of the stream.
    pub fn new(bytes: &'a [u8]) -> Self {
        Self {
            bytes,
            remaining_bytes: bytes.len(),
            current: 0,
            bits_remaining_in_current: 0,
        }
    }

    /// Number of bits already returned by this cursor.
    pub fn consumed_bits(&self) -> usize {
        (self.bytes.len() - self.remaining_bytes) * 8 - usize::from(self.bits_remaining_in_current)
    }

    /// Number of stream bytes touched by this cursor.
    pub fn consumed_bytes(&self) -> usize {
        self.consumed_bits().div_ceil(8)
    }

    /// Number of unread bits left in this cursor.
    pub fn remaining_bits(&self) -> usize {
        self.remaining_bytes * 8 + usize::from(self.bits_remaining_in_current)
    }

    /// Number of fully unread stream bytes left in this cursor.
    pub fn remaining_bytes(&self) -> usize {
        self.remaining_bits() / 8
    }

    /// True when the next read starts at a byte boundary.
    pub fn is_byte_aligned(&self) -> bool {
        self.bits_remaining_in_current == 0
    }

    /// Discard any buffered bits from the current byte so the next read starts
    /// at the next reverse stream byte.
    pub fn align_to_byte(&mut self) {
        self.bits_remaining_in_current = 0;
    }

    /// Return the next whole byte when the reverse cursor is byte-aligned.
    pub fn read_aligned_byte(&mut self) -> Option<u8> {
        if !self.is_byte_aligned() {
            return None;
        }
        self.remaining_bytes = self.remaining_bytes.checked_sub(1)?;
        Some(self.bytes[self.remaining_bytes])
    }

    /// Return the next bit, reading stream bytes from back to front and reading
    /// the most-significant bit of each byte first.
    pub fn read_bit(&mut self) -> Option<u8> {
        if self.bits_remaining_in_current == 0 {
            self.remaining_bytes = self.remaining_bytes.checked_sub(1)?;
            self.current = self.bytes[self.remaining_bytes];
            self.bits_remaining_in_current = 8;
        }
        self.bits_remaining_in_current -= 1;
        Some((self.current >> self.bits_remaining_in_current) & 1)
    }

    /// Return up to 32 bits, packed MSB-first into the low bits of the result.
    pub fn read_bits(&mut self, count: u8) -> Option<u32> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut count = count;
        let mut value = 0_u32;

        while count != 0 {
            if self.bits_remaining_in_current == 0 {
                self.remaining_bytes = self.remaining_bytes.checked_sub(1)?;
                self.current = self.bytes[self.remaining_bytes];
                self.bits_remaining_in_current = 8;
            }
            let take = self.bits_remaining_in_current.min(count);
            let shift = self.bits_remaining_in_current - take;
            let mask = low_bits_mask(take);
            let chunk = (self.current >> shift) & mask;
            value = (value << take) | u32::from(chunk);
            self.bits_remaining_in_current -= take;
            count -= take;
        }

        Some(value)
    }

    /// Inspect up to 32 upcoming bits without advancing the cursor.
    pub fn peek_bits(&self, count: u8) -> Option<u32> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut count = count;
        let mut value = 0_u32;
        let mut remaining_bytes = self.remaining_bytes;
        let mut current = self.current;
        let mut bits_remaining_in_current = self.bits_remaining_in_current;

        while count != 0 {
            if bits_remaining_in_current == 0 {
                remaining_bytes = remaining_bytes.checked_sub(1)?;
                current = self.bytes[remaining_bytes];
                bits_remaining_in_current = 8;
            }
            let take = bits_remaining_in_current.min(count);
            let shift = bits_remaining_in_current - take;
            let mask = low_bits_mask(take);
            let chunk = (current >> shift) & mask;
            value = (value << take) | u32::from(chunk);
            bits_remaining_in_current -= take;
            count -= take;
        }

        Some(value)
    }

    /// Advance past up to 32 bits without returning their value.
    pub fn skip_bits(&mut self, count: u8) -> Option<()> {
        if count > 32 || self.remaining_bits() < usize::from(count) {
            return None;
        }
        let mut count = count;
        let current_skip = self.bits_remaining_in_current.min(count);
        self.bits_remaining_in_current -= current_skip;
        count -= current_skip;
        if count == 0 {
            return Some(());
        }

        let whole_bytes = usize::from(count / 8);
        self.remaining_bytes -= whole_bytes;
        count %= 8;
        if count != 0 {
            self.remaining_bytes = self.remaining_bytes.checked_sub(1)?;
            self.current = self.bytes[self.remaining_bytes];
            self.bits_remaining_in_current = 8 - count;
        }
        Some(())
    }
}

fn checked_add(lhs: usize, rhs: usize) -> Result<usize, HtLayoutError> {
    lhs.checked_add(rhs).ok_or(HtLayoutError::SizeOverflow)
}

fn checked_mul(lhs: usize, rhs: usize) -> Result<usize, HtLayoutError> {
    lhs.checked_mul(rhs).ok_or(HtLayoutError::SizeOverflow)
}

const LOW_BITS_MASKS: [u8; 9] = [0, 1, 3, 7, 15, 31, 63, 127, 255];

fn low_bits_mask(count: u8) -> u8 {
    LOW_BITS_MASKS[usize::from(count)]
}

fn range_slice(bytes: &[u8], range: HtByteRange) -> Result<&[u8], HtLayoutError> {
    let end = checked_add(range.offset, range.len)?;
    bytes
        .get(range.offset..end)
        .ok_or(HtLayoutError::BufferTooSmall {
            required: end,
            actual: bytes.len(),
        })
}
